/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20191021-10","meetingId":"r01-cm10","date":"2019年10月21日","dateIso":"2019-10-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"大倉委員","kind":"意見","question":"別紙に配付しております音声認識アプリケーション運用について、資料No.５にまとめましたので、そちらの朗読をもって説明にかえします。〔資料朗読〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"大倉委員","kind":"確認","question":"メールの送信先は事務局に届けているアドレスを考えておりますが、改めて各議員に対して確認をする予定です。以上、２点についてご検討のほど、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"幾つか確認をさせていただきたいのですが、３番の「対象の会議」のところで、認識度というのは変わるのでしょうかということがまず１点。その２点を確認させてください。","respondent":"米田区議会事務局長","answer":"拾う音の質が相当変わってまいりますので、あくまでもこちらのＱＲコードを通したもののほうが、より精度が高まるという形かと考えています。今、ＩＣＴ推進会議の中で話し合われている中では、特段の提供は行わないということで考えているところです。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました。ということは、これは基本的には傍聴者のためのものであって、議員のものではないという考え方での運用ということでよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"議員が何らかの理由で本会議場で使いたいとする場合は、システムとしてはまずできるのか、できないのか。この運用ルールにのっとるとどういう取り扱いになるのか、ちょっとそこだけは確認させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"大倉委員","kind":"意見","question":"それについては、ＩＣＴ推進会議と別の場での会議が必要になるかなというところです。ＩＣＴ推進会議のほうでの議論でなく、ほかの場での議論になるかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"}]},{"id":"topic-02","title":"議長会等の報告","agenda":"議長会等の報告","exchanges":[{"speaker":"渡部委員","kind":"提案","question":"今、議員連盟の提案、説明を議長からいただきました。品川区としてももうこの６年間ぐらいでしょうか、またそれぞれ個々の議員にどのような形で参加するかというのを諮らせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"オリンピック・パラリンピック推進特別委員会がさまざまやった中で、気運醸成を進めていただきたいので、ぜひお願いします。ただ１点だけ確認ですけれども、長期にわたって続けるのかどうか、そこだけ確認させてください。","respondent":"渡辺議長","answer":"レガシーと言われるように、終わってすぐ閉じてしまうのではなくて、日常の区民活動に生かせるかというのが宿題だと思っています。やはり次の改選期、私どもの議連ですから、改選期まで今年を含めて４年間の活動期間は担保したいなというのが希望であります。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"個人的な感想ですが、また特別委員会も数年にわたって設置してきたということもありますので、議会として応援をするという趣旨は賛同するところです。会派のほうに持ち帰りたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"提案","question":"今、ご提案があったので、会派に持ち帰って検討したいと思いますが、説明を聞く限り、よい提案だと受けとめております。支える、学ぶという視点で継続していくことは大事な視点なのかなと思いますので、一言添えさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"これで区議会が出ていってしまうと、それぞれが何か干渉してしまうのではないかなと思うのですけれども、その辺どうなのかなという疑問は感じます。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"提案","question":"先ほど聞き忘れました。準じてということなのですが、これは別に議長のご提案の想定の中では、例えば入りたければ全部入ってもいいという考え方か尋ねました。","respondent":"渡辺議長","answer":"願わくばお１人の議員が３つ入られていいのだという前提で、３競技とも応援するよと言っていただけるのがベストな形かなと考えています。それぞれ活動が違ってくるので、それぞれというふうに。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201447?Template=document&Id=5332#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":18099,"voices":65}},{"id":"r01-20191111-6","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"区民委員会","time":"午後 １時００分～午後 ３時５２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"第２０回 品川区中学生の主張大会","agenda":"第２０回 品川区中学生の主張大会","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"中学生の主張大会についてですけれども、行ける方というのは一般の方でもいいのですか。一般の方はなしで、あくまでも地区委員、中学校、義務教育学校の関係者のみということか尋ねました。","respondent":"川島地域活動課長","answer":"一般の方にお声をかけるというよりも、関係者の方、今お話しされました地区委員、それからＰＴＡ関係者の方に、会を通じましてこちらから出席依頼をしているというものです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"私、その中で、この主張大会がとてもすばらしいものだとお聞きしているのですね。一般の方も、そういった部分でも少し広く聞いてもらえるような場になればいいかなとは思っていますが、そこら辺を。","respondent":"川島地域活動課長","answer":"今のお話も踏まえまして、次回以降の参考にさせていただければと思います。","id":"exchange-002"}]},{"id":"topic-02","title":"総合区民会館（きゅりあん）の大規模改修に伴う休館予定","agenda":"総合区民会館（きゅりあん）の大規模改修に伴う休館予定","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"私たちはそれでも撤回を求めていっている立場なのですが、きゅりあんというのは非常に被害を受ける施設になると思うのです。そういうことを区としては検討なさった、あるいはきゅりあんに対する影響をお調べになられたのか尋ねました。","respondent":"鈴木（真）委員長","answer":"建設委員会の所管になってくると思うので、答えられる部分で答えてください。基本は、そういった問題は区民委員会ではなくて建設委員会での取り扱いになりますので。","id":"exchange-003"},{"speaker":"藤原委員","kind":"確認","question":"確認なのですけれども、これは１年ぐらいは全館休館にしてしまうということですよね。例えば８階の大ホールで工事をやっていても、きゅりあんという意味で全館休館にしてしまうのですかということがまず質問です。","respondent":"古巻文化観光課長","answer":"工事の最初の１年間につきましては全館休館、大ホールは工事していますけれども、ほかのイベントホール等は使えるような状態で開館をしていきたいという流れで考えております。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"ということは、文化振興事業団に委託していますが、あそこの２階にきゅりあんの受付がありますよね。この１年間はまるきり閉館してしまうわけですから、閉館しているわけですから、きゅりあんに関してはどうなるのか尋ねました。","respondent":"古巻文化観光課長","answer":"そういったご案内の業務については継続してやっていく予定ですし、そのあたりで文化振興事業団も含めて、業務は若干残っていく。そのあたりは今後、しっかり適正に運営ができるような形で協議をしていきたい、連携していきたいと考えております。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"大体いつぐらいになっていくという大きな予定を今わかる範囲で教えていただきたいのと、これは改めて確認なのですけれども。まだ予定だからわかりませんというのであるならば、ウオシュレットにしていただきたいということを要望したいのですけれども。","respondent":"古巻文化観光課長","answer":"それから大体の予定ということで言いますと、来年度実施設計をしていくという予定でおりますので、しっかり実施設計をしていくというところで。今のところ、そのようなスケジュールで進めているところです。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問・要望","question":"代替施設というのは選別が難しいところもあるのかなと思うのですけれども、例えば現時点でもしそういうところが決まっていたら教えてほしいなと。大ホールを使いたい、小ホールを使いたいという方々にはこういうところをご案内するとかいうのがあったら、教えていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"木村委員","kind":"意見","question":"１年間かけてやるわけですけれども、また、来場者がいろいろと便利になるようなものに変えようという計画はあるのかどうかとの意見を述べました。","respondent":"古巻文化観光課長","answer":"こちらにエレベーターを設置して、なるべく利用者の利便性向上ということも含めて考えていきたいと思いますけれども、できる範囲でやっていきたいと考えています。","id":"exchange-008"},{"speaker":"木村委員","kind":"質問","question":"見る側としては映画館もそういう会場も同じ役目なわけですから、来場者がリラックスできるような方向でお願いしたいなと思っていますが、お考えだけ説明を求めました。","respondent":"古巻文化観光課長","answer":"今、委員からご指摘いただいたとおり、利用者に対してサービス向上につながるような、改修の計画、来年度、実施設計になりますので、そういった中で十分に考えていきたい、やっていきたいと考えております。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"それはなぜかとお聞きしたのですが、実は太鼓の振動で、波長が合うというのですか、建物自体が揺れてしまうと、そんな話を聞いたのです。さっき課長も言いましたけれども、太鼓を使えるように補強していただくなど、そういった修繕の内容も踏まえて考えていただけたらなと思います。","respondent":"古巻文化観光課長","answer":"今現在この場ではお話ができないので、そういったお声もあるということで、設計の中で意見として伝えていきます。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"１点だけ伺いたいのですが、こちら、１年間休館されている間、きゅりあんで働いている方々の仕事であったり雇用の状況がどうなるのか。そちらについて伺いたいです。","respondent":"古巻文化観光課長","answer":"周知等をご案内の窓口で対応していただく形になろうかと思いますし、また、基本的には残っていただくような流れにはなろうかと思います。細かいところについてはこれから文化振興事業団で検討していくことになろうかと思いますので…","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問・要望","question":"必ずそれを求めていくことができるのか、それとも先方に任せているので、そこに関しては関与できないのかどうか。今働いている方々の雇用は必ず確保していただきたいと思うのですけれども、そちらに関して、情報がわかる範囲で説明を求めました。","respondent":"古巻文化観光課長","answer":"別の施設も、そちらの仕事もあるので、事務機能として仕事がなくなるわけではないということで説明させていただいたという内容です。雇用の継続ということにつきましては、区としてもなるべく雇用が継続できるような形は考えるというか、しっかり雇用を。","id":"exchange-012"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"改修内容で確認を何点かさせてほしいと求めました。そこを確認させてほしいと求めました。","respondent":"古巻文化観光課長","answer":"エレベーターにつきましては、ホールの中に入って、多分階段の近辺になろうかと思うのですけれども、設置する予定です。今のところ検討は……、恐らくエスカレーターの設置ではなく、エレベーターでないと設置が難しいという判断だったと考えております。","id":"exchange-013"},{"speaker":"こんの副委員長","kind":"質問","question":"エレベーターの考え方ですが、すいません、そうすると、場内に入って、ホールに入ってすぐの階段のところにつけるイメージなのですか。そこを、ごめんなさい、細かいですが。","respondent":"古巻文化観光課長","answer":"おおよそそのあたりのイメージで設計を考えているようです。","id":"exchange-014"},{"speaker":"こんの副委員長","kind":"意見","question":"ピロティから２階の一番上の席のほうまで上がる階段は、中央階段でいいのですけれども、実は利用者の方からの声なのです。どこまでどうするかというのはあると思うのですが、お届けさせていただきながら、ご検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/776686?Template=document&Id=2850#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":12458,"voices":60}},{"id":"r01-20191111-7","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"厚生委員会","time":"午後 １時００分～午後 ６時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を82件整理しています。","topics":[{"id":"topic-01","title":"令和元年陳情第４３号 高齢者への補聴器購入費用の助成を求める陳情","agenda":"令和元年陳情第４３号 高齢者への補聴器購入費用の助成を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこの加齢性難聴を課題として捉えて対応していくということが、区としても求められているのではないかなと思います。加齢性難聴に対しての区の認識と、課題と捉えることについてはどう考えられているのかということについて、まずお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"どのポイントでどういう形で補助をすれば一番効果的なのかというのは、なかなか見極めが難しいのかなと考えております。それからそれを使われるであろう方の実態といったものの整合性といいますか組み合わせが、一つ大きな課題になるのではないのかと認識しております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ私は、そして生活の質そのものをどう変えていくのかというあたりも、区としてもつかんでいただきたいなという思いがしています。こういうものを、区としてどう受けとめられているのか、その点についてもお聞かせいただきたい。","respondent":"大串福祉計画課長","answer":"確かに認知症、関連性が一定あるのかなとは認識しています。先ほども申し上げましたが、そういった視点も含め、調査、検討させていただければと考えているところです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"把握していくというところでは、具体的にどういう形で実態をつかんでいくということを考えられているのかというのをお聞かせいただきたい。そこのところは区としてもやはり取り組むことが必要なのではないかなと思いますが、その点はいかがか尋ねました。","respondent":"大串福祉計画課長","answer":"専門家の意見、知見というのは非常に大きなところだというふうには認識しております。そうしたところを踏まえた上で検討を重ねていきたいと考えております。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"補聴器の早期使用の点についても、区としてはさまざまな意見があるという考え方ですか。だから、補聴器を早期に着けるということがとても大事なのだというところでは、認識は同じということでよろしいか尋ねました。","respondent":"大串福祉計画課長","answer":"そうした意味では、予防の観点、ご本人のお気持ち、あるいは着ける、着けないといったご判断も大きな問題になってこようかと考えています。そういったところを含めて、総合的に判断させていただければと考えております。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、そこのところは認識を一致させていただきたいなと思います。そこのところでは一致しているということで、よろしいか尋ねました。","respondent":"大串福祉計画課長","answer":"今おっしゃっていただいたことも含めて、総合的に判断していきたいと思います。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当にこれは耳鼻科の先生もとても強調していることです。早期補聴器の使用がいいのかどうなのかも総合的に判断するということになると、そこら辺のところをお聞かせいただくというのはできないか尋ねました。","respondent":"大串福祉計画課長","answer":"再三申し上げていますように、早期がいいのか、あるいはもう少し進んだ段階でいいのかといったところも含めて、総合的に判断していきたいと考えています。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところはぜひとも認識していただきたいと、強く要望しておきたいと思います。実態をつかむというところでは、どういうふうにやっていくのかということもお願いしたいと思います。","respondent":"大串福祉計画課長","answer":"専門医のご意見等、それから実際使っている方がどれぐらいいるかといったところも含めて、実態把握に努めていきたいと思っています。そうした中で、どのような形で助成といいますか補助することが一番効果的なのかといったところについて…","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"もし品川区がそういう補助制度をつくるとしたら、その包括補助で２分の１を都が補助する仕組みがあるということです。もし品川区が購入費補助を行うということになれば、この東京都の包括補助が使えるのではないかなと思いますが、その点についても説明を求めました。","respondent":"大串福祉計画課長","answer":"補助をするかどうかということを検討します。その上で特定財源等見込まれるものがあれば、そういったものも活用していきたいと考えているところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"４１デシベルの中等度の人から補聴器を着けることを推奨しているということなのです。これはぜひ早期着用というところで、このことをもう一つつけ加えて申し上げておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"それから、お子さんについては、品川区も中程度まで補助を、助成と言ったらいいのでしょうか、あったかと思います。品川区で今それぞれ難聴の重度・中度・軽度は、どのくらいの人数がいらっしゃるかというのを把握していらっしゃいますか尋ねました。","respondent":"松山障害者福祉課長","answer":"恐らく手帳の等級によってそれぞれ異なって分かれるかと思いますが、等級については、今ちょっと手持ちの人数の情報を持っておりません。聴覚障害の方の全数は把握していますが、補聴器を使っている方でというふうに限定しますと…","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"聴覚障害の方の全数がわかるということのようで、その数字をください。補聴器を着けている中の重度・中度ということではなくて、品川区民の中で把握されている聴覚障害の中での級の割合がわかれば説明を求めました。","respondent":"松山障害者福祉課長","answer":"令和元年度、今年４月１日ですが、７８４人ということになっております。例えば平成３０年度に支給した延べ件数にしますと、いろいろなタイプがありますが、合計で１４３件という実績は把握しています。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"品川区内で中度・軽度で、どの程度聴覚の障害と言ったらいいのでしょうか、これを考えるにはまずとても大切なことだと考えています。難聴になった方をどう把握していって、どういうことをメインのアプローチにしていくのかということを、お答えほしいと求めました。","respondent":"大串福祉計画課長","answer":"委員ご指摘のように、そういった身体的な衰弱といったものが影響するといったところでの普及・啓発は大切なことだと考えています。難聴ということに関しても、区として、さまざまなご意見を伺いながら周知・啓発を図っていきたいと考えております。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"今すぐにお答えいただけるのは、かなりざっくりしたところだと思いますが、ちょっと難聴の問題というのも、ぜひ品川区で一つのテーマとして取り上げていただければなと思うのですが、ここはお答えいただけますか尋ねました。","respondent":"大串福祉計画課長","answer":"関係する部署等が出てこようかと思います。そちらとの連携を図りながら、さまざま課題はありますが、そういった中でも難聴といったところにもフォーカスを当てていければと考えています。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"高齢者クラブやシルバー大学といった、対象になるような団体での講習会・交流会といったことに広げられたところはなかったのか。そこを伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"会議には関係者だけでなく、外部の方を招いて何かお話をしていただくなど、周知・啓発をしていただくといった機会も多々あります。そういった方にはそのようなご案内を事前にさせていただいているところです。","id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ああ、さらにそれをお友達にも広げるという状況もあって、これはとても求められていることなのだなということを地域に出ても思うわけです。ぜひ品川区としてはそういった立場で実態調査、そして普及・啓発をしてほしいと求めましたが、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"先ほども申し上げまして、さまざまなご意見等あろうかと思います。そうした中、ご意見をさまざま伺わせていただきながら、どういった形が一番有効なのかというのは判断させていただければと考えております。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"認知症のところでの補聴器早期着用についての啓発は、区の取り組みとしてはされているのかどうか。その点について、お伺いします。","respondent":"寺嶋高齢者福祉課長","answer":"先ほどご案内のあった論文等については、我々のほうもつかんでおりまして、その後の追加情報等、新たな発表等も含めて今注視しています。必要なものにつきましては対策として取り組んでいくことが、認知症対策に役立つものについては積極的に取り組んでいきたいと考えております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、早期に補聴器が大事なのだという具体的なその辺のところがされているかどうかというところを教えてほしいと求めました。その具体的な状況を教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"１点目の認知症の取り組みの中で補聴器が重要であるということを啓発しているかどうかということにつきましては。それがどの段階から補聴器なのかといったことについては、まだ残念ながら把握できておりませんので… 身体障害者手帳の交付を受けた方の内、耳鼻科の医師の補聴器が必要だという診断書に基づいて、こちらのほうは補助しているものです。ですから、個別性が高いと認識はしております。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４１デシベルというのはどういうレベルかというのもＷＨＯのそこのところに書かれていまして、時々人の言うことが聞き取れない。ぜひとも区としてもこの問題に向き合っていただいて、補聴器補助をしていただいたり、要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"議論を伺っていて、このような陳情が挙がっている中で、さまざまな考え方があると思うのです。場合によっては、これというのは僕らが議員なわけだから、国に対して議会で要望を上げることかもしれない。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"は根拠、情報が求められると思いますので、一足飛びには難しいというところにポイントがあると思います。調査を進める必要があるため、継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"例えば買った人の２５％ぐらいが使っていない。しっかり見極めていただきたいということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"２５％というのも、補聴器というのはどういうものだよという説明をあらかじめきちんと受けて、もうつくられているものなのです。高齢者が本当にいきいきと暮らし続けるためにも、一刻も早くこの制度をつくっていただいて、そういうところに足を踏み出すべきだと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"難聴の問題をちょっとトータルで把握していただいて、そしてその中で必要な施策をとるという方向で考えてほしいと求めました。そういったことについて見ていくという意味も含めて、継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]},{"id":"topic-02","title":"令和元年陳情第４５号 障害者が安全に利用できる心身障害者福祉会館の整備を求める陳情","agenda":"令和元年陳情第４５号 障害者が安全に利用できる心身障害者福祉会館の整備を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、２階からはスロープがあるけれども、その上からはスロープというのはないという構造なのでしょうか。そして、３階、４階の場合は、階段を担架でおろすということになるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"布担架あるいは、電動車いすですと重量が多くて難しいとは思いますけれども、通常の車いすであればそのままおりるということも可能です。訓練につきましては、職員同士でまずは実際に使えるということで訓練を行い、慣れるということを行っております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この心身障害者福祉会館は、２次診断までされているのか。その点についても説明を求めました。","respondent":"松山障害者福祉課長","answer":"心身障害者福祉会館の場合は、全ての階におきまして、ＩＳ値は０.６以上というふうに全てクリアされております。平成２２年１月に心身障害者福祉会館の耐震診断を行いました方法としましては、２次診断まで実施しているものです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"２次診断までされて、この心身障害者福祉会館は安全な建物だということで確認されているということでいいわけですね。この陳情を見て、公表や、調査結果を示して説明していただいたほうがいいのではないかなという思いがしたのですが、そういう点ではいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"特にくくり出しまして公表する予定はございませんが、安全性についてはきちんと耐震診断を行いまして、毎月やっているということです。今度とも障害者の方が安全に過ごせるような形で、心身障害者福祉会館を通じて利用者には説明もしていってもらいたいと考えています。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２次診断までされて、そういうデータが出ているわけですから、通われている方は安心されるのではないかと思います。ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"今回も大変真っ当な指摘をいただいております。この施設は、福祉避難所になる計画はあるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"心身障害者福祉会館は、二次避難所の扱いになっております。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"ここなどは１.０とかいう数字、違ったでしょうか。その辺はいかがなのでしょう。","respondent":"松山障害者福祉課長","answer":"学校の場合については、文部科学省の補助金の支給条件というのが０.７以上ということになっているかと思います。心身障害者福祉会館の場合については０.７以上も全ての階においてクリアされております。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"０.７以上というのもクリアされているということでお伺いいたしました。安全性や災害時の対応などもブラッシュアップしていく必要があるかと思うのですが、現段階で区として、それはどのようにお考えなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"要はサービスを継続することというのは非常に大事であると区としては認識しております。今すぐ何か検討しているわけではございませんが、将来にわたって、サービス継続の面から総合的に判断する必要があると考えております。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういった意味からも、余り先延ばしにせず、具体的な計画をできるだけ早く考え始めてほしいと求めました。最後は要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"今、課長からも説明がありましたが、建て替えるとなると、それ相応の準備も必要になると思います。ただ、今の今ではないということでしょうから、不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"西村委員","kind":"意見","question":"結論を出すで、不採択でお願いいたします。は災害時に車いす利用者の方も安全に避難ができると認識していると課長もおっしゃっておりましたので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"若林委員","kind":"質問","question":"安全に利用できる心身障害者福祉会館についての説明をお聞きしましたので、不採択で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、趣旨採択でお願いしたいと思います。この方もそういう状況を求めてきたにもかかわらず、建て替えも含めて検討していただきたいという思いもありますので、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"あべ委員","kind":"意見","question":"今お話がありましたように、早急にというのは今の区の状況に合わないだろうと受けとめました。区ももう既に認識されていると思いますので、その中できちんと計画を立てて、よいものをつくってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"}]},{"id":"topic-03","title":"令和元年陳情第４６号 一元化した指定管理による障害児者総合支援施設の管理運営を求める陳情","agenda":"令和元年陳情第４６号 一元化した指定管理による障害児者総合支援施設の管理運営を求める陳情","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"１個だけ教えてください。代表番号に電話したら電話に出る人がいるわけで、誰が出ているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"今現在、区から受付業務を委託しております委託業者の職員が出ております。","id":"exchange-037"},{"speaker":"渡部委員","kind":"質問・要望","question":"一元化した指定管理による管理運営を求める陳情ということなのですが、例えば電話対応は、そこの人間として出させなければだめ。そこは直してください。","respondent":"築山障害者施策推進担当課長","answer":"委員にご指摘いただきました点につきましては、館の管理運営ということで研修をして、改善を図ってまいりたいと思います。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"やはりこれは区立の施設で区の事業ですから、その条件というのも、やはり最終的には区が責任を持つべきことだと感じます。私は当初のこの施設をつくった目的ですとか、あるいはそれを安定的にサービスを向上させていくという区の責任がどうも曖昧なように感じております。","respondent":"築山障害者施策推進担当課長","answer":"それぞれの事業で収益に落差等が出ると思いますが、そういったものの采配が難しいといった課題がありました。建物管理をするに当たって、どこが代表として実施していくのかといったところの難しさもございました。","id":"exchange-039"},{"speaker":"あべ委員","kind":"意見","question":"そのための第１歩がうまくいっていないからこそ、電話のやりとりもうまくいかないというようなこともあると思います。そこに対する区の考え方はいかがでしょうとの意見を述べました。","respondent":"築山障害者施策推進担当課長","answer":"当初のプロポーザルのときに、建物管理の実施部分について、公募の要項のつくり込みの部分で甘さがあったのかなというところは認識しております。こういった地道な積み重ねで風通しのよい施設運営、一体的な運営ということで努めてまいりたいと思います。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このフリーユニティーという法人というのは、そういう初めてのことだけに、議会の中でもかなりいろいろと確認のやりとりというのはあったと思います。そこら辺のところはどうなっているのかも教えていただきたい。","respondent":"築山障害者施策推進担当課長","answer":"一般社団法人に建物管理等を委託して実施させるという案もあったのですが、これも指定管理で実施するのは難しいということがございまして。３年後の体制につきましては、現在どういった形で実施していくか、検討している段階です。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"言ってみれば、一番初めのプロポーザルで応募して選定された事業所が、そういう一般社団法人フリーユニティーという形になったものではないのですか。そこら辺の仕組みも含めて教えていただけたらと思います。","respondent":"築山障害者施策推進担当課長","answer":"最初の一般社団法人の位置づけについて、もう一度ご説明します。３年後のことということで委員からご意見をいただいておりますが、こちらにつきましては、現在実施方法について検討しています。","id":"exchange-042"},{"speaker":"渡部委員","kind":"質問・要望","question":"障害児者の方が待っていた施設ができ上がって、それぞれさまざまなご期待がある中で動き出しているわけですから、それはそれでやっていただきたい。全然内容と違うところでクレームになってもおもしろくないし、そこでけちがつくのも嫌ですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"西村委員","kind":"意見","question":"結論を出すで、不採択でお願いいたします。安心して使っていただけるようにしたいという思いはありますが、現在検討中ということですので、不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"若林委員","kind":"質問・要望","question":"今年の２月の指定管理の議決で、今のこの３年間の各法人による指定管理のあり方については、私としては思っています。３年後、またサービスできるように、ぜひ頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、この事業者に引き続いてこの品川からやはり発信できるような中身をぜひ実践していっていただきたいなと思います。検討していただいて、事業者と意思疎通を図りながら、ぜひやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういった意味で、この３年間、区と事業者の中で良質なサービスをつくり出していく。同じ熱量で取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-04","title":"建物明渡等請求事件の結審","agenda":"建物明渡等請求事件の結審","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"１点確認したいのが、この被告３名です。追い出されてホームレスになったりでは困りますので、どういう状況か、話せる範囲で説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"１回だけ、この３人の内お一人の方とお会いすることができて、それはまた別の形でお受けしますということはお伝えしています。こういう受け入れる体制はあると、相談はお受けできるということは、３人の中のお一人にお伝えをしているという状況です。","id":"exchange-048"}]},{"id":"topic-05","title":"「しながわ健康プラン２１」中間・評価見直し（素案）およびパブリックコメントの実施","agenda":"「しながわ健康プラン２１」中間・評価見直し（素案）およびパブリックコメントの実施","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"そこをまずどのように区として考えていらっしゃるかということをお伺いしたいと思います。これは後半どのように変えていくつもりであるのか説明を求めました。","respondent":"高山健康課長","answer":"例えば塩分であったり油分であったりというものに気をつけた、自宅で健康的な食をつくるようにといった取り組みなども検討しております。働き盛りの人たちが参加しやすいような事業をしっかり運営していくという形で、何とかそういう人たちを取り込んでいきたいと考えております。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問・要望","question":"例えば啓発のところ、学校の中で心の授業と言ったらいいですか。それに対してどうするというのがないので、ぜひ後半で頑張ってもらえればと思いますが、いかがか尋ねました。","respondent":"高山健康課長","answer":"この報告にも出てまいりますが、自殺対策の取り組みも一つの大きな計画として仕上がってまいりますので、内容になっていくのだと考えております。ギャンブルなども含めた依存に関する対応についても取り上げていく内容ですので、その取り上げ方や頻度…","id":"exchange-050"},{"speaker":"あべ委員","kind":"提案","question":"その中でさまざまな健康についての知識や行動、一緒にやっていけるような体制というのも今後つくっていかれたらどうかなと思います。これは、最後、提案といいますか意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"目標値がほとんど増加とか何か本当にどうするのという中身が多いというのを指摘もしてきたわけですが、すごい前進なのではないかと思います。どのように検討して出されたのかというのをちょっと教えていただきたいのと、ここの中にメンバー表がないので教えてほしいと求めました。","respondent":"高山健康課長","answer":"もう一つなのですが、その上で検討した結果、それほど厳しくもなく甘くもなり過ぎないというようなことが一つ庁内検討の中で出てまいりましたので。２点目の庁内検討委員会のメンバーにつきましては、完成したものといたしましては…","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"パブリックコメントを得るに当たり、全区民向けの説明会というのを私は行ってほしいなと思いますが、それはいかがでしょうか。少なくとも健康推進委員の方々には説明をしてご意見を伺うことも必要なのではないかなと思いますが、いかがか尋ねました。","respondent":"高山健康課長","answer":"さすがに計画の検討ですので事業の中身の具体までのお話ではございませんが、少なくともこの計画を推進するフェーズ、段階におきましては。３点目、パブリックコメントに当たっての区民全体への説明という点です。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"健康に関しては、本当に多くの皆さんが関心が高いですし、また健康寿命を伸ばしたいと皆さんが思っているところです。そういうご意見も踏まえた上で、より充実というところでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"５７ページに第６章、プランの推進体制というのがあって、庁内の関係部局間の連携というのがあります。どこからどこまでの連携、関係部局なのか、もうちょっと具体的に教えていただきたい。","respondent":"高山健康課長","answer":"この庁内検討委員会に参画してもらいました高齢者地域支援課です。いろいろな課の取り組みというのも見えてまいりましたので、そういった部分はしっかり今後もかかわる形で進めてまいりたいと考えています。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問","question":"やはり今のお話を伺っても、いわゆる地域振興部や都市環境部なのかな。議論を踏まえて、このプランの策定に当たって、ここはしっかり根拠を持たせようというお考えはなかったか尋ねました。","respondent":"高山健康課長","answer":"やはり庁内のしかるべき部門で連携する必要があるという認識は持ってありますので、しっかりとその部分は計画以外の部分で進めていくと。いわゆる保健所設置市の事務として進めていく必要があると考えておりますので…","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"こういうふうになるからこの口の中の健康というのは大事なんだと思ってもらえる書き方、示し方をしてほしいと思います。健康プランが、そういったことが示せるものなのかを伺いたいと思います。","respondent":"高山健康課長","answer":"８ページの医療費という欄には、いろいろ検討する必要の中では、歯科という医療費の内訳なども載せてみたりしております。委員のご指摘の表現する方法については、今後計画案をつくる中で整理してまいりたいと考えております。","id":"exchange-057"}]},{"id":"topic-06","title":"品川区がん対策推進計画（素案）およびパブリックコメントの実施","agenda":"品川区がん対策推進計画（素案）およびパブリックコメントの実施","exchanges":[{"speaker":"あべ委員","kind":"提案","question":"全体によくできたものだと思いますが、幾つか質問と提案をさせてください。今ＮＴＴ東日本関東病院と昭和大病院のがん相談支援センターは、何人ぐらいのご利用があるのでしょうか、説明を求めました。","respondent":"高山健康課長","answer":"２点目の胃の内視鏡の麻酔の件につきましては、いろいろな検診実施上の課題もあるということから、現下においては採用していないといったところです。そうした品川区民のニーズなどが、どのような状況でどれだけあるのかということは今後も把握に努めてまいりたいと考えておりま…","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはなぜ伺ったかというと、委員にも入っていらっしゃるマギーズ東京、先日見せていただきました。がんに悩むご家族の方、あるいはがんでご家族を亡くされた遺族の方の相談の場といいますか、心の内を話す場としても機能しているやに伺いました。","respondent":"高山健康課長","answer":"２点目のがん相談支援センターにつきましては、現在、十分に自分たちの存在が知られていないというのを非常に残念がられています。そうした医療機関以外の相談場所の存在というのも、やはりこの計画を実際に進めていく中では、さらに必要になってまいるかなと考えているところで…","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問・要望","question":"今区内で提供できないサービスについては、できればマギーズ東京をご案内するような形でやってほしいと求めました。以上、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういう点では、私はこの計画がとてもいい中身でありますし、また、そういうふうな思いをさせるにもとても役立ててほしいなという思いがしたのです。特に品川区として啓発だったり、こういうところに力を入れていきたいというところがあったら…","respondent":"高山健康課長","answer":"健康づくり推進協議会という場で地域の代表の方にもこの内容についてはご説明をし、素案としてつくり上げてきたものですので。しっかりと進めていくということが第一段階だと考えておりますので、行動に移っていただけるような取り組みを進めてまいりたいと考えております。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も先ほどの２つの拠点病院で、やはり知らせていくというところを、とてもしていただきたいなという思いがしています。ぜひそういう機会として、啓発の機会として、これを使っていただきたいというところで改めて要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういった自治体と医療機関との連携をさまざま総合的に推進するという形がとても強く求められているのではないかなと思っています。要は、そういった方々の声を聞く場をつくって反映された計画になっているのかお聞かせほしいと求めました。","respondent":"高山健康課長","answer":"例えば６１ページに記載の東京産業保健総合支援センターというのが、実は目黒区にあります。そういった意味では、この計画をつくって５年後ということではなくて、今後も収集してまいりたいと考えております。","id":"exchange-063"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、そういった声を反映できるように、アンケートなどはぜひとってほしいと求めましたが、いかがでしょうかということ。そこを伺いたいのです。","respondent":"高山健康課長","answer":"１点目のアンケートを実施するかという点に関しましては、やはり我々としても意見を把握していく必要性については感じております。今後、把握の方法については研究、検討してまいりたいと考えております。","id":"exchange-064"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"最後に、また罹患してしまった人たちの治療というところで、経済的負担が増大することは避けるべきではないかと思います。こういった計画を出すわけですから、がんを予防するというところから進んでいくべきではないかなと思いますが、いかがか尋ねました。","respondent":"高山健康課長","answer":"１６ページあたりに、品川区が実施しているがん検診を記載しておりまして、このように対象と自己負担額ということで書かせていただいております。やはりこの辺は負担増の関係もありますので、一定の検討をしていく必要はあるとは思いますが。","id":"exchange-065"},{"speaker":"若林委員","kind":"確認","question":"確認だけ。６つというのは、具体的に、すみません、説明を求めました。","respondent":"高山健康課長","answer":"有効ながん検診の実施の中の現状と課題というところをまず見ていただきますと、２行目の「一方」と書かれているところです。こういったものにかけている費用などを他の５つのがんに振り分けていくとか、税の有効な活用が図られると考えております。","id":"exchange-066"}]},{"id":"topic-07","title":"品川区自殺対策計画（素案）およびパブリックコメントの実施","agenda":"品川区自殺対策計画（素案）およびパブリックコメントの実施","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"やはり私もこの週末、周囲の方にも伺いましたけれども、これは違うのではないかという方々が非常に多かったです。同じ２７ページのこの基本理念、緑で囲った上のところの２つ目の段落ですけれど、これは何か言葉が重複していないか尋ねました。","respondent":"鷹箸保健予防課長","answer":"最終的に事務局としてこちらにしたものなのですが、今ご意見をいただきましたので、再度ここの部分については検討していきたいと思います。この取り組み方については、なぜここをターゲットにしたかという説明が確かに弱い部分を感じますので…","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"これまでやっていることを挙げてもらって書くだけでは、なかなか対策として前に進んでいかないのではないでしょうかということです。そうした意味では、せっかくこの自殺対策計画ができるわけですから、いかがでしょう。","respondent":"鷹箸保健予防課長","answer":"丁寧な１つの相談が、全て自殺予防に役立っているということの認識をまず持ってもらうということはかなり重要と思います。つなぐシートというのをつくり、もちろん個人情報はしっかり守った上で積極的にほかの課に相談をつないでいくということをやっています。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問","question":"この中にもあるように品川区は全国でも自殺率が高い自治体であるというふうに指摘もされておりますので、質問させていただきました。減らす方向で今後も施策を展開されることを期待して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここを見ると、ライフリンクの清水さんの講演を聞いているわけではないですか。何かあれば。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"渡部委員","kind":"質問・要望","question":"ただ、今２人の委員からやはりそぐわないという話があるとすれば、表に出る書類なのだとすれば直したほうがいいのかなと思います。これで僕はいいと思うのだけれど、考え方が違ったら違いますよと言ってほしいし、そうですよというのだったらそうですよとぜひ言ってほしいです。","respondent":"鷹箸保健予防課長","answer":"例えば３２ページの区民一人ひとりが取り組めることとして、悩みを抱え込まないで相談するとか、相談窓口を知るとか。区民一人ひとりが取り組めることとして、みずからの不調に気づくといったようなことを挙げている部分になりました。","id":"exchange-071"},{"speaker":"渡部委員","kind":"意見","question":"どうやって行政や地域がかかわっていくかということを、僕はこれはこれでとてもいいことだと思いますし、これ以上のことはなかなか難しいのかなと。長くなりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自殺しなくてもいい社会を、地域をどうつくるかということが一番大事だと思うのです。そういうところにもっと力点を置いたような形でつくっていくという中身が必要なのではないかなと思います。","respondent":"鷹箸保健予防課長","answer":"今の鈴木ひろ子委員のご説明で大変よくわかりました。ちょっと方針をもう一度見直してみたいと思います。","id":"exchange-073"},{"speaker":"西村委員","kind":"質問・要望","question":"自殺予防のために区として力を入れてほしいことで、そして２０代の女性でも６７.５％の方が、職場における過労防止対策を希望しておられます。関係機関、もう少し見えるように周知をしていただいたり記載していただきたいなと思いますが、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"２６ページの２０代女性の職場における取り組みをぜひという部分については、若年層の取り組みなどで、重点施策の中で取り組んでいきたいと思います。４８ページの中高年女性の支援については先ほどもご説明したところですが、具体的な支援策について。","id":"exchange-074"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、そうした自殺者を生み出さない地域や社会をつくってほしいという当事者の皆さんの願いでつくられた、そういうもとでの計画だと思います。ですので、やはりこうした調査もしながら、対策を、計画をつくっていくべきではないかなと思うのですが、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"港区が、かなりもう以前に計画を策定して、昨年その改定もされている部分については十分認識しております。品川区で現在のところまだ実施していないので、簡単に比較することはできませんし、またちょっと考えていきたいと思います。","id":"exchange-075"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"貧困と格差を拡大してきた経済政策や社会保障や医療の改悪をやめて、全ての国民が憲法２５条の健康で文化的な最低限の生活を営む。ですので、そうした今の政治がつくり出してしまっている現状というのに対して、区の認識はいかがでしょう。","respondent":"鷹箸保健予防課長","answer":"そういったご事情を抱えた方がさまざまな生きづらさを抱えているということについては、事務局としては十分認識しております。我々が持っているものでないので、ちょっと取り組めるかどうかは今自信がないところですけれども、再度データについては見直したいと思います。","id":"exchange-076"}]},{"id":"topic-08","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、はがきを健康課へお送りくださいということでありますが、はがきを出した方だけということなのでしょうか。ちょっとその点を教えてほしいと求めました。","respondent":"仁平品川保健センター所長","answer":"今回、その中でも支援ができていなかった、手薄になっているというところを、ネウボラネットワークとして整備したというのが考え方になっております。こちらは平成３０年度の数字ですが、出生通知に対しまして、把握率が９４.２％、訪問率は８３.６％となっています。","id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"はがきを出さなくても、かなり高い比率で訪問されているということなのですが、訪問されない方の理由もわかったら教えていただきたいのが１つです。そのまま受け入れざるを得なくて、必ず病院からは連絡が来る、ほとんど来るということで捉えていいかということだけ確認をします。","respondent":"仁平品川保健センター所長","answer":"病院との連携です。まれな例なのですが、ほかの妊娠相談のＮＰＯから保健センターに連絡があって、そこで病院につないだということもあります。","id":"exchange-078"},{"speaker":"あべ委員","kind":"確認","question":"それから、要支援が複数あるとそれもハイリスクになるのかなと思いますが、そういう捉え方はされていますでしょうか。もう一つ、一応確認です。","respondent":"仁平品川保健センター所長","answer":"要支援が複数あった場合にハイリスクというのは、余りがちがちには考えておりません。具体的に何をするかというと、まだ妊婦健診等の残回数がある方は、特別区で使える健診票に交換するのと同時に面接も同じようにしています。","id":"exchange-079"},{"speaker":"あべ委員","kind":"確認","question":"あるいは精神疾患の既往歴がある方は、そうした出産を機に状況が変わる方というのは、一定数いらっしゃるのかなと思います。それについては出産から時間を経たずに、やはり状況の変化がないか確認するということもぜひやっていただければと思うのですが、いかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"出生通知を出す方については、訪問の受け入れの段取りを決めて対応してまいります。今、郵便受けのところまでエントリーできないという事情がありまして、なかなか訪問に来たよというのもお知らせできにくいという状況もあります。","id":"exchange-080"},{"speaker":"あべ委員","kind":"提案","question":"そこもネウボラではいろいろなサービスが整っていていいなと思いますが、やはりその分量です。これは提案にとどめておきますが、相談だけではない、具体的なサービスというのも必要に応じて柔軟に提供できるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"西村委員","kind":"質問・要望","question":"ドゥーラについて伺いたいのですが、一文でもあるのかなと思ったのですが、見落としていたらすみません。なかなか予約をとるまで気が回りませんので、もう少し予約がとりやすいような改善をお願いしたいと思いますが、いかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"こちらも今現在実施場所が１カ所でして、非常に利用希望の方が多く、月の上旬には大体その月の予約が埋まってしまうような現状になっております。そちらを実施されていない方でしたら、まずは区の訪問対応を受けていただきたいというのを勧奨しています。","id":"exchange-082"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312511?Template=document&Id=3548#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":91112,"voices":214}},{"id":"r01-20191111-8","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"建設委員会","time":"午後 １時００分～午後 ５時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"今の最後のステップのことなのですけれども、ステップ２の日程というか、大体どれぐらいの時期なのかというのを説明を求めました。","respondent":"鈴木都市計画課長","answer":"１２月には第２回目検討会の中でステップ１の地域の評価というところをご議論いただく予定です。それから、ステップ４以降については来年度以降です。","id":"exchange-001"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。我々も、今品川区でも一生懸命こういう形で地域の選定をこれからやられるということですので、しっかり見守っていきたいなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問・要望","question":"結局ステップ１の地域の評価の中である程度地域が絞られてしまうということなのでしょうかというのが１点と、本当にさまざまな地域の方たちがコミュニティバスを求められていて、ステップ２をつなぐ間の動きのようなことが検討されているのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今の取り組み状況については、地域センター管内ごとに順次説明して、その場でいろいろなご意見をいただいているところです。ちょっと今検討中ですが、全域で一堂に会してというのはなかなか難しいかなという考えで今検討している状況で、所管としてはそういう認識です。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"それぞれ１３地域センターごとに説明会を開かれてご意見を伺うということも必要だと思うのですけれども、同じ願いというか、何か不満が残るみたいな。そういう形の意見を聞く場というのをぜひ検討していただきたいと思うのですけれども、もう一回、もし見解があれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり１３地域、広いエリアでこうしたご提案いただいたような会を立ち上げてご議論いただくというのはなかなかちょっと難しいかなという捉え方です。そうした区民の声の反映の仕方をしっかり用いながら、全域は難しいかもしれませんが…","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"今はできないというふうにおっしゃっていますけれども、これからステップを幾つか踏まないといけないわけですから。これは要望にとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"そのことを伺ったのですが、区のホームページとかこの委員会の場でも報告したいということだったのですが、その後の検討はいかがでしょうか伺います。アンケートは１,０９４票ですか、この地域別内訳についても伺ったのですけれども、それぞれ幾つぐらい返ってきているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"アンケート結果のホームページ等での公表ですが、第１回の地域交通検討会の資料は既にホームページ上でも公表しています。品川第二地域センターでは開票数が１１４票、大井第一地域センターですと１７３票、大井第三地域センター等では７２票等々の開票数です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、この時点でというか、私が今上大崎の地域を歩いて地域の方から伺う声と全然合わないなというのがあるのです。生活実感から来る要望だと思うのですけれども、区は現時点でどのような分析をされているのか伺いたいなと、それぞれ伺いたいなと思います。","respondent":"鈴木都市計画課長","answer":"一番多い、よりご回答いただいたその地域ごとの票数の割合ですとか、そうしたところをより細かく評価項目としていくということで検討しています。これから２回目の検討会に向けて、地域の評価、まさにそれぞれのエリアについては第２回目の検討の中で地域の評価をしていきたいで…","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、今回具体的な三つの地域からの分析については、今分析中ですからということなのですけれども。こういった陳情で寄せられた具体的な声をぜひ受けとめていただいて、検討に反映していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"まさに委員からご指摘をいただいたように地域の方の声を検討の中でしっかり把握しながら反映していくということは大事だというふうに考えてあります。そうした施設が１カ所に集約しているような形であれば、その反映の仕方はこれからしっかり検討して…","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、住民の方々が求めていることですし、そういう施策に私はなるのだと思うのです。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"松本委員","kind":"意見","question":"今いろいろと今後の検討の方向についてお話が出たのですけれども、一つ気になるのは試行運行が行われた後の話だと思うのです。１回やってみて、運行を１回実証でやってみた後のイメージ、そのあたりをお聞かせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"ここで１ルート絞ってみたいな記載になってありますが、それも含めてこれから検討していくことになろうかと思います。あるいはさらにちょっとこういった視点を加えて本格実施していきましょうとか、やはり中身的には本格実施をするには、その後の展開を考えていくです。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"理由を述べますが、地域交通検討会ですか、この検討会も既に立ち上げられて、８月に行われました。先ほど申しました、繰り返しますけれども、不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここら辺のところを伺うと、いろいろな形で議論していただいて、一定の方向を出していっていただきたい。今これがまさにこういう形で進んでいるときに、路線をどうという形でと私は委員会として出すべきではないと考えていますので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"確認","question":"不採択でお願いします。先ほど確認したとおり１２月末、１２月中には一定程度地域が絞り込まれていく中で、不採択としたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうところに、やはり地域の要望をどう反映させていくかというのはすごく大事な点だと思います。こういった要望があるのだということを一定議会として判断していくといいますか、私はこれを採択すべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"吉田委員","kind":"意見","question":"やはりこういう陳情がたくさん出てくるということは、そこに自分たちの地域の意見を反映してほしいということだというふうに理解します。この思いというのは、取り上げるべきと思いますので、趣旨採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いいたします。今いろいろな方がおっしゃられたとおりで、全く不採択というのもちょっと抵抗がありますので、趣旨採択ということでお願いできればと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろ皆さんのご意見を聞く中で、やはり私は議会としてこういう地域から具体的なコミュニティバスに対する要望が上がっているということは。少しでも反映させるために趣旨採択というお声も多いので、趣旨採択に変えさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、先ほどと同じ流れですので、趣旨採択を主張しますが、大変大事な内容が書かれていますので、ぜひその趣旨を検討に反映させていくべきだと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"吉田委員","kind":"意見","question":"項目については、まさにこれから議論すべきです。ただ、この陳情の趣旨はぜひ採択として趣旨採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、先ほどの議論を踏まえて趣旨採択を主張します。ぜひ今後の議論に反映すべき趣旨だと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]},{"id":"topic-02","title":"大崎駅周辺地域および西五反田三丁目地区のまちづくり","agenda":"大崎駅周辺地域および西五反田三丁目地区のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"五反田、大崎と出ていますけれども、これはひとくくりで担当しているという感じなのでしょうか伺いたいというのがまず１点です。番号順に幾つかお伺いしたいのですけれども、今回入ったというのは、この半年足らずの間に新たな動きがあったということなのか尋ねました。","respondent":"稲田都市開発課長","answer":"これは国が示す都市再生緊急整備地域、都市再生特別措置法が平成１４年に制定されました。緊急的にまちづくりをしっかりと進めていくという国の方針に従いながら指定されたものでございまして、再開発等々をやってきているです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと最後のところは、指定されることで、具体的にどういう規制緩和がされるのかとか、そういうところをお伺いしたかったので後で教えてください。建物が与える影響が余りにも甚大なので、それを認めるべきだと思うし、公聴会を開催する考えがあるのか伺いたいなと思います。","respondent":"稲田都市開発課長","answer":"東京都も認識しながら進められているものでございまして、精査をしながら出てきた案に対して精査をしながら検討していくものです。それから第１７条、広く区民の皆様方にここで縦覧や説明会を行いながらご意見等々を伺うです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"続けて、２の東五反田二丁目第４地区についても伺いますが、これはどんな制度なのでしょうか。区として今後この制度の活用を進めていくという考えなのかどうか伺います。","respondent":"稲田都市開発課長","answer":"それから、東京都マンション再生まちづくり制度を活用予定の東五反田二丁目第４地区です。そういう中で再開発等々を検討しているというところです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"大崎駅についての記述がありますけれども、交通結節機能強化ということがありますが、これはどういうことなのでしょうか伺いたいと思います。大崎駅東口第４地区の西側のほうの再開発準備組合、もしくは協力企業にＪＲ東日本は入っているのかどうか、これも伺います。","respondent":"稲田都市開発課長","answer":"そういう中におきましては、東西両方の連絡会をつくって、しっかりとまちづくりに対応していこうかというふうに進めてきているものです。大崎駅について現在協議している中におきましても、この辺の状況等は今協議会、事務組合等々で検討されているという話はしているところです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"８のところはちょっと細かくて申しわけないのですけれども、その理由というのですかね、お伺いしたいと思います。主にどういう方がいらっしゃるのかというのを伺います。","respondent":"稲田都市開発課長","answer":"新しいビルも含んだ形でのエリアというふうには考えているというところですが、実際の再開発準備組合は東側と西側に分かれるというところです。その社宅があったところに３棟のものを建てていくというところで、その３地区…","id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"大変１枚で幾つにも、あるいは昨今ですと、災害等で電気がとまった際の災害対応なども課題が大きく見えてまいりました。こうしたまちづくりの転換を私はすべきだと思うし、住民参加のまちづくりと環境にも持続可能な、そうしたまちづくりの転換を進めるべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"そこをどうやって整合性をつけていくのか、そういう話し合いというのでしょうか、それはどのように行われるのか。区としてはあくまで要望しか出せないものかもしれませんけれども、どういうふうになっていくのか、ぜひ教えてほしいと求めました。","respondent":"稲田都市開発課長","answer":"あるいは雨水浸透の舗装等を利用するのか、そういう開発によって発生するような環境の話もそうですけれども、対応を考えていきながらやっていくです。事前の詳細な設計に入る前、あるいは準備組合とかで検討されるときには区の担当者も行っておりますので。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺のことももともとは事業者としてきちんと説明会を開くべきものだと思うのですけれども、周辺に広げるようにということを求められないのか。求められないのだったら、区がかわりにそれをやるということはないのか、その辺についても伺いたいと思います。","respondent":"稲田都市開発課長","answer":"これは地域において計画する建物の高さを２倍した範囲ですかね、そういう範囲にチラシをまいて、事前にそういう事業者が自主的に説明をやる。区のほうとしても、そういう説明をやってくださいよというような話はしてきておりますので…","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりまちづくり全体を今住んでいる人たちと一緒に考えながらこの開発というのを進めていただきたいなというふうに思います。基本的にはやはり今住んでいる方たちの意見が反映されるようなまちづくりであってほしいし、最後は要望にさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]},{"id":"topic-03","title":"東京港青海ふ頭（江東区）における「ヒアリ」の確認","agenda":"東京港青海ふ頭（江東区）における「ヒアリ」の確認","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"八潮をはじめ、品川区でも追加の調査の要望を出すべきだと思うのですけれども、いかがでしょうか。あるいは品川区のホームページからも直にリンクを張るなど、もっとこれを活用したほうがいいと思うのですけれども、いかがか尋ねました。","respondent":"小林環境課長","answer":"それから、委員ご指摘のように非常にわかりやすいパンフレットというふうに区としても認識しています。ホームページへの記載ですが、最新版に更新されることを含めてしっかりと周知してまいりたいというふうに考えてあります。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとそういう被害というのですか、拡散というのですか、そういった危険性についてはどのように認識をされているのか伺います。ですから、品川区として定着を防がなければいけないというところでの意気込みというのですか、それをお伺いしたいと思います。","respondent":"小林環境課長","answer":"そこに例えば抜けがあるとか、そのようなことがございましたら、しっかり区としても対応していくべきだというふうに現在考えてあります。その辺につきましても…","id":"exchange-031"}]},{"id":"topic-04","title":"「資源・ごみの分け方・出し方」の配布および年末年始のごみ収集","agenda":"「資源・ごみの分け方・出し方」の配布および年末年始のごみ収集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点目は、ちょっと改めて現在の区のごみの減量の目標はどうなっていましたか、伺いたいと思います。どのようにそちらのほうはこういったパンフレットだとか周知を強めていくお考えなのか、３点目として伺いします。","respondent":"工藤品川区清掃事務所長","answer":"１人当たりのごみ量、１日当たりのごみ量という部分を把握しておりまして、それを前年よりも削減していくという取り組みをしています。そういった中でも排出抑制の取り組みという部分をしっかりと詳細に周知して、区民の方の分別行動が促進されるような形で啓発を展開しています。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"２点目のところで、京都市でちょっと伺いまして、そこに向けてあらゆる手段を考えざるを得なくなるというふうに感じたのです。１日当たりで前年よりも減らしていくという目標にされているというのは何か理由があるのか、それだけお伺いします。","respondent":"工藤品川区清掃事務所長","answer":"今ちょうど私ども第３次となる一般廃棄物処理基本計画を策定しておりまして、そちらのほうをもってしっかりと数字等を管理しているです。今後発生抑制という部分、ごみ減量という部分をしっかりとしてまいりたいというふうに考えております。","id":"exchange-033"}]},{"id":"topic-05","title":"五反田水辺が結ぶプロジェクト 五反田リバーステーションオープニング記念式典","agenda":"五反田水辺が結ぶプロジェクト 五反田リバーステーションオープニング記念式典","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点お伺いしますけれども、その後、五反田リバーステーションの具体的な活用や事業展開というのはどんなふうになっているのか改めてお伺いします。２点目は、桟橋の災害時の活用という説明をしてきたと思いますけれども、そちらについてはどのような検討が行われているのかお伺いします。","respondent":"松本河川下水道課長","answer":"現在事業展開につきましては、今事務手続きを進めているところです。災害時につきましては、東京都の防災船着場に指定されていることから、災害時にはそういった活用も考えているところです。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"２点伺います。社会実験とか東京２０２０大会時の活用とか、２点間の問題とか、いろいろな話があるのをどうクリアするのかというお考えを持っていらっしゃるのか。","respondent":"松本河川下水道課長","answer":"私たちにつきましても、そういった観点からもこの起点となる五反田リバーステーションを使えるような仕組みを今検討しています。先ほども言いましたように、文化観光課も含めまして、いろいろな課と対応しながらいろいろ仕掛けていきたいなというふうに考えているところです。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一つだけ要望しておきます。そこら辺のところも含めて、ぜひより良い活用ができるようにお願いだけしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"}]},{"id":"topic-06","title":"水辺のライトアップ（かもめ橋）","agenda":"水辺のライトアップ（かもめ橋）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"２点確認なのですが、ライトアップは期間限定なのでしょうか。年間のランニングコストはどれくらいなのか、あと、整備工事の費用は幾らだったのかお伺いします。","respondent":"松本河川下水道課長","answer":"あわせて、まだ試算ベースですが、年間９０万円ほどかかる予定としております。最後に、整備工事費ですが、こちらは起工額が１億２,９４０万５,０００円に対しまして、落札額が１億２,５４０万円となっております。","id":"exchange-037"}]},{"id":"topic-07","title":"台風第１９号（１０月１１日～１３日）における対応について、および(7)台風第２１号と低気圧の影響による大雨（１０月２５日）における対応","agenda":"台風第１９号（１０月１１日～１３日）における対応について、および(7)台風第２１号と低気圧の影響による大雨（１０月２５日）における対応","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"自主避難施設と高潮だとか土砂災害の場合の避難場所、この名称というのですか、この違いと運営体制にも違いはあるのか尋ねました。","respondent":"中島防災課長","answer":"避難準備・高齢者等避難開始あるいは避難勧告などに基づきまして開設するのが、正確に言いますと、避難場所として区が開設をするものです。よく避難所ということで、少し混同するのですけれども、区としては自主避難施設、避難場所、避難所という三つを考えているところです。","id":"exchange-038"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、もしくは土砂災害とか高潮だと避難場所になるにしても、運営とかそういうのは基本的には区の職員がやるということでいいのかどうか。なぜそういう質問をするかというと、地震のときの避難所運営会議という体制ですか、そういう体制でやることも考えるのかどうか。","respondent":"中島防災課長","answer":"普通に電車等も走ったり、どこまで地域の方と連携できるかというのは、正直まだこれから考えていく必要があると思います。そのあたりは今後あり方を考える中で、そういうところを頭に入れながら、よりよい避難場所等の運営を考えていきたいと思います。","id":"exchange-039"},{"speaker":"たけうち委員","kind":"質問・要望","question":"いや、もっと私たちを入れてやったほうが、来た方は顔を知っているのだから安心するのだからというところもあったと思うのです。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"今ちょっと自主避難所の話が出たので少しお伺いしたいのですけれども、ある意味任意的にやられているということなのだと思います。自主避難というのは、こういうものというのは、例えば品川区の場合はある程度基準を明確化していたりするのかをお願いいたします。","respondent":"中島防災課長","answer":"今回、前回の台風第１５号から２回目の自主避難施設の運営になりますが、食料はご持参くださいとかというところの周知はしています。そのあたりのところは、基準もさることながら、しっかりと周知に努めていきたいと考えています。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"結局定員いっぱいで入れなかったみたいな自治体があるかと思うのですけれども、避難するほうは先回りして避難できるのではないかと思います。区でやるのは難しいかもしれないですけれども、ある程度やっていただくのもいいのではないかなというふうに思いますが、いかがか尋ねました。","respondent":"中島防災課長","answer":"やはり早い情報開示、定員になる前に情報開示していくことの必要性を感じておりますので、区としてはそのようなところも十分頭に入れながら避難の呼びかけ等を行ってまいりたいと考えています。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"ただ一方で、実際のところはある程度余裕があったと、これはある程度余裕があったという情報をむしろ知りたかったという方が結構いらっしゃるのです。たしか電話でちょっと伺ったら、１％ぐらいしかいっぱいになっていなかったみたいな話もあるみたいなので、いかがか尋ねました。","respondent":"中島防災課長","answer":"荏原調整池が２０万m3入るということで、現状避難準備の水位といたしましては５万m3で、さらに水位の上昇が見込まれる場合になります。水位は、現状河川の水位を見られるようなものを用意していますので、わかりやすい情報の発信に努めていきたいと考えています。","id":"exchange-043"},{"speaker":"大沢委員","kind":"質問","question":"この部分で、開設の手引きというか開設のマニュアルみたいなものというのはあるのでしょうか。何を判断しながら、どんな基準をもって判断をし、開設に至るのか何か明確な決まりとかマニュアルのようなものはあるのか尋ねました。","respondent":"中島防災課長","answer":"そういう区民の方が不安に感じるような台風の進路等を勘案しまして、区のほうで開設の規模であるとか場所等を含めまして判断をしています。基準というよりもまだ実際の台風の進路等を見まして、判断をさせていただいているです。","id":"exchange-044"},{"speaker":"大沢委員","kind":"質問","question":"先ほどのご答弁の中で、近隣の方、地域の方からの声を聞いて自主避難施設を開設したというお話がありましたが、今のご答弁と若干矛盾するようなところがあると思いますけれども、いかがか尋ねました。","respondent":"中島防災課長","answer":"ちょっと私のほうの説明が悪かったかもしれないのですが、ちょっとお話をさせていただいたというつもりでございまして、あくまで開設するのは区のほうが気象情報等を見まして判断させていただいているところです。","id":"exchange-045"},{"speaker":"大沢委員","kind":"質問","question":"ちょっとこのような質問をさせていただいたのですけれども、これは５カ所ということですけれども、同様に並行して開設をされるというような考えでいいのか尋ねました。","respondent":"中島防災課長","answer":"今回開設しました５校の義務教育学校につきましては、同じ時間に開設させていただきました。同じ自主避難施設を翌日の８時３０分にシルバーセンターにも開設させていただきまして、そちらのほうでも今回対応させていただきました。","id":"exchange-046"},{"speaker":"大沢委員","kind":"質問・要望","question":"行政サービスであるがゆえに均一化したサービス提供のタイミングとかというのが必要だと思うので、そこのところをきちんと意識されながら運営をしていっていただきたいのですけれども、どのようにお感じになりますか尋ねました。","respondent":"中島防災課長","answer":"あまりマニュアルに頼り過ぎてもよくないのですが、やはり均一的な、標準的な対応が少なくともできるように配慮していきたいと思います。基本的には、よほどのことがなければ同じタイミングで開設するように努めてまいりたいと思います。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"少しでも前へ行くような感じにしていただきたいのだけれども、今回ある小学校へ行った方が、小学校にいる方に「うちではないですよ」と。そういう連携は必ず図っておいてもらいたいと思うのですけれども、そこら辺のところでお考えがあれば教えていただきたい。","respondent":"中島防災課長","answer":"教育委員会のほうでも努めさせていただきましたが、啓発板というか、案内をご覧いただけなかったという課題もあると思います。所管を問わず全庁を挙げて取り組みをしていますので、教職員とも認識いたしまして、誘導等ができるように努めてまいりたいと思います。","id":"exchange-048"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"そのとき区がどういうことを言っているのか、私のところに３人の方ぐらいから何を言っているのかわからないという問い合わせがあったのです。今回そういうことがあったのかどうかお聞きしたいと思います。","respondent":"中島防災課長","answer":"災害対策本部のほうに今何を放送したのかという問い合わせはいただいております。その都度内容についてお伝えをしていますが、やはりスピーカーで音声を流した後に一定程度そういうお問い合わせがあったということは確認しています。","id":"exchange-049"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"アナウンスをしているのが、何となく早口にアナウンスしているから、余計聞き取れないというのは一つあるのかなと思っているのです。なので、どういうふうにアナウンスをしなさいという指示をしているのかどうかということをお聞きしたいと思います。","respondent":"中島防災課長","answer":"そういうケースもあるのですけれども、今回に関しましては、あらかじめ録音したもので行ってあります。しゃべるスピードなども調整できる機能もありますので、いま一度放送のスピードなども含めてよりよい伝達法を確認させていただきたいと思います。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"台風第１９号は１２日になってから、この高齢者等避難開始の発令の仕方というのを確認させてほしいと求めました。品川区の場合どうしたかというよりも、どの程度そういうふうに、何か考えていらっしゃることがあったら伺いたいと思います。","respondent":"中島防災課長","answer":"ただ、そういうツールだけではなかなか難しいので、区としましては、広報車を回したり、そういう形の呼びかけも補完して行っているところです。そのあり方等も含めまして…","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"今回は町長みずからがマイクの前で何分置きですか、呼びかけたということで、やはり今まで大丈夫と皆さん思われるけれども。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"運営マニュアルがあるということですが、今回品川区は２回目ということでしたけれども、どのようなものが示されているのか伺いたいと思います。そういうマニュアルの今後の改善とか考え方というのは、やはり必要なのではないかと思うのですけれども、そこら辺についてはいかがか尋ねました。","respondent":"中島防災課長、あくつ委員長","answer":"１８カ所の施設で避難者が５８４人とご説明させていただきまして、資料の提供については検討……。 資料の要求については、委員会で諮ることになっているのですが、特に支障がなければ、今お答えしていただいてもいいかと。… 当初１２日の８時３０分に義務教育学校を含めました１１カ所の開設を予定、シルバーセンターと義務教育学校１１カ所の開設を予定していましたが。…","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"これからもかなり大規模な台風というのは来ると思いますので、ぜひ今後に活かしていただきたいなというふうに思います。最後に１点、浸水や高潮のハザードマップの浸水想定区域内に立地してしまっているのが、区のお考えはいかがか尋ねました。","respondent":"中島防災課長","answer":"浸水想定の区域内ということで、ただ区といたしましては、避難される方の避難しやすさなども考慮して考えてきたところです。早い段階でさまざまな手段を用いましてほかの近くの避難場所への移送等も行っていく必要があるというふうに考えております。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"浸水のおそれがあったりとかいうことで、また違うところに避難するというようなこともほかの自治体などではあったというふうに伺います。そういったことで、そこも含めて今回のことというのを本区に限らず、他自治体の事例も参考にしながら検討していっていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"}]},{"id":"topic-08","title":"令和元年度 区内一斉防災訓練の実施","agenda":"令和元年度 区内一斉防災訓練の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"災害対策本部運営訓練のことなのですけれども、区民避難所との連携、物資等の輸送とありますけれども、具体的にどのような訓練を行うのか説明を求めました。","respondent":"大森災害対策担当課長","answer":"現在避難所連絡会議等で検討中ですので、区の職員が参集計画で各避難所８名から１０名ほどがそのまま発災と同時に参集することになっております。それから無線、その中でどうやって各避難所に対して災害対策本部として支援をしていこうかと…","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"この計画で８名から１０名という計画になっているそうですが、この訓練でそういった方々全てが参集して訓練するということになっているのでしょうか。その一部の方に来てもらうということなのでしょうか、年に１回ということなので、いかがか尋ねました。","respondent":"大森災害対策担当課長","answer":"防災課の職員と参集予定の係長級職員と学校施設管理者、平時から避難所の運営について議論できるような体制というものをつくっているところです。そういった形で平時から連携を図るようにしておりますので、実際に運営の立ち上げ等の連携づくりをしていただくと…","id":"exchange-057"},{"speaker":"大沢委員","kind":"質問","question":"質問ではないのですけれども、表に「Ｒ元」と書いてある。「Ｒ元」というのは、令和元年だと思うが、ちょっとつり合いからするとおかしいので直してもらいたいのですが、どうか尋ねました。","respondent":"大森災害対策担当課長","answer":"大変失礼しました。ご指摘のとおり表現としてちょっとつり合いがとれない部分が項目としていますので、「令和元年度」という形で訂正をさせていただければと思います。","id":"exchange-058"}]},{"id":"topic-09","title":"本日は、まちづくりの進め方","agenda":"本日は、まちづくりの進め方","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の３の地区計画位置図で、地区計画のさまざまな種類があるのですけれども、このそれぞれの違いというのですかね、ちょっとそちらをお伺いします。その事業手法の中に、この手法の中にどういうふうに位置づけられているのか、そこら辺についてご説明ほしいと求めました。","respondent":"高梨木密整備推進課長、稲田都市開発課長","answer":"私からは、図で示されている地区計画の種類について説明をします。皆さんと話し合って、建物の形をそろえて、ちょっと特別な対応を設定することができる地区計画の種類という形になっております。 そのまちづくりの方針に従ってにぎわいや駅周辺の経済活動や、その辺を考えながら地域の皆様方、いろいろと検討していきます。市街地再開発を検討するその前の段階、共同建て替えにするのか、そういう意見も当然出てきます。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"具体的に伺いたいのは、ここに地域住民の、周辺住民の意見というのはどのように反映されていくかというのがすごく大事だと思います。ここについて今どのような仕組みになっているのか、私は入れていくべきだと思いますけれども、そこについてお考えをお伺いします。","respondent":"高梨木密整備推進課長","answer":"区といたしましては、まずその地域の中にお住まい、もしくは権利をお持ちの方々の意見というのは十分に尊重されるべきであると考えております。こちらの趣旨の説明を行うことで意見をいただく場をつくり、このようなまちづくりを今後も進めていく、このように考えているところで…","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"そういう計画というのが往々にしてあるわけですから、それは考えていくべきだと思いますし、これからも私たちも研究していきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"たけうち委員","kind":"質問","question":"先ほど緑の誘導容積型地区計画は東八潮とおっしゃったのですけれども、地図を見ると大井三丁目かな、小さいところがあるのですけれども、この場所はどこか尋ねました。","respondent":"高梨木密整備推進課長","answer":"先ほど私の答弁に誤りがありますので修正をします。誘導容積型地区計画は東八潮のほか、大井一丁目だと思うのですが、こちらの地区計画でも定めがあります。","id":"exchange-062"},{"speaker":"たけうち委員","kind":"質問","question":"一本橋のところですか。以上で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうなったときに調べてほしいのは、前はこういう形でしたよというと、土地の平米数はなぜか６０m2になるのだよね。議論をして地域の方から聞くときに、そこら辺の周りの調査というのをぜひしてほしいと思うのだけれども、そこら辺の考えを教えていただきたい。","respondent":"高梨木密整備推進課長","answer":"どうしても６０m2だけなので、今まで定めた地区においても、６０m2ありきでは進めておりません。例えば１１０m2の土地ですと宅地としては二分割できませんよといったところはお示ししているところなのですが、このように考えております。","id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば用途地域で僅少で４００m2でもいいけれども、８０m2の４００m2だとか、あるではないですか。そうなったというのだけれども、そこら辺の両面をもう少し考えていただければなと思うのだけれども、それはどうお考えか尋ねました。","respondent":"高梨木密整備推進課長","answer":"確かに区内では２０年、３０年といった形で長期の取り組みを推進している地区もありますが、制度上整備計画の変更ということもあります。まちもどんどん年数がたてば状況も変わってまいりますので、変更等についてもこれから話し合っていければなと、このように考えております。","id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういうのもそこだけ変えてもらうと、それなりに変わるというところがあるではないですか。こういうのというのは、やはり地区計画なのか、こういうのというのはどこがどうすれば変えられるのかを教えてもらいたい。","respondent":"高梨木密整備推進課長、稲田都市開発課長","answer":"手続的には高度地区の変更手続を行うということになろうかと思うのですが、本当に変更するのが望ましいのかどうか、手続等が必要であれば進めていく。今までの事例等を見ますと… まちづくりの方針とか、そういう手法、市街地再開発事業等では取り入れてやっているところです。","id":"exchange-066"},{"speaker":"石田（秀）委員","kind":"確認","question":"最後に確認なのだけれども、高度地区というのは、行政がやるといったら変えられるのではないのか。それだけ確認です。","respondent":"鈴木都市計画課長","answer":"手続的には変えられることにはなってありますが、やはり、変更理由も含めて非常にハードルが高いです。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/876969?Template=document&Id=4276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":70300,"voices":205}},{"id":"r01-20191111-9","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"文教委員会","time":"午後 １時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"令和元年陳情第４７号、ひろまち保育園閉園に関する陳情につきましては、予定表２、報告事項(4)ひろまち保育園在園児の優先転園","agenda":"令和元年陳情第４７号、ひろまち保育園閉園に関する陳情につきましては、予定表２、報告事項(4)ひろまち保育園在園児の優先転園","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、ひろまち保育園の閉園に関する陳情ということで、５年間の期限の２０２１年３月から可能な限り延長いただきたいということで出されたものです。１番の項目に、区のほうで検討は行ってきたという説明がありましたが、どのような検討を行っていたのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"南側を使う予定で考えますと、これは近隣の方のご理解等を得られるかどうかというのは、なかなか難しいという判断をしたところです。２０２０年度の新規保育園については、ある一定の確保ができるという見込みがついたところで…","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"いろいろと検討はされてきたということですけれども、そういった中で子どもたちがどうなるかということがやはり重要だと思います。他の議員の方が一般質問でも言っていましたけれども、品川区では１,６５０m2を確保することが無理だとしても、いかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"もともとの「保育園のご案内」でもご紹介してきましたとおり、転園先の確保については必ず行うと区のほうではうたっております。品川区としては、ひろまち保育園そのものを動かすというのはほとんど不可能だと考えましたので、このやり方を決定した次第です。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"３歳、３歳を見ると４００名から５００名ぐらい申し込みをされているということで、そこの新たな待機児童の問題について伺いたいと思います。来年の４月に向けた今年の優先転園の申し込みが終わったところで、入園の状況を伺えればと思います。","respondent":"佐藤保育課長","answer":"ただ、広町においては３６０名というところになると、まだ１,６００名近い受け入れの十分な余裕があると見込んでいるところです。５歳も空きがある状態ですので、待機児童に関しては十分対応できると、今のところ見込んでおります。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"３歳申し込みをするということで、やはり３歳がさらに厳しくなってしまうのかなと思うわけですけれども、いかがでしょうか。やはり定期も１年で終わってしまうということになり、同じ場所で保育することができるというのが望ましいと思いますが、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"１点目の大井町近辺でどうなのかですけれども、入居日が４月以降という情報もありますので、その辺りで対応していきたいと考えております。今後も十分活用していきたいと考えているところと、引き続き待機児童対策というところで私立保育園等の新規開設に努めてまいります。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"新規開設が毎年５園から７園ですか、申請も増えているということで、待機児童がいまだにあるという状況だと思います。内定者の方はどういったところに転園されて、また不承諾の方がどういった地域の方だったのか、そこを伺いたいと思います。","respondent":"佐藤保育課長","answer":"私どもとしましては、通常の例月だったり４月の入園申請、また結果の範囲内で情報をお出ししています。東大井・八潮地区で５名、大井地区で１名、その他の地区に関しましてはゼロです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"要は、伺いたかったのは、入園内定された方も、お宅が近くですとか通勤途中のところ、通いやすいところにしっかり入れているのかということで、うわさでは２０希望まで入園希望の枠があったという話も聞いておりますけれども、しっかりと通えるところに入れたのか、そこを伺いたいと思います。","respondent":"佐藤保育課長","answer":"大変失礼いたしました。内定した方の約９割の方が第３希望以内の園に内定しておりますので、近隣もしくは希望されている保育園に内定したのかと考えているところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"第３希望までで入れたということで、それがどういったところだったのかがわからないので何とも言えないところなのですけれども。３２名の方がまだ在籍をしているというところで、この３２名の方は今後どうなっていくのか、区の対応について伺いたいと思います。","respondent":"佐藤保育課長","answer":"新２歳児から新４歳児までの３２名の方ですが、区としましては、当初からご説明しているとおり、優先転園は年度に分けて２回行いますので、令和３年４月の時点でご希望する保育園に優先的に転園をしていただくというふうに、丁寧に説明をしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"転園するところはしっかりと確保してほしいと求めましたけれども、転園をしないでほしいという声もしっかりと受けとめてほしいと求めました。工事は着工していないという確認と、なぜこのタイミングなのか、もう一度伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"令和３年３月以降開発する予定だと、２０２１年の夏以降、私どもの判断もそれほど間違っているとは思えません。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"やはり再開発を優先して子どもたちや保育をないがしろにしていると思われても仕方ないのかなと思います。区が区民の暮らしを、福祉、保育を守っていくという姿勢こそ必要なのではないかと思いますけれども、いかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"もともと５年ということで保育園の募集をしたところもあります。ＪＲ東日本との話を含めて、先が見えてきたところで、私どもは当初の予定どおり５年で閉園すると決めたところです。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"保育課内において、事業やサービスの内容の情報共有や周知といったものは、どのように行われていたのでしょうか。ぎりぎりまでＪＲと交渉されていた、話し合ってくださったのは承知しておりますが、スケジュールの決定はどのようになされたのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"保育園のご案内にもありますとおり、５年間の期間限定園という形でうたってまいりました。当然、優先転園にならないところもありますので、それは１０月中に終わらせないと来年４月の一般の募集の対応に影響が出てしまいます。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"もしかして、保育課内で、これからは報告・連絡・相談をしっかりとしていただくことを要望したいと考えています。そして、今後はなるべく早目にお知らせしていただくなど、園児と保護者の方のお気持ちや状況を考慮したスケジュール調整を要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"「当初決定の２０２１年３月から可能な限り延長頂くよう品川区に求めてください」ということなのですけれども、お話が出たとおり。延長の物理的な可能性というのはあるのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"こちらの開発にあたりましては、都市開発課が所管になりますので、私どもとしては、２０２１年３月以降にその予定があるということであれば、そこに従う形になります。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"詳しくは都市開発課のほうだと思うのですけれども、そういった契約がなされていて、仮に、こちらの保育課のほうで“延長してください”と言っても、それは難しいということでよろしいのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"この間、私が覚えているだけで平成３０年から何回か、所管の都市開発課を通じてＪＲ東日本にはお願いをしてきたところではありますが、延長するのは難しいという回答をいただいているところです。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"恐らく第２回のものだと思うのですけれども、「新しい事業者には、延長の可能性はあると知らせている」ということも記載されております。そうした延長可能性のことを言った程度、先ほどは一切ないというご答弁でしたけれども、改めてその辺りの区の認識としてはどうなのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"なかなか正式な形にはならないかと思いますので、今まで公式には「延ばす」だとか、そのような回答はしてきていないところです。今回予定どおりに５年間、２０２１年３月以降、区としても引っ張ることはできないという判断をした次第です。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"ある意味、期待権というのが失われたということに対しての区からの謝罪というか、そういったものはなされたのでしょうか。説明とか謝罪のようなものがあったのかどうかというのをお聞きします。","respondent":"吉田保育施設調整担当課長","answer":"この間、引っ越しできないか、それから既存園や来年度つくる保育園で吸収できないかというところを調整していたところがあります。早目にできなかったかどうかというところでは、ぎりぎりの線だったかなと考えております。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"優先転園に申し込まれた方が８６.７％いて、区のご説明を受けて、納得されたということなのでしょうか。優先転園を申し込まれた方の気持ちとかお考えを、区はどのように把握しているのか尋ねました。","respondent":"佐藤保育課長","answer":"まだ１年、令和３年４月に関しましても優先転園を行いますので、担当が細かく話を聞いて確認をしているところです。すべての方が１００％納得しているかというのはあれですけれども、ある程度、ご理解いただいて申請を出していただいていると考えております。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問","question":"これは参考としてお聞きしたいのですけれども、羽田新飛行ルートについては、ひろまち保育園の保護者の方というのはご存知なのでしょうか。区としても“羽田新飛行ルートの直下にありますよ”というご説明はされたのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"第３回定例会の時の文教委員会だったと思いますけれども、約２０デシベル現状より音が下がるような仕組みを付けるということを予定しております。その工事を年度内に行いますので、そういうものが付くというのは、そのルートの下にあるということに暗黙的には認める形になります。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"羽田新飛行ルートについて、ちょっと嫌だなとか、そうした否定的なご意見というのはあったのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"特に、直接こちらのほうにご意見だとかが届いていることは、今のところはございません。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほどせお委員から要望等がありましたけれども、そしてわかりやすく正確な情報が伝わるように、というところ。今回いただいたご意見もきちんと受けとめていただいて、今後に活かしていただくということで、会派としてもお願いしたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"ただ、１点だけ。可能性の示唆のところもそうですし、誤解の度合いがなるべく少ないように、これから心がけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"５年前にこの待機児童、当初５年限定ということが前提としてありつつ、確かに当時から聞いてはおりました。区として、今回、当初予定どおりでの閉園の決定をすることについてはやむを得ないと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"のだて委員","kind":"意見","question":"最初の８月２６日の報告があった際にも、私は延長すべきだということで主張をしてまいりました。新たな問題も発生してくるというところと、やはり議会として保護者の方々の思いを受けとめて、採択をしていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"今後はこうしたことがないように、ぜひしていただきたいと考えております。ただ、延長の可能性というのは客観的にほぼゼロだということを踏まえまして、趣旨を採択させていただきたいと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"計画がそこまでスピーディーに進む予定なのかどうかというところを私は疑問に思っているので、もう一押ししていただければとは思っています。ただ、先ほどほかの委員からもありましたけれども、他の園での保育事業をこれまで以上にきちんとしていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"筒井委員","kind":"意見","question":"わかりました。先ほど述べましたとおり、物理的に延長というのは不可能だということになっておりますので、不採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]},{"id":"topic-02","title":"令和元年特別区および東京都人事委員会勧告の概要","agenda":"令和元年特別区および東京都人事委員会勧告の概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"人事委員会からの意見というところで、長時間労働の是正ですとか、メンタルヘルス対策についてということで書かれておりますけれども、今の品川区の現状について伺えればと思います。","respondent":"工藤指導課長","answer":"例えば、授業の準備などの教員がなさなければいけない業務に集中できるような体制をつくるなど、さまざまな取り組みをしています。これらにつきましても、これまでの取り組みと同様、引き続き進めていきたいと考えているところです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"それはこの間、土日の打刻ができないということで言ってきましたけれども、それはできるようになったのか。勤務時間の実態を把握していかなければ、実際にどれだけ働いているのかということがわからないと思いますので、そこのところを伺いたいと思います。","respondent":"工藤指導課長","answer":"ご指摘いただきましたように、現状だと土日の勤務の部分がカウントできないというシステムの部分がございました。今、システム改変を行っているところですので、それを進めていきたいと考えているところです。","id":"exchange-027"}]},{"id":"topic-03","title":"令和元年度 各種学力調査の結果","agenda":"令和元年度 各種学力調査の結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"一部ご紹介がありましたが、生活習慣や学習環境に関する調査についてもご説明いただきたいというか。この結果が具体的にはどういった形で活かされていくのかというところをご説明ほしいと求めました。","respondent":"工藤指導課長","answer":"今後の活用につきましては、いただいたご意見をもとにしながら、やはり検討していきたいと考えています。同時に、より丁寧に、この場合は数学的解釈を説明するなどの授業展開を考えていくというふうに活かしていくように考えているところです。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"無答率が下がったというところもご説明がありましたけれども、ここについて分析があれば伺いたいと思います。小学生のころに詰め込み教育というのですか、そういった形で自分の知識として使えないというか、そこも含めて伺いたいと思います。","respondent":"工藤指導課長","answer":"そういった段階がありますので、各授業ではきちんと丁寧に指導するということで、学校には指導してまいりたいと考えているところがあります。やはり学習に対して意欲的に取り組む、いわゆる主体的な学びにおいても資する部分がありますので…","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"は１とか２とかという方もいるというところで、やはりこういった子どもたちへ支援をしていかなければならないと。今後の対応ですとか、その支援をやはりしっかりしていかなければいけないと思うのですけれども、いかがか尋ねました。","respondent":"工藤指導課長","answer":"今、ご指摘いただきましたように、例えば、四分位でいくとＤ層の子がＣ層に移るように課題を克服していくことが大事であると認識しています。今、品川地域未来塾を学校支援地域本部中心に進めてありますけれども、引き続き支援してまいりたいと考えているところです。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"義務教育ですので、取り残しというのですか、わからないまま進んでしまうということがないように、基礎の学力をつけていくということで、しっかりと対応していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"横山委員","kind":"意見","question":"１点だけお願いします。どういったことに活かしていけそうなのかというところを、区がどうお考えなのか、お聞かせいただけたらと思いますとの意見を述べました。","respondent":"工藤指導課長","answer":"結果としては、コンピュータも含めたＩＣＴを授業で活用したいというふうに肯定的に回答する児童・生徒ほど正答率が高いという傾向になったです。結果としては「当てはまる」「どちらかといえば…","id":"exchange-032"},{"speaker":"横山委員","kind":"意見","question":"先ほどの無答率を減らしていくというところですとか、ＩＣＴ等の最新の機器等を活用して、いろいろ工夫していただいていると思うのですけれども。先ほどの社会ですとか理科の課題にも何かつなげられるところがあるかと思いますので、ぜひ授業も十分に工夫してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"第７学年に進学する際に、私立中学などを受験する方がいて、そっちの私立中学に流れてしまっていることも、原因として考えられるのでしょうか。この第２学年から第６学年と第７学年から第９学年の差が出てしまうということについて、区としてはどのようにお考えになっているのか尋ねました。","respondent":"工藤指導課長","answer":"教育要領が本格実施するというこの時期を考えますと、今、まさに移行期です。授業改善を進めているところがありますので、授業改善を図るように、学校のほうに指導していきたいと考えているところです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"特に理科の成績が低いのかなと思うのですけれども、理科が弱いという理由はどのようにお考えなのでしょうか。その改善は何かお考えなのか尋ねました。","respondent":"工藤指導課長","answer":"まさに今、新しい学習指導要領等で言われていることを、特に理科において進めるところが必要であると。実験に若干時間がとられる部分があって、そういった改善も含めて進めていくことが改善につながるのではないかと考えているところはあります。","id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それとも、先ほどはやっていないというお話だったのでしょうか、その確認です。３年生（９年生）になったときに、公立高校を受験するためには社会と理科の力がかなり求められると思うのですが、３年生になったらまた３年生の社会。","respondent":"工藤指導課長","answer":"今後、児童・生徒アンケートの内容も含み考えながら、実施時期も含めて精査をしながら検討してまいりたいと思っているところです。英語、社会、そういったところで８年生の段階で補充に取り組むという事例はあるところではあります。","id":"exchange-036"}]},{"id":"topic-04","title":"改修工事および特別整理に伴う八潮図書館の休館","agenda":"改修工事および特別整理に伴う八潮図書館の休館","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"資料の４の利用制限等の(2)で、エレベーターが使用できないため、困難な方には、併設児童センター経由で連絡を受け、図書館職員が１階へ降り対応するとなっていますけれども、具体的には、いわゆる介助するとか、どんな感じなのか尋ねました。","respondent":"横山品川図書館長","answer":"委員ご指摘のとおりです。ゆたか図書館、ご連絡をいただいて階段を補助対応するようなことを行ってありますので、同じように八潮図書館でも対応する予定です。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"車椅子の方なんかも職員の方が抱えて運んでいらっしゃるという感じでしたけれども、それはやっぱり人海戦術ということでしょうか。駅の階段にあるような、上に上がっていく装置があって、みたいなのではなくて、基本的に人海戦術ということか尋ねました。","respondent":"横山品川図書館長","answer":"ご指摘いただきまして、ありがとうあります。工事期間１か月の間で設置するのが困難であることと、設置については、今回は見送らせていただきたいと考えています。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/211588?Template=document&Id=4982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":29371,"voices":99}},{"id":"r01-20191111-5","meetingId":"r01-cm11","date":"2019年11月11日","dateIso":"2019-11-11","committee":"総務委員会","time":"午後 １時００分～午後 ３時１７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"予算編成過程の公表","agenda":"予算編成過程の公表","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"少し伺いますけれども、予算編成過程の透明化を図る目的を改めてご説明ほしいと求めました。それと、こうした形で公表している他区の動きですけれども、２３区ではどういう動きになっているのか、そこもお知らせほしいと求めました。","respondent":"品川財政課長","answer":"委員のご質問でありますように、２３区でも、大体半分以上の区が、この予算編成過程の公表を進めているという状況です。今回いろいろ検討してきたのですが、今回、このような形で公表するものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それとも１２月中と言われると委員会の開催の日程も含めて、区議会、報告というものはどのように考えているのか伺いたいと思います。その点についてはいかがか尋ねました。","respondent":"品川財政課長","answer":"本日、こういう趣旨で公表するというところを議会報告としまして、後の数字の公表の部分については、そのまま公表していきたいと考えております。今、説明をしてしまいましたが、やはりそこは予算特別委員会の中でやっていくべきだと考えております。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"差額の５００万円以上の場合は理由を表記するということだったのですが、この５００万円の根拠をお知らせください。ホームページでの記載がＰＤＦということだったのですけれども、これは視覚障害の方たちが読み取ることはできるかというところを確認させてください。","respondent":"品川財政課長","answer":"そういう面ではほかの区とレベルを合わせておくということを考えて、今回については５００万円という形にしております。それから、ＰＤＦの視覚障害の方への対応については、検討材料として考えします。","id":"exchange-003"},{"speaker":"田中委員","kind":"意見","question":"この予算編成が公表されるということは、目的とする透明化を図るためという部分や情報公開の部分で一歩進んだなということでとても歓迎したいのですけれども、やはり視覚障害の方たち、どの方たちからも見られるようになってほしいと思うのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"これはどうしてこうなったのだとか、どうして増えたのだとか、それが短い１行でも２行でもいいから書かれていないと、やはり質問したくなる。それで、質問しようとして、「いや、細かい点はお答えできません」となれば、結局、透明性というものはなくなってしまうではないか尋ねました。","respondent":"品川財政課長","answer":"やはり事業の説明から出している区もあれば、これは後々、公表の仕方の統一化が見えてくるのではないかなと予想されるところがあります。現時点ではこのように公表して、これから区民の皆様のご意見等も踏まえて、表記の仕方も考えていきたいと考えています。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"それぞれ各自治体がどういう方向で持ってくるかわかりませんが、その辺は簡単な説明表記みたいなものをそこに少しつけ加える。長くならないようにやるというのは難しいと思うのですけれども、何か検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"西本委員","kind":"意見","question":"この後、１カ月間かけて審議をするわけです。それをどういう形で表現するのかとの意見を述べました。","respondent":"品川財政課長","answer":"詳細の説明のところについては、今のところ、基本的にはそのような考えです。そのような考えです。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"確認しますが、区民の方が要求されれば、そこまでは出しますよということでよろしいのですか。本当に誤解されると思うので、その辺はいかがか尋ねました。","respondent":"品川財政課長","answer":"当然、情報の公開の要求があれば、それに対応していくです。これが最終的であると書いておりますが、今の委員のご意見も踏まえて、ホームページの表記方法もこれから考えていきたいと考えています。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、もう少しかみ砕いた形で、このようにやっていって、そして、このデータはここの位置づけなのです。最終というのは、３月に議決という形になりますというところを明確にしていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"予算案をつくるのは区長であって、それを議会が審議して、可決されてから執行される。確かに住民から見ると、ここはご答弁もありましたけれども、解説なりわかりやすさを工夫していただきたいと要望だけしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"つる副委員長","kind":"質問・要望","question":"本題のところとは違いますが、ＰＤＦのところの確認で、先ほど質疑があって、検討というご答弁がありました。そのあたりについて、しっかりと対応をしていただきたいという視点でご答弁をお願いしたいと思います。","respondent":"品川財政課長","answer":"この代わりになるものとなれば、基本的には音声サービスという形になると思います。対応として、それがどれぐらいかかるかというところを考えながら、やっていかなければいけないと現在考えております。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"少し確認というか、要望というか、お伺いしたいのです。区民の方により情報が伝わるかなと思ったのですけれども、その辺の検討はどのようにされたのかということを伺いたいと思います。","respondent":"品川財政課長","answer":"いろいろ実施している区などを見て考えたところで言いますと、事項別見積書を出しているというのは、私の調べた限りではないというところがあります。ある程度の部分としては要求額まででとどめておくというところが現在の考えではないかなということで、今…","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"見られないですか。どこに行ったらそれが見られるかということが、注意書きでも書いてあったらいいかなと思ったのですけれども、いかがか尋ねました。","respondent":"品川財政課長","answer":"閲覧ができる、できないというところは、あくまでそこの段階のものです。予算要求時点でのものというところは、現在のところ出しているところはございません。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"私が求めているのは、今答弁いただいた見られる場所などを記載していただけたら、区民の方が見に行けるかな、区民の方にとってわかりやすいかなということを伝えたくて、ご説明あった１文を記載してほしいなと思っていますが、いかがか尋ねました。","respondent":"品川財政課長","answer":"これは、あくまで予算編成過程のものですので、予算案のもので出してしまうと、それは非常に混乱を来してしまうので、それを公表する考えはございません。","id":"exchange-014"}]},{"id":"topic-02","title":"令和元年職員の給与等に関する報告及び勧告の概要","agenda":"令和元年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そこを単純に伺いたいというのが１つです。そこもあわせて伺いたいと思います。","respondent":"黒田人事課長","answer":"２点目の人事委員会の考え方ですが、先ほどご説明しました１ページ目の４の「本年の公民較差算出」というところで、見直した給与表の額を超えている。８層制を６層制に変えている関係で、マイナス５,８１９円ということですので、今回見直されたです。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"その辺、あくまで人事委員会が決めたことなのですが、区としてはどのように思っているのですか。少しご見解を説明を求めました。","respondent":"黒田人事課長","answer":"今回０.１５月となりましたのは、そこの部分は実施していないというところで言えば、プラスとなっているというものです。５０人がどうかですが、特別区人事委員会が国の人事院および全国の人事委員会と共同して実施しているというものです。","id":"exchange-016"},{"speaker":"須貝委員","kind":"意見","question":"実際、これだけボーナスも上がっているのだよという考え方を持って、認識をして見ているのかどうか。そこに対して、もう一回、見解だけ説明を求めました。","respondent":"黒田人事課長","answer":"特別区の人事委員会が特別区内の事業所を中心として調査しているですので、品川区に限って何か調査をしているというところではございません。品川区の事業所と比べるとどうかというところは、この調査からは、なかなか導き出せないのかなと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"いや、やはり私は勧告をやっているところに対して、何かおかしいのではないかという投げかけはするべきではないかなと思うのです。区民の皆様の理解を得られるかどうか、一応意見として、今回申し上げさせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"特別区は人事委員会の調査に基づいて、統一した考えのもとでやっているとは言いつつも、今後、これに従っていかなければいけないのですか。それに見合った給料体系というものが、当然必要になってくるのではないかと思うのですが、その辺の考え方はいかがか尋ねました。","respondent":"黒田人事課長","answer":"当然、２３区一体となって採用も含めて任用制度を定めているという中で、いわゆる労使交渉も２３区と特別区長会という形で進めております。そういった国の議論も含めて、今後、どのように公務員制度が変わるかということを注視しています。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"再任用については、教員なども既に国の流れで、多分７０歳近いところまでいくのではないですか。ぜひとも重要な情報があったら総務委員会にも上げていただいて、一緒に考えていきたいと思いますので、これは意見で終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]},{"id":"topic-03","title":"水辺のライトアップ整備工事（かもめ橋）請負契約","agenda":"水辺のライトアップ整備工事（かもめ橋）請負契約","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"毎回、予定価格について伺っているのですけれども、説明資料の中に記してほしいということを求めているのです。そういった、この契約が正しいかどうかの判断材料になるのではないかなと思うのですけれども、どう考えられたのかというところを伺いたいです。","respondent":"立木経理課長","answer":"こちらの予定価格は、積算単価表を使いまして計算しているものですので、そちらは妥当なものかと考えております。他の入札案件等への影響も考えられますので、こういった形で予定価格総額ということで出させていただいているところです。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、議会での説明ということで、契約にかかわる報告ですので、予定価格がこのように積算されてこの額になったということが、これでは全然わからないので、そういった資料作成をしていただきたいなということを求めます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"その辺について、少しご見解を伺いたいと思います。その割合など、歳入と言ったらいいのか尋ねました。","respondent":"柏原企画調整課長","answer":"まさに我々がいろいろ検討しなくてはいけない部分もありますし、長期基本計画の実施計画の中で、今まさに検討して。環境の面を考えて、その制度も使いながら、財源として入れられるものについてはいろいろな財源を使いながらというところで検討しているものです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"大井町は年間で５,０００万円ぐらいかかっています。今回は１億２,０００万円ということで、こうした事業の展開についていろいろ検討していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"西本委員","kind":"確認","question":"確認だけです。そういう詳細にわたっての比較をしながら落札をするという形になっているのか尋ねました。","respondent":"立木経理課長","answer":"こちらは制限付き一般入札ですので、予定価格内で最低制限価格を上回った金額で一番安い札を入れた事業者が落札という形になります。こちらの大きな金額のものに関しましては、予定価格と最低制限価格があります。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"決定したところに、詳細にわたってチェックを入れるということでよろしいのでしょうか。やはり４００万円というのがかなり差があるので、いいのかなと疑問を持ったのですけれども、いかがか尋ねました。","respondent":"立木経理課長","answer":"落札の仕方につきましては、委員がお話しされたとおり、予定価格以内の最低制限価格以上で最も安い金額が入ったところになります。そのような形になってありますので、詳細なチェックでということではなく、金額の総額で決めているです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"先ほどの最低制限価格というのは、事業者のほうには公表されているのか尋ねました。","respondent":"立木経理課長","answer":"最低制限価格は非公表となっていますので、事後でも公表はいたしません。結局くじ引きで、それこそ適切な金額で積算されているかどうかが担保できませんので、非公表という形になっております。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"翌年は、翌年にライトアップを設置するときは、値段的には相当安くなるのですかということを教えてください。保管は、今回入札した会社が保管して、管理・維持しているのか尋ねました。","respondent":"立木経理課長","answer":"工期は令和２年３月１９日ということで、また来年度、追加工事が出るということではございません。一度つけてしまえば、あとはランニングコスト、維持費だけということになるかと思います。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"毎年つけるのではないですか。〔「つけない」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"勘違いした。説明を求めました。","respondent":"立木経理課長","answer":"こちらの工事で据えつけてしまうものでございまして、期間が終わったら取り外すということではなく、常設、そのまま固定してまいります。ですので、ランニングコストは電気代と、定期的なメンテナンス等ぐらいかと思います。","id":"exchange-030"}]},{"id":"topic-04","title":"ふるさと納税（寄附金）事業の新たな展開","agenda":"ふるさと納税（寄附金）事業の新たな展開","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"応援していただけるための機会を増やす」ということは、つまり、何かポスターでもつくるのですか。寄附をしたらどんな体験や何が返ってくるのか、イメージがよくわからないのでもう少しご説明いただきたい。","respondent":"伊東税務課長","answer":"体験型返礼品に関しましては、まだ、これは今年度どうこうという話ではなくて、検討を進めていきたいです。一緒になってそういう開発の検討を進めていこうです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"確認","question":"要するに、品川区がやっているふるさと納税事業をＰＲするということなのですか。改めて確認したいと思います。","respondent":"伊東税務課長","answer":"今のものはふるさとチョイスにも「品川区とは」というところで載っているのですけれども、そのようなところは当然並行でやります。それにプラスアルファとして、その辺の中身についてはこれから検討しますけれども、そのようなことを含めてＰＲをしていくという形です。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"品川区だけなので、何でかなと疑問に思ったので、そこを伺いたい。これを掲載するにあたって、その全体的な予算というのは幾らぐらいになっているのかというところをお知らせください。","respondent":"伊東税務課長","answer":"それと、カード決済する場合には、１％の手数料がとられるということで、トータル寄附額の８％がかかるという形です。先ほど言った７％と１％という中ですので、今回、実施したところです。","id":"exchange-033"},{"speaker":"田中委員","kind":"意見","question":"ちなみに、先ほど、体験型返礼品の検討ということで、東急とのオリジナルをつくっていくことを検討していくというお話があったと思うのです。体験型のイメージがつかないので、今の議論の中でどのような感じかなというイメージがもしあればお知らせほしいと求めました。","respondent":"伊東税務課長","answer":"１案としては、屋形船のクルーズやしながわ水族館のナイトアクアリウムプランなど、そのようなイメージ。これから少し詰めていって、具体化できれば、新年度にできるかなということです。","id":"exchange-034"},{"speaker":"須貝委員","kind":"提案","question":"総務省に提案していただいて、１０億円なのか、これは本当にお金の取り合いになってしまうと思うのです。それだけ少し意見を言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"「周知方法」で、「品川区ホームページにて」というのは、どこを見ればいいのですか。どこに書いてあるのか尋ねました。","respondent":"伊東税務課長","answer":"その中で、先ほど、ほかの委員からお話があった、ふるさとチョイスと東急のふるさとパレットのサイトに入っていけるような形になっています。これから順次返礼品の制作者といいますか、つくっている方から見たＰＲという部分など、さまざまな形でアップするという形です。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"このふるさとパレットというところが、東急のサイトになるということですか。東急とどのような話をされていますか。","respondent":"伊東税務課長","answer":"先ほども少し言いましたけれども、その中で１,８００ぐらいの自治体が登録されているという中では、どうしても埋もれてしまう。１つ今まで以上に掘り起こしができるのではないかというところで、そういう広告媒体も活用させていただけるのがいいのかなと思っているところです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"非常にいろいろなところで目につくよという仕掛けをしましょうということだと思うので、そういう意味で大切なことかと思うのです。もう少し東急といろいろやっているよという宣伝のような形ができるといいのかと思いますけれども、今後やっていただきたいなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"大倉委員","kind":"質問","question":"こういうものはどうですかと売り込んでいかないと、もっとこういうものがありますよというお話が東急とできないといけないかなと思います。やはり金額も３割というのが、東急とどうやっていくかというところは、どのように考えているか教えてほしいと求めました。","respondent":"伊東税務課長","answer":"連携というところでは、体験型に関しても地域、品川区なら品川区の部分で考えていかなくてはいけないというところがあります。シナモロールは３割ぐらいというところでやっていますので、当然３割ぐらいの形を見ていかないと、その辺の設定は少し考えするということであります。","id":"exchange-039"}]},{"id":"topic-05","title":"ふるさと納税（寄附金）の返礼品追加","agenda":"ふるさと納税（寄附金）の返礼品追加","exchanges":[{"speaker":"西本委員","kind":"意見","question":"欲しがるかな、どうなのかなという声があるのです。少し不安なのですが、その辺はどういう議論の中でこれをつくり、それをふるさと納税品の返礼品にしようとされたのかとの意見を述べました。","respondent":"伊東税務課長","answer":"寄附者から見れば、制度はご存じのとおり２,０００円の負担ということになりますので、単純に考えれば２,０００円で返礼品がもらえる。現状で１６０件ほど出ているという状況と、新たに１１月からですので、４件出ているという状況です。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"これをやっていくと、やはりそういう状況だということを区長をはじめ、議長がいろいろなところで発信していただきたいなと考えています。その辺はいかがか尋ねました。","respondent":"伊東税務課長","answer":"今年６月に税制改正がされて、まだまだ伸びしろがありますので、少し厳しい状況です。では受け入れのほうも少し考えながら、自分の形を推し進めつつ、しばらくはやっていかなくてはいけないかなと思っているところです。","id":"exchange-041"},{"speaker":"大倉委員","kind":"質問・要望","question":"３０％のものをつくったときに、ほかのものは１５％や１０％というのは、例えば額の変更などが可能なのかどうなのか。３０％にしてほしいというよりは、大井町などの体験も含めて、いかがか尋ねました。","respondent":"伊東税務課長","answer":"それだと５,０００円ぐらいですから、全然３０％にいっていないという状況です。それによって５万円にしたり、２万円にしたり、寄附額とそれにかかる必要経費のバランスを少し考えていかなくてはいけないということです。","id":"exchange-042"}]},{"id":"topic-06","title":"みずほ銀行品川区役所出張所の業務形態の変更","agenda":"みずほ銀行品川区役所出張所の業務形態の変更","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"今の報告は、要するにみずほ銀行から品川区にそういう報告があったということでいいのか、品川区からみずほ銀行にお願いをするということはあり得ないとは思うのですけれども、そこを１点確認したいと思います。","respondent":"齋藤会計管理者","answer":"私どもとしても、利便性を損ないますので、何とかこの形態でということで、繰り返しお願い、ご協議は申し上げておりましたが、いかんともしがたいということでございました。","id":"exchange-043"},{"speaker":"中塚委員","kind":"意見","question":"やはり区民サービスを思うと、出張所という機能が続くことが望ましいと思いますし、みずほ銀行がそうだと言われれば、どう抵抗していいのかわからない部分はありますが、残念ですと述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"恐らく職員の方々の利用が多いのではないのですか。いろいろ議論があったのでしょうけれども、職員の方々はかなり不便になるのではないかなと思ったのですけれども、いかがか尋ねました。","respondent":"齋藤会計管理者","answer":"職員がどれだけ口座を持っているかというのは、個人情報にもかかわることでございまして、私からはお答えしづらいというところであります。通帳がいっぱいになった、青物横丁の支店まで行かなければいけなくなってしまいますので、そういう意味では確かに利便性は損ないます。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"１つの要求として、通帳が満杯になったときに、つくってくれるものがあるではないですか。そういう要求は難しいか尋ねました。","respondent":"齋藤会計管理者","answer":"少し協議をさせていただきたいと思います。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問","question":"これは局長に聞かなければいけないのですけれども、政務活動費や名義を変えるなど云々あったときに、大井町支店でもいいのでしょうか。そちらがそのようになるならば、何かそういうことも考えていくべきではないかなと今思いましたので、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993969?Template=document&Id=2148#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":36993,"voices":126}},{"id":"r01-20191112-14","meetingId":"r01-cm11","date":"2019年11月12日","dateIso":"2019-11-12","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時０８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"区組織と関連団体に関すること","agenda":"区組織と関連団体に関すること","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"私が誤解しているのかもしれませんけれども、区の助成事業のところなのですが、２億７,５５２万５,０００円、これが助成金ということなのですよね。この助成金は、事業全体にかかっている費用の何％ぐらいなのか尋ねました。","respondent":"古巻文化観光課長","answer":"平成３０年度で言いますと、財団の会計資料から正しく読み取れているかというのが難しい部分があるのですけれども、事業全体の金額が４億５,６００万円という報告を受けておりますので、そのうちの２億７,０００万円ほどが助成金として区から支出されているという状態です。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"わかりました。それで、逆に助成金なしの事業というのは、ほかにあったりするのか尋ねました。","respondent":"古巻文化観光課長","answer":"助成金の対象外となっているものとしては、文化振興事業団の収益事業として、グッズの販売であったり、そういったようなところです。それから、建物の維持管理であったり、そのあたりは指定管理として行っていただいているという形になってあります。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"労務チェックというのですか、今、チェックをやっていると思うのです。そこについてお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"企画部門が指定管理者に対して、社会保険労務士にお願いして、順次確認していただいているといった状況です。文化振興事業団におきましては、現段階ではチェックはまだ入っていないですけれども、順次やっていく予定です。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"定款というのですか、自治体のものを横引きにしているがゆえに、民間ではあり得ないような内容になっているところもあったようです。指定管理の発注元として、そういったこともぜひ行ってほしいと求めましたが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"４年目の段階でそういったことでのチェックを入れて、データになるようにというようなことも考えておりますので、体制を組んでいきたいと思ってあります。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"よろしくお願いします。体制が整ってからで結構ですので、議会にもお示しほしいと求めましたが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"指定管理のその部分に関しましては、労働環境チェック、プラス、いろいろなチェックといいますか、やっていきたいと思っていますので、トータルの中で、そういったチェックした内容についても、当然議会にもご報告させていただきながら進めていきたいと思ってあります。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、現在の事務局長は元幹部職員であったのか、そういう経験があったのかどうかも伺いたいのが２点です。この財団自体は昭和６１年に設立されたということですけれども、いつごろから行われていることなのか、それもお伺いしたいと思います。","respondent":"榎本総務部長","answer":"それで、昭和６１年からどうなっていたかということですけれども、昭和６１年のときには、たしか総合区民会館は直営で区がやっておりました。事務局長については、区の現役もしくはＯＢという形で変遷してきていると思います。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"現在の事務局長は、今４名の元幹部職員の方が再就職されているということですが、事務局に入っているのかどうか、お伺いしたいので、もう一度お願いします。","respondent":"榎本総務部長","answer":"事務局についても、全員ではありませんけれども、係長級のＯＢの方が何人か入っているということです。今現在の事務局長は、中山武志です。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"事務局長ですね、こういうところのいわゆる報酬というのは年間どれぐらいになるのかというのは、公開されているものなのでしょうか。公益財団法人という性格そのものがかなり公益性が強いところだと思いますので、そこら辺をお伺いしたいと思います。","respondent":"榎本総務部長","answer":"インターネットで全部、公益法人というのは出すような形になっていますので、その中で明らかになっていると思います。それぞれ団体の特性がありますので、団体の中で判断をしていると思いますが、それはわずかなものと考えております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的には２点お伺いしますけれども、補助金要綱の第４条２項に、この条件を付すということはどれぐらい行われているのか。この第９条の是正のための措置についても、実際にこういう実績はあるのかどうか、伺いたいと思います。","respondent":"古巻文化観光課長","answer":"そういったことはありますけれども、その中できちんと条件に合ったものが補助金の対象となっているということであると認識しております。その結果として、何か是正が必要になってくるものというのは、特に今まで事例はないと認識しております。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"ただ、あるいは文化振興事業団としての独自性というところですか、できないのではないかという不安というか疑問も当然のことかと思います。そこら辺の体制というのは正していく必要があると思うのですけれども、そこについて、現状の認識を伺います。","respondent":"榎本総務部長","answer":"要は指定管理の施設運営の継続性が危ぶまれるようなことがあったり、そういうことになると区民が利用できなくなるわけですから。きちんと信頼できるところにお金が入るわけですから、そういうものについては今後も必要に応じて検討していかなければならないと考えています。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"区からの派遣が３人、そして元管理職が４名入られているということで、事務局長は元管理職の方ですよね。３２名の方がそれぞれ何人ずつ、どこにどう配置されているのかというのを伺いたいと思います。","respondent":"榎本総務部長","answer":"係長を置いてある組織と置いていない組織がありまして、係長を置いてある組織につきましては、４人の係長がＯＢで入っています。それから係長を置いていない組織についても、ＯＢが係員として何人か入っているという形です。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"ＯＢのところは、ありがとうあります。その上で、それぞれのところ、３２名の職員の方の配置の内訳をお聞きしたいなと思います。","respondent":"古巻文化観光課長","answer":"文化振興係が係長含めて３名の体制。それからメイプルセンターは、館長がおりまして、館長含めて５名の体制ということで、職員についてはそういった形になっております。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"こうした３２名の方々で、静かなクラシックとか、そういったものができなくなっていくのではないかなと。できなくなるようなまちへの変化に対して、文化振興事業団としてはどのようにお考えなのか、伺いたいと思います。","respondent":"古巻文化観光課長","answer":"そういったところに柔軟に対応できる体制として文化振興事業団が存在していると考えていますので、そういった形で今後も適切に文化芸術活動のいろいろな対応だったり事業の実施だったり、文化振興事業団もそういうふうに考えて事業を実施していると考えております。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういった中で、文化芸術を今までどおりに守っていくというのが本当に困難になるのだなと改めて思っております。区民の文化芸術を守っていく、魅力的なまちづくりに寄与していくというこの目的を達成する立場で、引き続き運営を進めていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"確認","question":"文化振興事業団、いろいろ頑張ってもらっているし、区民芸術祭も大分人も増えていると聞いています。その上で確認なのですが、前年度よりも５００万円減ってきている、ここら辺の理由をまず説明を求めました。","respondent":"古巻文化観光課長","answer":"特に平成３０年度は、イベントホールの収益が少し減っているというところがあって、恐らくこの差が出てきたのではないかなと考えております。そういった大きなイベントがあった関係で利用料収入が増えて、指定管理料が減っているという流れになっていると認識しております。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"年度別にどうなっているのですかと聞こうと思ったのだけれども、今、年間の支出２億４,２００万円というのが大体そこら辺の数字を見ているのか。今やっている７階の改修があるから、今お手元では、単年度分の収入というのは出していないのか尋ねました。","respondent":"古巻文化観光課長","answer":"今年度予算が３億２,０００万円ほどになっておりますけれども、こちらの中身につきましては、文化観光課の予算上はついていない形です。そういった部分が６,３００万円ほどになっておりますので…","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"意見","question":"まちづくり系のほうの予算ということになるのかどうかわからないですけれども、区は予算を出していませんよということになってしまうみたいな感じになるけれども、そうではないですよねとの意見を述べました。","respondent":"古巻文化観光課長","answer":"そういった意味では、全体の中ではお金がかかっている部分については区から出ております。今年度、文化観光課の内訳には載っておりませんが、全体の中で組み上げて予算を執行しているような状況だという認識です。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"そして、区から派遣で３人いらっしゃるということですが、これは例えば区の職員の中でそれぞれ役職を持った方がこちらに派遣されているのでしょうか。説明を求めました。","respondent":"榎本総務部長","answer":"２人は係員で、若い職員です。３２名のうち、区のＯＢの管理職については、理事長含むと４名です。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいのですが、今言われた方以外の方の採用は、品川文化振興事業団でやっているのですか。それとも品川区で担当されているのか尋ねました。","respondent":"榎本総務部長","answer":"事業団の固有の職員については事業団でやっております。配置できるかできないかということがありますので、その辺を調整の上、配置するという形になります。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"実際、文化振興事業団で採用しているならば、私は品川区からわざわざ職員を派遣するというのはいかがなものか、おかしいのではないかと思うのです。なぜそういうふうにしなければいけないのか、疑問に思うのですが、その辺について説明を求めました。","respondent":"榎本総務部長","answer":"２０代後半から３０代前半の職員に、民間の会計も含めて勉強してきてもらうという意味で、それぞれ派遣に出しています。期間限定の派遣をしてということで、ずっと文化振興事業団にいるという形ではありませんので、そういう形での派遣の形態です。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"大半の区の文化振興、観光もそうですけれども、区の部局でそれぞれやっているわけではないですか。品川区は品川区で、貴重な職員ですから、これからの区を支えていっていただくというのが職員を育てるという人事の原則だと私は思うのです。","respondent":"榎本総務部長","answer":"それ以外に、そういう別の組織に行ってそれぞれやり方を覚えてきてもらって人材育成をするというやり方もずっととっております。人事当局としてはこれを少なくしていきたいと考えていますが、事業の継続性なり、必要な人員を派遣しているという形です。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"大まか、よくわかりましたが、ややもすると、結局こうやって派遣して、品川区の庁舎の中の職員定数を超えないために、わざわざ外へ出しているような対応にも見られかねないので、私は各事業団でそれぞれ人を育てていただいて、品川区のために尽くしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお伺いしたいのですけれども、そうしたところを帰宅困難者に避難所として開設するなんていう場面ももしかしたらあるかもしれない。その辺を参考までにお伺いしたいと思います。","respondent":"古巻文化観光課長","answer":"災害時の対応ですけれども、施設といたしましては、区と協定に基づいた施設の開放を行っていただくような形をとっております。それぞれお客様を入れる施設ですから、そういった方々に対しての備蓄もされていると伺っております。","id":"exchange-023"},{"speaker":"こんの委員","kind":"確認","question":"考え方をお伺いしたいのと、そこ独自の例えば災害対応、何か災害があったときに利用者への対応とかというのは独自でマニュアルみたいなのがあるのか。対応マニュアルなどがあって、そこも訓練をされているのか、確認させてください。","respondent":"古巻文化観光課長","answer":"そういった形での訓練はされていると認識しておりますし、また、危機管理に対してもしっかり対応できるような体制を組むようにということは。スクエア荏原ですけれども、区の帰宅困難者対策の中で必要なことについて検討して…","id":"exchange-024"},{"speaker":"こんの委員","kind":"質問・要望","question":"確認をすべきところは確認をしながら進めてくださるということですので、災害時の対応も確認させていただきましたので、より一層確認をしながら。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"ご出席というか、文化振興ではなくて、文化観光の切り口でのやりとりをしていいものか。そこの理由を教えていただきたい。","respondent":"古巻文化観光課長","answer":"文化振興事業団に関しましては、庁内の所管は文化観光課ですので、そういった立場で私が本日出席さていただきまして、ご説明、また、必要に応じて答弁をさせていただいているです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"確認させていただきたいのですけれども、これはあえて改めて確認したいのが、いわゆる給料というのは文化振興事業団が持つということでよろしかったかということを確認したいと思います。","respondent":"榎本総務部長","answer":"それから給料につきましては、現役の職員については区で給料を出しております。それ以外のＯＢについては、事業団の職員ですので、事業団が支給するという取り決めになっております。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/990135?Template=document&Id=6078#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":18442,"voices":66}},{"id":"r01-20191113-18","meetingId":"r01-cm11","date":"2019年11月13日","dateIso":"2019-11-13","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時５８分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"先ほど視察の中で、いろいろな話の節々で、組織委員会からなかなか情報が入ってこないという話をよく耳にしまして、そういうところで品川区として、狭間にあったといいますか、どのような形で情報提供していく方向に持っていくのか、お考えをお聞きしたいと思うのですけれども、お願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回のまちづくりの協議会がいろいろ取り組んでいる内容につきましては、いろいろ情報交換をしながら、一緒に進めているところです。それが１つのルートで、正しい情報を正確に伝えるように苦労しているといいますか、しています。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"それは具体的にどのぐらいの人数の職員の方が、どのぐらいの期間で出向、派遣といいますか、されているのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"２桁台の人数の職員が今行っておりまして、あと、建築関係の職員も行っております。組織委員会や東京都の管理職クラスの方とはつながりがありますので、そういったルートを通していろいろな形で情報をとるようにしております。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問・要望","question":"引き続き情報収集に努めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"宿泊、寺小屋事業などについて先ほど勉強させていただきましたけれども、このほかで品川区で考えている文化プログラムというのはあるのでしょうか。例えば、２６号線のお神輿のように、またお神輿をやるとか、何かそういったものというのはお考えはありますか。","respondent":"古巻文化観光課長","answer":"これは来年度も予定しておりますし、東京都の指定になっている文化プログラムという形で今年度させていただきましたけれども、ＧＯＯＤ ＰＡＲＫ！共催したり、支援したり、そういった形でたくさんのことをさせていただいています。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、委員長のほうから、６９件の文化プログラムのご紹介をということでお伺いさせていただきました。逆に、町会・自治会は２００ぐらいあると思いますけれども、どれくらいあるのかというところを教えていただきたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"青少年対策地区委員会のほうで、何かオリパラに関するイベントをしたときは、やはり助成金を出しますよということでやっている地区が多々あるように聞いております。","id":"exchange-005","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"質問・要望","question":"助成金があることでの文化プログラムの認定ではなかったですよね。八潮がどうやってオリンピックの盛り上げに貢献できるのかという、品川区として何かお考えがあるのか、教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"さまざまな形で取り組みが可能だと思いますので、ぜひこれは協力し合いながら、やっていきたいと思っています。８月のホッケーのテストイベントの際には、今後も地域の方にご協力をいただきながら、盛り上げていきたいと思っています。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"今日、視察をさせていただきまして、寺ｃａｆｅですとか、宿坊のお話ですとか、いろいろ伺いました。寺ｃａｆｅのほうでは３００万円、そこの予算の面と、区としてのかかわりのところで伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"共催プログラムといいまして、全国の自治体や非営利団体などと連携してやるものというもので、今のところ１３件ぐらいは発表になっています。寺ｃａｆｅは、先ほど説明の中で３００万円というお話があったと思うのですが、それをそのまま負担金としてお渡ししています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"お金のほうは１,５００万円、だから、そちらでどう使うかというのは決めていくということになるのですかね。実証実験をどうしていくということと、今後、改善して、本格的な事業にしていくということなのか、伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しながわ学という、文化観光課の生涯学習係がやっている立正大学との連携講座、東京２０２０参画プログラムはかなりたくさんやっております。余計なサービスは切ってしまうですとか、そういった作業をしまして、来年度につなげるという予定になっております。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、区がこの事業にどうかかわっていくかというところは、ご答弁あったのでしょうか。どういう形で実証実験の結果を踏まえて、どうやっていくのかということも含めてなのですが、そういったところを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"企画自体は、その後の相談等は一緒にタッグを組んでやっているところですので、どちらかが先導してやってしまっているという形でもございません。定期的に相談し合いながらといいますか、まちの会議にオブザーバーで参加することもありますし…","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"こうしたことをやりたいというか、認定基準というか、そういったものはどのようにして決めているのか。区としてこうあってほしいというイメージがあれば、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"自分が体を動かすのが別に好きでなくても、区全体でみんなで盛り上げていきましょうという機運を上げたいという、それが一番大きなところです。バッジをつけて、みんなで連帯感を持って臨んでいきましょうというような、そんな思いを込めているところです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。今まで申請してこられた方に対して、お断りしたとか、そうした断ったケースというのはあったのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"お断りしたケースは、私が記憶している中ではございません。","id":"exchange-011"}]},{"id":"topic-02","title":"コロンビア共和国のホストタウン登録","agenda":"コロンビア共和国のホストタウン登録","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ホストタウンになると何が変わるのかというか、何ができるようになるのか、そこを伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これは何かいいことがあるのかということなのですが、地域によっては、交流をした金額の２分の１程度が特別交付税で交付されるということがあります。お墨付きをもらうということが１つと、大きくＰＲすることにもなりますので…","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"品川区が認められたというのは、具体的にオリパラの、パラ・パワーリフティングの視察に行きましたけれども、要は、障害者に優しいとか、いろいろおっしゃっていましたけれども、そういう取り組みが評価されて、品川区が認められたものなのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京２０２０大会時の交流の予定、まちとしてバリアフリーが進んでいるとか、そういうところは特に申請時の要件としては入ってはおりませんでした。特に大事にされていたのは、地域の住民と同国の交流があるかどうかというところでございました。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"資料の最後のほうに、今後もホストタウンとして事前キャンプ実施の支援を行うとともに、子どもたちや地域住民との交流などを行うことでという予定といいますか、それが書いてありますけれども、今、具体的に何か既に計画されていることとかがあれば、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"聞くところによりますと、試合前というのは皆さんぴりぴりしているといいますか、なかなか交流は難しいのではないかという話を聞くところもあります。どのぐらいの人が来て、どんな交流ができるかという具体的なことはまだ来年入ってからになってしまうかと思っているところです。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"もしそういうことを既に考えられているのでしたらお知らせほしいと求めましたし、本当に文化同士の交流みたいなものを計画していただきたいと思うのですが、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今、文化的な理解ですとか、歴史的なことを学んだりということも大切なのではないかというお話です。そういったところとも連携しながら、何かうまい形で、これも品川区全体で盛り上げていくということは考えていきたいと思います。","id":"exchange-015"},{"speaker":"つる委員","kind":"確認","question":"品川区、２３区を含めてそうでしょうけれども、そういう財政的な支援は一切ないという認識でいいのかという確認をまずさせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、財政的な措置は一切ございません。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"その辺の継続性というのでしょうか、それをしているのかどうかというところと、そのあたりの関係性の濃淡というのでしょうか。先ほどあったとおり、かなり優先順位が高いということもあると思うのですけれども、そのあたりについてまず考え方を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"コロンビア以外のホストタウン登録の予定はあるかということなのですが、あとは、今のところはないというふうにお答えをします。事前キャンプをこれ以上受け入れる予定は今のところ、ございませんので、そういった方向で今のところ考えているところです。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"スペイン語圏にかかわる文化を今まで以上にどう伝えるか。このあたりについて、予算の関係もあるのかもしれませんけれども、お答えになれる範囲で伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今までですと、コロンビア共和国の紹介ということで、広報しながわで年１回ぐらいは載せていたというぐらいだったと思います。スペイン語も、なかなかステップ１から学ぶというのも難しいので、そういったところはこれからいろいろ考えていきたいと考えています。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"ですから、世界で見れば、使われている言語としては第２位なのです。何かそういう応援をできる機会を区民に与えることができるのかどうかという、この辺がわかれば、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、まだ何日にどの選手が出るかというのが、難しいところなのです。期待値も込めて用意するというのもあるのかと思いますが、そこのところはこれからいろいろ検討させていただきたいと思っているところです。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"そういう代表、誰が選ばれるのかとか、これから当然、一人ひとりなのでしょうけれども、チケットを自治体が購入できるということですよね。いろいろそういった都合もあるので、職員とかで代表選手を応援していくのかという、そのあたりがわかれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これはもちろん区民が主役ですので、区民の方向けということで、職員は自分でチケットを応募してということになります。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろ細かいところは伺っていきたいと思いますが、その際は、区民にとって一番いい形で参加できる機会にしていってほしいと求めました。そういったことも当然、大会後については、品川区全体としてはぜひ大きい方向性として検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/985009?Template=document&Id=6564#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":17755,"voices":59}},{"id":"r01-20191115-10","meetingId":"r01-cm11","date":"2019年11月15日","dateIso":"2019-11-15","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"この後、第１回定例会、令和２年１月１３日に第１回定例会が開かれます。診療報酬がどう改定されるかによって保険料が変わってくるのではないかということの案内までは出ておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"確認というより意見ですけれども、後期高齢者医療の保険料の値上げについては、本会議で反対をしていただきたいと述べておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201447?Template=document&Id=5334#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":7103,"voices":29}},{"id":"r01-20191127-10","meetingId":"r01-cm11","date":"2019年11月27日","dateIso":"2019-11-27","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"全員協議会は事前の説明がありまして、本会議におきましては、一般質問が３人から、その後、副連合長の選任同意、これは全会一致です。これは会計年度任用職員の関係、それから地方公務員法および地方自治法の改正に伴う関係条例の整備ということで、この２件も全会一致で賛成でした。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"前回、後期高齢者医療保険制度の保険料値上げには反対していただきたいと意見を述べさせていただきましたが、一般会計と特別会計についてどのような態度を示したのかということをお聞かせいただきたいのと、保険料値上げにはぜひ反対していただきたいと改めてお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201447?Template=document&Id=5336#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":7562,"voices":29}},{"id":"r01-20191128-9","meetingId":"r01-cm11","date":"2019年11月28日","dateIso":"2019-11-28","committee":"文教委員会","time":"午後 ４時５０分～午後 ５時０８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"最初の確認で、労使の妥結はされたということでいいのかということです。","respondent":"工藤指導課長","answer":"労使の妥結はされたところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"本年４月からの公民較差の相当分に関する調整措置は行わないということで妥結をされたということですが、経緯などがありましたら伺えたらと思います。全体的に見ると、職員の方はプラスになるのか、マイナスになるのか、そこを伺いたいと思います。","respondent":"工藤指導課長","answer":"昨年度も勧告を見送ってありますので、基本の考えの中には２年続けて見送るということについての議論はあったというふうに伺っているところです。そういったところで、期末手当ではなく勤勉手当で調整をするというところを合わせているです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"もう１つ、学校教育職員においては、東京都人事委員会勧告によって公民較差、これは極めて小さかった。この２つ、同じ公民較差と称しているけれども、出てくる数字が違うというところがなぜなのか、というところのご説明だけお願いします。","respondent":"工藤指導課長","answer":"号数であるとか、職層であるとかが完全に一致しているところではございませんので、その辺りについても差が出るというところで把握しています。とり方と、職層も違っている部分が合っていないために、仮に同じ民間事業者等を選んだとしても差が出てくるということになってありま…","id":"exchange-003"},{"speaker":"塚本委員","kind":"意見","question":"言い方を変えてしまうと、すごい数字が動いたりするということで、過去にもそういうことでいろいろと論議があったと思うのですけれども。何かご答弁というか、何かコメントをいただければ、もう１回お願いしたいと思いますとの意見を述べました。","respondent":"工藤指導課長","answer":"公民較差で調べた結果が先ほど申し上げた引き下げの分だということになったと伺っています。そういう意味では、民間事業者をどうとるかというのも引き続き検討しながらというところで意見で伺っているところはあります。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"ここだけパーセンテージの記載になっているのは、どういったことなのでしょうか。同じように合わせるとマイナス２,２３５円という……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"ほかの議員とか区長はマイナスの数字、マイナス５,０００円とか書いてあるのですけれども、ここだけマイナス０.５８％にした理由は何が。パーセンテージにした理由をお伺いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"筒井委員","kind":"意見","question":"消費税が増税されまして、区民生活にも悪影響が及び始めている状況の中で、通常の給与がマイナス２,２３５円。トータルで平均２万２,０００円の増加が行われるということについては、ふさわしくないということで、反対をいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/211588?Template=document&Id=4984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":5218,"voices":40}},{"id":"r01-20191128-5","meetingId":"r01-cm11","date":"2019年11月28日","dateIso":"2019-11-28","committee":"総務委員会","time":"午後 ４時５０分～午後 ５時３８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"時間その他の勤務条件に関する条例の一部を改正する条例、(4)第１０７号議案 品川区監査委員の給与等に関する条例の一部を改正する条例および(5)第１０８号議案…","agenda":"時間その他の勤務条件に関する条例の一部を改正する条例、(4)第１０７号議案 品川区監査委員の給与等に関する条例の一部を改正する条例および(5)第１０８号議案…","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"お伺いしたいのは、１０７号、ベースは下げるものの期末手当の引き上げで年収ベースでは給与の引き上げという中身になると思います。お伺いしたいことは、そうした検討や判断に至らなかった理由は何か、その点だけ伺いたいと思います。","respondent":"立川総務課長","answer":"答申のみならず、当然、社会経済情勢、また他区の状況、国の状況、東京都の状況等を勘案いたしまして決定しているものです。今回の決定につきましては、それらを総合的に判断して決めたものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"改正には総合的な判断ということでありますが、この答申の「おわりに」の中でも、特別職の報酬は区民の理解を得られるものでなければならない。２３区も含めてということが書かれておりますけれども…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"１０８号議案のところでまず１点確認したいのですけれども、来年から始まる会計年度任用職員に、この条例が適用されるのか。適用される場合は、期末手当もこの条例に沿った形となるのか、その部分を確認させてください。","respondent":"黒田人事課長","answer":"今回の条例改正につきまして、会計年度任用職員、来年から始まるところについては影響はございません。期末手当の月数は変わってございませんので、そういった意味でも会計年度任用職員の期末手当の支給月数は特に変更はないところです。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"確認したいのが、会計年度任用職員が連続して働いた場合に、１年間で見直しというか、あるではないですか。会計年度任用職員が連続して働く場合に、１から３月に働いた分が６月の期末手当に反映されるのか、その部分を確認させていただきたいのですけれども。","respondent":"黒田人事課長","answer":"４月、５月の勤務の実績に基づいて６月１日基準で支給されることになりますので、そこのところは算定されない。さらに先の年度になりますと、今度は年度を続いて任用されることであれば勤務が続いておりますので、そこは算定するような制度になってあります。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"確認ですけれども、これは区議会議員の期末手当と連動をするのか確認をさせてください。連動するのであれば、その理由をお知らせください。","respondent":"立川総務課長","answer":"いわゆる条例のつくりとしまして、まず、区長、副区長、教育長を念頭に、期末手当の月数を具体的な数字として定めております。議員の報酬等の条例につきましては、期末手当については、区長等の期末手当の月数に合わせるという、そういった条例のつくりです。","id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"第１０４号議案、品川区議会議員の議員報酬、費用弁償及び期末手当に関する条例の中で、期末手当のことが記されていないです。条例を見たときに、期末手当が上がる仕組みというか、区長および副区長の期末手当と、連動しているのですよねとの意見を述べました。","respondent":"立川総務課長","answer":"品川区長および副区長の給与および旅費条例の第６条で具体的な期末手当の割合が決めてあります。品川区長および副区長の給与および旅費条例第６条第２項に定める支給月数を乗じて得た額で決めるという、こういった条文関係になっているです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"トータルでこうやって上がっていくというのは、ちょっと問題があるのではないかと、我慢してほしいというのが私の気持ちです。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"聞きたかったのは、なぜ期末手当がここに連動してしまうのか、そういうつくりになってしまうのかということを伺いたかったのです。そこをお知らせください。","respondent":"立川総務課長","answer":"２３区、その辺は同一ということでやっているところですので、そういったいろいろな歴史を踏まえているといった現状があるというふうにご理解いただければと思います。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"以前、２０１７年のときにも、生活者ネットワークは歴史の経過の中身を聞きたいということを言っています。歴史的経過が示されないというか、具体的にちゃんとお示しいただきたいと思うのですが、伺います。","respondent":"榎本総務部長","answer":"たしか区長と特別職のところを、期末と勤勉と規定が違いますので、期末手当のほうに一本化するときに全部定めたというような経緯があります。それで、職員の例によるではまずいので、区長の例によるという形での規定を定めたというものです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"今、改めて連動が必要か考えるべきなのではないかということは思うのですが、そのところはいかがでしょうか。きちんと分けていただきたいというか、検討をいただきたいのですけれども、そこについてお答えほしいと求めました。","respondent":"榎本総務部長","answer":"職員の例によるから区長の例によると変えたときも、議会のほうにお諮りした上でそういう形に変えていいかということをお聞きした上でやっていますので、これについてはまた今後、別のしかるべきときに検討していきたいと思います。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"なので、本当は何ですか、何のために今回やるのかというのが、この答申を見ると、そういう疑問があります。だから、どこに根拠を持ってやっているのでしょうかということをお聞きしたいのです。","respondent":"立川総務課長","answer":"報酬等審議会がなぜ開かれるのかということを説明しますと、当然、各自治体においては特別職の報酬等審議会を設置されたいという。ですから、この報酬等審議会の意見を聞くことによって、お墨付きをもらった上で条例を改定するというふうに理解しています。","id":"exchange-011"},{"speaker":"西本委員","kind":"意見","question":"昭和３９年のということでありましたけれども、この後ろのほうに審議会のメンバー表があります。それと、この人事委員会勧告に対しての考え方は、審議会としてどう捉えているのかというかとの意見を述べました。","respondent":"立川総務課長","answer":"それぞれ各方面でご活躍されている区民の代表の方という位置づけでご参加いただいているところです。やはり特別職の給料等を決定するときの指標としては大変に重要なものだというふうに考えているのではないかというふうに推察しています。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"それなりのちゃんとしたベースを、すぐにはできないと思いますが、そういう視点を持って考えていただきたいと考えています。意見で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"反対したいと思います。厳しい社会経済状況を見るならば、年収ベースで給与を引き上げるということは行うべきではないし、区民の理解も得られないと思うからですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"私も同様で、年収ベースで考えると、今回、トータルで上がるというと収入が増えるということなので、区民の生活実態等を考えますと、やっぱり区民の理解が得られないと思いますので、反対しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"西本委員","kind":"意見","question":"先ほども申し上げたとおり、ただ単に金額が上がった下がったという議論にはあまりしたくないのです。なので、今回の改正はいろいろな状況を鑑みて賛成という形にしたいと思いますが、もっと深い意味で議論できたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"反対したいと思います。理由は、同じく厳しい社会状況、経済状況を見るならば、年収ベースで引き上げを行うことはすべきではないし、区民の理解も得られないと思うからですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"私も同様で、今、区内経済状況が悪かったり、それぞれ区民の年収が増えていない中で、年収ベースで引上げを、こういう条例が議案に出たのですが、区民の理解が得られないと思いまして、私も反対しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"第１０４号議案で示されているとおり、区民に身近な考え方と感覚を持つべきである区議会議員の期末手当が連動して上がるのは、反対します。そして、先ほども質問しましたが、連動が必要かどうか改めて検討していただくよう、強く要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そういう視点の評価は必要だと思いますが、見合うということではなくて、それ以上の仕事をしていくという気概をしっかり持っていただきたい。それだけ付言させていただいて、本件については賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"職員の皆さんには、一生懸命職務はやっていただいているのですが、私は我慢をしてほしいというふうに思います。今回、この議案に対しては反対しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993969?Template=document&Id=2150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":13398,"voices":77}},{"id":"r01-20191129-10","meetingId":"r01-cm11","date":"2019年11月29日","dateIso":"2019-11-29","committee":"議会運営委員会","time":"午前 ９時３０分～午前 ９時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201447?Template=document&Id=5338#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":1886,"voices":8}},{"id":"r01-20191202-6","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"区民委員会","time":"午前１０時００分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"令和元年請願第２１号 選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","agenda":"令和元年請願第２１号 選択的夫婦別姓制度の国会審議を求める意見書を国に提出することを要望する請願","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"国会で議論されるべき事柄であるのは明らかですから、どういう立場の方からも賛同できる事柄ではないかなというふうに思います。意見書を提出してくださいという請願ですから、その別氏制を導入するかどうかについて賛成、皆さんいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"くにば委員","kind":"意見","question":"私自身がそれをしたいかどうかと言われれば、ただこれは、国民として選択をする権利というのはあってしかるべきだなとは思います。世界でのスタンダードの考え方ですので、私はそれに沿った形で、こちらの請願に関しては採択をしたいなというふうに考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"藤原委員","kind":"確認","question":"１点だけ確認したいのですが、この請願で下のほうで、東京都内では６区１４市が意見書の採択、ということと、全国自治体レベルでは合計３１件の意見書提出に至っています、という数字的なものは間違いないのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"都内の都議会を含めた１８議会のほうで意見書が可決、または請願が採択されているという記事は載ってございました。全国でも１９議会で意見書を可決したり、請願が採択されたという内容でした。","id":"exchange-003"},{"speaker":"藤原委員","kind":"確認","question":"今、課長の答弁で、都議会と出ましたが、確認だけなのですけれども、東京都議会も採択をしているということで、確認。","respondent":"提坂戸籍住民課長","answer":"委員のご質問のとおりです。","id":"exchange-004"},{"speaker":"こんの副委員長","kind":"意見","question":"我が会派も継続をお願いしたいと思います。もう少しこれをやはり、議会で深めていく時間が必要ではないかと思うところから、継続をお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"藤原委員","kind":"意見","question":"私のところも会派でこれは激論をしたのですけれども、継続でお願いいたします。理由としては、今、こんの副委員長がお話ししていただいたとおり、議論を深めていくという意味において、今回継続でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"先ほどのそのお話を伺うまでは、先ほどの藤原委員からの質問のとおり、継続でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"くにば委員","kind":"提案","question":"店頭表記、その２点に関しては、その翻訳の端末等についてもその端末の導入状況について伺いたいと思います。きちんとどういったところが人気があって、そこに対して今どういうアプローチをしていますというのがありましたら、教えていただきたいとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"キャッシュレス対応で、例えば五反田あたりに集積する得意の企業と結びつけるようなことをもって、その辺もしっかり応援はしてまいります。来ていただいたら入りやすくする店頭の工夫というような、そういう段階的に対応してまいりたいなというふうには考えております。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問・要望","question":"特に地方ではそういうことが強いというふうに伺っているので、やはりその７割ぐらいのところは、腰が重いというふうに伺っていますので。韓国語等でそれぞれどういったＳＮＳであるとか動画配信であるとかといった、こんなところがあるんだよ、加速してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"せっかくこのレコメンドメニューを書いてあるわけですから、すごく安心してそのお店に入れると思うので、それはいかがかというのが１点。商店街の推薦かもしれませんし、どういう形でやったのか、教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"来年の事業の説明会などをしたときに、ちょうど平成２８年度の末に、来年度こんなことをやりますよということをちょっとやりました。７０いただいた中で、最初はつくらせていただいたというものが、今ご覧のものになります。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"ずっと海外の方から来ていただきたいという思いで仕事はしていると思うので、やはり現場の方たちが一番接しているわけですから、１点です。それともう１点は、でも前から商店街に関しては、英語少し通じます商店街みたいなものをやられているではないか尋ねました。","respondent":"山崎商業・ものづくり課長、遠藤協働・国際担当課長","answer":"１点目のほうです。そういう中の一つでいろいろ今後しっかり研究なり検討してまいりたいなというふうに考えてあります。 私のほうから、英語少し通じます商店街のほうについてご説明します。５９店舗が実際やられていますので、その中で、来るところにつきましてはもう一歩どんどん進んでいるというふうに考えてあります。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"ずっと続けていっていただきたいという思いで質問させていただいたので、というような意見をちょっといただければ幸いなのですけれども、誰か答えていただけますか。","respondent":"古巻文化観光課長","answer":"来年やはり、例えば商店街支援であったり、そもそも外国人の旅行者に向けた情報発信だったりといったところは継続してやっていきたいと思います。品川区の魅力を国内、区民だけではなくて、外国の方にもたくさん知っていただきたい…","id":"exchange-012"},{"speaker":"おくの委員","kind":"意見","question":"これ、あるいはそういうことをこれからやっていきたいと、その商店街の方自身がそもそもどれほど思っていらっしゃるのか。こういう働きかけを区のほうからやっていらして、そこら辺のことを大ざっぱなご感想でもいいのですけれども、ちょっとお教えほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"外国の方というのはなかなか対応したこともないし、できるのであればそうしたことができるほうがいいよね、というような順番なのです。現実的になると、先ほどのいろいろな事例の取り組みでは今のところ４０の商店街のような状況にはあるというようなことです。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"増えてきている感じなのでしょうか。やるべきだと思うのですけれども、それからこれを３年間やられて、それほどでもなかったのかというところもちょっとお伺いしたいのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"ここのお店については外国人の方が来られたときにいろいろ多言語の対応もされているし、という、要は売りにしていくというのですか。ほぼそういう、事業の意図などという部分は、品川区の商店街の方々には理解をしていただいているというふうには受けとめているところです。","id":"exchange-014"},{"speaker":"湯澤委員","kind":"質問","question":"このおもてなしガイド、本当にすばらしいものだと思います。これはもう既に配られているものか尋ねました。","respondent":"古巻文化観光課長","answer":"こちらのおもてなしガイドにつきましては、既に各商店街に商連を通じて配っておりますので、なのでちょっと在庫がなくて、こういう資料の形になっております。","id":"exchange-015"},{"speaker":"湯澤委員","kind":"意見","question":"どういった意見があって、また改訂版などもつくるのかどうかも踏まえまして、当委員会でまたお知らせいただければなというふうに思っているのが１点。何か、それについて意見があればとの意見を述べました。","respondent":"古巻文化観光課長","answer":"こういったような形のもの、またいろいろ工夫をして出していきたいなというふうには考えておりますので、進めていきたいというふうに思います。今年３回目ということで、商店街の方にメリットのある形をとっていきたいというふうには思いますので、ご意見ありがとうございました。","id":"exchange-016"},{"speaker":"湯澤委員","kind":"質問・要望","question":"もうおっしゃるとおりで、商店街の方々の意見でやっていることはもう重々承知なのですけれども、やはりそういった一部の方の意見もあるということは確認してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"１人でも多くの海外の方々に、品川区ではこういう商品がありますよ、ということを発信していかなければいけないのではないかなと考えています。そういう考えというものはないかな、あるのかどうかということをお聞かせいただきたい。","respondent":"古巻文化観光課長","answer":"３０万部ほど発行部数があるということで、かなり影響力というのですか、特に飛行機の中で見るものなので目にされる方が多いと思います。そういった形の、そういった紙媒体での発信もどんどんやっていきたいなというふうに考えております。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"にもぜひ、本当に一番身近にある韓国や中国、そういうところとの絆をもっともっと今以上にしっかりと結ぶべきではないかなと思っています。そういう何か、韓国、中国に対しての品川区からの狙いというかＰＲの仕方、何かあれば教えていただきたいなと思います。","respondent":"古巻文化観光課長","answer":"アジア圏を中心により積極的にやっていきたいなと、情報発信はしていきたいなと思っています。例えば観光案内所、品川区をより知っていただくといった試みといいましょうか、取り組みは常にやっていきたいというふうに考えております。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"指さしで示せるフレーズや、英語がしゃべれない日本の方でもいろいろなそういう準備をされていて、すごくすばらしい取り組みだと考えています。ちょっとお聞きしたいのが、この謎解きウォークやえばら観光フェア、こういうものというのは、実際はどなたが中心でやられているのか尋ねました。","respondent":"古巻文化観光課長","answer":"謎解きウォークにつきましては、しながわ観光協会のほうにお願いをしていてやっていただいている事業になります。これは品川区の主催ですので品川区としながわ観光協会、そちらがメーンになって、今のところ組み立てをしているというようなところになります。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"確かに大きく集客はあるのですけれども、個店の方々がなかなか前に出られないというのがあったりするのをよくお聞きするのです。先ほどありました１０４の商店街のうち、品川区としてはではどういうふうにやっていくのかという施策みたいなのというのは考えているのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そこは現在も、文化観光課と私ども商業のほうと密接な連携をしながらという、基本的にはそういうふうに考えています。いろいろ有機的な連携ができるような形でやらせていただいているつもりですので、そんな方向には努めてまいりたいなとは思っているところです。","id":"exchange-021"},{"speaker":"こんの副委員長","kind":"質問","question":"参考までにお聞きしたいと思うのですけれども、外国人の方からの、その気づきの声というのはどんなお声があるのでしょうか。参考までにちょっとお聞きしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"最初のそういった話し合いでヒアリングのときにはそこが１つと、やはりお店に入られると、双方いただきました。何か、そこの動線をどうにかしたいなというふうには、そのときからそういうことを思った次第です。","id":"exchange-022"},{"speaker":"こんの副委員長","kind":"意見","question":"その課題をどうするかという話と、外国人の方が喜ばれて、行ってみたいなと思われるのか。その辺の声は何かありますかとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"いろいろ商連などと本件のようなことを検討するときに、そのときに使える、そういうものが欲しいというようなご意見をいただくことがすごく多いです。よくよく考えてみると、そこの構築、それがすごく大事だなというふうには思ったところです。","id":"exchange-023"},{"speaker":"こんの副委員長","kind":"質問","question":"こういうのはどうなのですかというお話を次にしたいのですけれども、打っていく、一つの呼び込む手法ではないかなというふうに考えているのです。ないのであれば、こんな考え方、今言ったようなものはどうですかというところなのですけれど、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長、古巻文化観光課長","answer":"確かに、日本にいますと当たり前のように四季がありまして、年度がかわって春から夏にかけては、商店街のイベントはどうしても夏から秋です。すが… 特に歳時期にこだわらずというところもあるのですけれども、一つのそのツアー、まち歩きの中のプランとして取り組んでいたりということはあります。今だと…","id":"exchange-024"},{"speaker":"こんの副委員長","kind":"質問","question":"どういったものをというところで今、どう動線をつなげるか、幾らイベントをたくさん打ってもなかなかそれは難しいというのは確かなのです。連携というのでしょうか、そうしたところは今現状、どうなっていますか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"連携の大きさはさまざまでありまして、例えばエリアに属する企業が商店街のイベントに協賛をするというようなところというのは結構あります。商店街のイベントだけではありませんが、商店街と組まれて、というような事例は幾つかあります。","id":"exchange-025"},{"speaker":"こんの副委員長","kind":"質問","question":"どうですか、やりたい人」みたいなお声がけというのもあってもいいのかなと思うのですけれど、その点はいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そういうふうに考えてまいりたいなということがありまして、そのエリアの一企業というよりも、そこはやっていきたいなということ。アイデアとしてはいろいろ幾つか出ておりまして、何か形にできればいいかなというふうには今思っているところで、検討しています。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問","question":"なぜなら、何というのですか、そういう発信もありかなと思っています。","respondent":"古巻文化観光課長","answer":"タクシー会社との連携は、というようなご提案だったと思いますが、直接今、すぐに何かやっているわけではありませんけれども、貴重なご意見ということで参考にします。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/776686?Template=document&Id=2852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":35420,"voices":83}},{"id":"r01-20191202-7","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"厚生委員会","time":"午前１０時００分～午後 ０時３９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"令和元年陳情第５０号 卒後の壁～障害者のいる家族が働き続けることができるよう支援を求める陳情","agenda":"令和元年陳情第５０号 卒後の壁～障害者のいる家族が働き続けることができるよう支援を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９月の陳情でも、日中一時支援を障害者まで拡大してほしいという要望が出されていました。そういう考えでサービスを拡充することが必要だというところで考えられているのかということについて、まず伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"当然ながら、ご本人やご家族を支えていくというのは、区として必要なことだと認識しております。ご家族の方の就労に対する実態があるのかということにつきましては、今後、基礎調査の中でつかんでいく必要があると考えております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほども課長から言われましたように、指定特定相談支援事業所のほうで、一人ひとりに対して計画を立てているわけですよね。実態がどうなっているかというのは、また、品川区の課題についてどう考えられているかについてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"先ほど陳情の説明でも申しましたように、指定特定相談支援事業所の相談員が、ご本人とご家族から事情は十分にお伺いしております。したがいまして、ご家族のご希望を全てかなえられるかということは、今の段階ではできておりません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで拡大の方針を求めるべきではないかと思うのですけれども、その点についてもお聞かせほしいと求めました。障害者福祉課の職員に確認したところ、ここに書かれているとおりないのかどうなのか、その確認をさせてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"西大井福祉園ですけれども、やはり午後７時まで実施しているというところですが、今現時点での実施状況ということになります。こちらのほうのお答えが、こちらのほうの明確なご説明ができなかった点は申しわけないのですけれども、申し上げておきます。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"報酬の面でも保障されるということであれば、ぜひそういうことで拡大をしていただきたいと思うのですけれども、その点についても伺いたいと思います。そこら辺のところは、そういうところも含めてしていくことが必要ではないかと思うのですけれども、そういうところではいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"女性の支援員を常に用意しなければならないということ、重度の方と高度障害の方ということで、非常に大きな人的な課題があるのだろうと考えています。就労継続支援Ｂ型におきましては、就労継続ということは、働くということではないというふうにもなりますので。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、年代によって随分変わってきているということに対しての対応というのがすごく求められるのではないかと思うのですけれども、就労というのは。それなのにもかかわらず、希望しているドア・トゥー・ドアの送迎をすべきではないかと思うのですが、その点についても説明を求めました。","respondent":"松山障害者福祉課長","answer":"道路状況に配慮して、各ご家庭と施設側が調整し、行っているです。そのため、本当に個別に対応が異なるものです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"道路事情ということがありながらも、家まで迎えに来てほしいという希望をすれば、ドア・トゥー・ドアはできるという仕組みになっているのか。私は、その点は、仕組みとしてどうなっているのかについても説明を求めました。","respondent":"松山障害者福祉課長","answer":"どうしても重度の方ですと、リクライニング等の車椅子で大きいタイプのものもありますので、車自体も大きい車両というのがあります。合わせたドライバーを複数用意しないと、なかなか難しい仕組みになるのではないかと、現実問題としてあります。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"介助者が１人つけば、できる限りドア・トゥー・ドアの希望のところで、そういう形での取り組みもお願いしておきたいと思います。その仕組みと、それから、通年かつ長期にわたる外出については対象にしないのかというところの理由についても説明を求めました。","respondent":"松山障害者福祉課長","answer":"例えば、就労継続支援Ｂ型等につきましては、３カ月から６カ月は移動支援というのを支給しているという事実はあります。やはりどうしても利用者の状態にもよりますので、個別に柔軟に対応していきたいと考えています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際に慣れるまで３カ月から６カ月可能ということで、実際に使われている方というのは結構いらっしゃるのでしょうか。それから、時間も……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"長くなってしまったので、まとめたいと思うのですけれども、この陳情には、卒業と同時に区外に引っ越さざるを得ませんと書かれているのです。地域生活支援事業で就労保障として移動支援を行っている区というのはあるのか、その点についてもお聞かせいただけたらと思いますとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"先ほどの就労継続支援Ｂ型で、慣れるまでの間の訓練として利用されている方というのは、多くはないと考えています。大人バージョンの日中一時支援をつくり始めた区、生活介護の延長で対応している区等々ありますけれども、情報交換した中では。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"何点か伺いたいと思いますが、そのことも、この陳情が出てくる背景にあるのかと思います。パンフレットなのか、わかる形にまずはしていくべきだと思うのですが、そのことについていかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"それぞれの延長対応につきましては、非常に個別性が高いという認識をしております。決して就労だけのために延長対応をしているというものではございませんので、やむを得ない理由によって延長対応しているというのが実情です。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういった意味では、やはり一定のことはしているということは、何らかの形で工夫して発信してほしいと求めました。その点はいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"おそらく指定特定相談支援事業所の相談員のほうが状況を把握して、相談の中で丁寧に説明するというのがよろしいかとは思っております。今後、障害者のいる家族が働き続けるためにも、重要なことだと考えております。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"こうした希望が現場の段階で潜ってしまわないように、課としてはもう一度ここはきちんと要望を把握しようということの働きかけをしてほしいのです。それについて、ご答弁をお願いします。","respondent":"松山障害者福祉課長","answer":"確かに委員ご指摘のとおり、最初から何もなければ、就労を諦めてしまうような方もいらっしゃるのではないかと推測されますので、再度、相談支援員の連絡会等を通じまして、周知徹底を図っていきたいと考えています。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"受給者の数というのは、あるいはご家庭の数というのは、ある程度わかるわけですよね。一定の就労の要望というのは、潜在的なニーズだと思いますので、それをいかに掘り起こすかということをぜひやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"預かれるのは毎日ということではないということをおっしゃっているのですけれども、平均で大体何日ぐらい預かれるということなのでしょうか。今のやりとりを聞いていて思ったのですが、毎日ではないというところがひっかかりまして、実態を教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"定員が４名ですと、毎日常に同じ方がというわけにはなかなかいきませんので、ほかの方のニーズも加えながらということになっております。さきに説明をいたしました生活介護の延長サービスや訪問系サービス等を組み合わせて、できる限り支援をしているというのが実態です。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結局、働き続けることが保障される受け皿というのが、本当に困難な状況というのが実態だと思うのです。親も働くことが、就労が権利として保障されるというところまで、ぜひサービスを拡大していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"若林委員","kind":"確認","question":"障害者福祉課の職員に確認したところという、障害者福祉課はたしか基幹相談事業所でしたか、まさに基幹としてという一つの大きな役割を。そこら辺のご相談があったときには、窓口としてはどのような返答、相談に乗るという形なのか尋ねました。","respondent":"松山障害者福祉課長","answer":"基幹相談支援センターという位置づけですけれども、まず、地域の拠点相談支援センターでもご相談はお受けしております。支えられるかということで、サービスの提案をし、ご家族と調整しながら在宅生活を支えていくという姿勢です。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"ですから、できる範囲の中でしっかり、障害を持っているか持っていないかだけではないではないですか。ですから、どういうサービスがあるのかというのは、しっかりやっていただかなければならないのだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ただいまのやりとりからも確認できたのですが、家族が働き続けることができるよう支援を求めるということで、先ほどもご説明がありました。ただ、障害者サービス全般の中で、拡充という大きな流れは意識しなければならないと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"その中で、９月と同様、ニーズの把握に努めて、第６期の計画が今進められていると。ぜひいい障害福祉計画、また、障害児福祉計画を策定して、ニーズに寄り添って応えていただきたいという思いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜ子どもに障害があるというだけで、母親は自分の人生を生きることを許されないのだろうと、やり切れなさを抱えてきた」という文章でした。私は、改めて親の就労を保障するためのサービスの拡充を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"冒頭のほうで書いてある小１の壁なども、前から小１の壁問題というのは存在していたわけですし、残念に思っています。不採択としますが、ここで陳情者の方がおっしゃっていることは区も十分把握されていると思うので、ぜひ実現に向けて頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]},{"id":"topic-02","title":"令和元年陳情第５１号 移動支援サービス事業者を増やす研修の実施を求める陳情","agenda":"令和元年陳情第５１号 移動支援サービス事業者を増やす研修の実施を求める陳情","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"２つだけありますけれども、１つは、特段何か問題があるわけではないですよねという確認が１点。要は、従事者を増やすことができる研修の実施ということが求められているのだけれども、問題はそこではないような気がするのです。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの、区との契約については、問題はございませんということです。２点目の研修の実施、研修の中身や研修の仕組みというよりは、全体的にヘルパーの確保というのが区としては非常に課題として認識しております。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"仕組みのことで伺いたいのですが、ヘルパー２級、そのうち移動支援は１８カ所しかないのですよね。ヘルパー２級があれば、その２点、まず説明を求めました。","respondent":"松山障害者福祉課長","answer":"確かに事業所につきましては、今後、民間の誘致といった方法も考えなければならないと感じております。ヘルパー２級の方でもガイドヘルパーになれるのかですけれども、やはりこちらのほうの知的障害者の方への支援ですので、必須の要件ではございません。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点では、研修の内容なのですが、講義と実習ということになっているのでしょうか。その中で１８カ所しか移動支援に手を挙げられているところがないので、そこのところの課題が何なのかということもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"あるいは歩く速度ですとか、事業者から聞いているのは、マッチングに苦労するということは非常に大きな課題として認識しております。ですから、やはり人の課題というのが一番多いと認識しています。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"報酬というのは、国で決められている報酬というのがあると思うのですが、それにのっとってやるということになるのでしょうか。もう一つ、この陳情に書かれているのが、区内で東京都の指定を受けた事業者というのはあるのかどうかについてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"したがいまして、移動支援のほかに給付がとれる事業所を併設して経営しているというところはあります。２つ目なのですけれども、区内においては、東京都の指定を受けた移動支援従事者の研修ができる事業者というのは、指定を受けたところはございません。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３０人なので、５,０００円だったとしても、１５万円という程度ですよね。無料またはもっと低額で受けられるようにしてもいいのかと思うのですけれども、その点についてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"受講料が高いという声を受講生からはいただいたことはないと事業者から聞いております。受講者を増やすというよりは、本当に移動支援サービスの事業者を増やすためにどうしたらいいかという方法については、模索はしていくです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際にほかの区がほとんど無料でしているということですから、無料にということで、品川区としてできない支援ではないと思うのです。どのように改善が必要だと、取り組みの具体的なところがありましたら、その点についてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"今後の具体的な取り組みですけれども、実際に移動支援をやっていらっしゃる事業者、具体的に情報を集めている段階です。情報が集まりましたら、精査をしまして、一旦どのようなものが有効な方法なのかを探っていきたいと考えています。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どう改善させていくかという取り組みがいろいろな分野にわたって、これはずっと言われ続けてきているところなので、ぜひ具体的なところで対応していただきたいということでお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"品川区もそうした積極的な手法もとってはいいのではないかと思いますが、いかがでしょうかというのが２つ目の質問です。受講のご案内が出ていないように見えるのですが、ここはぜひ改善すべきではないかと思いますが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"みらいの実施計画の中で、ほかのＮＰＯ法人と協力してこの事業を実施していくという旨の報告は区のほうにいただいています。あるいは軽いのか、私としても明確なお答えを持ち合わせておりませんので、情報収集しながら精査をしていきたいと考えています。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"今年や去年の話ではないですから、それはしっかり監督と言ったらいいのでしょうか、委託をしている者の責任としてやってほしいと求めました。こうした指定を受ける力があるはずの伝統ある法人は区内には幾つもあるわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ヘルパーの２級とか１級とかの養成というのは、昔、介護福祉専門学校でやっていたような気がするのですけれども、そういう点では、介護福祉専門学校でガイドヘルパーの養成をするというのはできないものなのかと思ったのですが、その点はいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"学校側としても、人材育成全体を考慮した上で何を重点的にやっていくのかというところもあると思いますので、学校側と話し合いはしていきたいと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"養成しなければならないということですので、やはり区が主導でやって、介護福祉専門学校もぜひ活かしてやっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、お話等々伺っている中で、そうすると、区内でこの研修をできるのはみらいしかないということですよね。ずっとできていないのか、できていたものが今回は、どんな理由があってなのか、できていない理由なども伺えたらと思うのですけれども、お願いします。","respondent":"松山障害者福祉課長","answer":"平成２８年ぐらいから平成３０年度まで、３年間に春と秋ということで、年に２回継続して実施してきております。そもそも受講生がやはり少ないというのは、区としても課題と思っておりましたので、この間、事業者と話し合いをしてきているです。","id":"exchange-033"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"以前に世田谷区に話を伺いに行ったときには、今後区がやることは、やはり人材育成をやっていくということだと伺いました。情報収集等もされているということですけれども、今に始まった話ではないので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"渡部委員","kind":"確認","question":"先ほど質問で確認することは確認させていただきました。これはどういう形かで、そういう方が増えるようになっていけばいいと思いますので、それについては進めてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"西村委員","kind":"質問・要望","question":"結論を出すということで、不採択でお願いいたします。引き続き創意工夫をしていただきたいと思うのですけれども、事実と異なる点もありますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"区の次に向かっての姿勢は、質疑の中で確認をさせていただきました。課長のお考えの中にもあったと思うのですけれども、そこはしっかり進めていただきたいということで、不採択で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域生活支援事業だけに、自治体で大きく差が生じるところです。区として当事者の声に応えて対策をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"本日結論を出すということで、採択でお願いします。先ほどからもいろいろ質問もさせていただきましたけれども、それをどう増やしていくかというところでは、これは採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"}]},{"id":"topic-03","title":"令和元年陳情第５７号 品川区旅館業施行条例を、常駐者を義務付けた内容に改正することを求める陳情","agenda":"令和元年陳情第５７号 品川区旅館業施行条例を、常駐者を義務付けた内容に改正することを求める陳情","exchanges":[{"speaker":"西村委員","kind":"質問","question":"先ほど課長がおっしゃられました、東京都内では多くの区が常駐者を置くことを義務づけた条例になっていると書かれているところで、不正確な情報だとありましたが、いま一度この点、ご説明をお願いできますか尋ねました。","respondent":"鈴木生活衛生課長","answer":"そのうち完全に条件なく、要望にあるような２４時間の常駐を義務づけているのは、中央区１区のみとなります。ほかの５区につきましては、無人でもオーケーという限定的、部分的な規制となっているのが現状です。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは９月の陳情審査のときに、改めて何件新たにできたのか、地域別に件数をお知らせほしいと求めました。","respondent":"鈴木生活衛生課長","answer":"荏原地区の５件のうち１件は、簡易宿所になります。八潮地区にはゼロ件となっているのが現状です。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それぞれの警察に確認して、品川区としても把握をすべきだと思うのですが、確認はされているのでしょうか。確認をしているのでしたら、どんな苦情が何件ぐらい警察には寄せられているのかということについても、お聞かせほしいと求めました。","respondent":"鈴木生活衛生課長","answer":"直接警察や消防に苦情などが行って対応したという報告は、連携するときはほぼ区からの要請、今年度は６件です。それから、ごみの出し方については、清掃事務所に連絡をして、指導していただくということで対応しています。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すごくうるさいので何とかしてくれみたいな、警察に直接住民の方から苦情が行ったという件数もこの中に入っているということなのでしょうか。直接警察に行っているというのもあるのではないかと思うのですけれども、その点についてどうか尋ねました。","respondent":"鈴木生活衛生課長","answer":"今後もし何かあったときに、夜中とかであれば、直接警察に連絡をしていただいて結構ですというのは言っていただいております。今のところ区のほうに何件とかという報告をいただくようになっていないので、それについては、今後また情報共有の意味で警察と協議したいと思います。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのように夜中とか、そういう点では、ぜひとも警察にどれくらいどんな苦情が来ているのかということは把握してほしいと求めました。先日の石田ちひろ議員の一般質問で、近隣への配慮の具体的な中身は、どのような中身で指導されたのかについても説明を求めました。","respondent":"鈴木生活衛生課長","answer":"指導としては、しっかりと説明をするということ、そこについて何か対応する方法がないかということも検討してもらうように依頼をしたところです。これについては、説明会の後、事業者のほうから報告を受けたところです。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう地域の方の要望ですので、その要望を受けて、その点が１つです。昼間のところではなくて夜の、そこのところをしっかりと対応してほしいということでのご要望なので、その点についてもいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そこのところの不安や疑問に対してどう応えていくかというところなので、この陳情の中身に沿わない質問をしているということではないと思います。それから、前のところで、既に建築確認はおりて、建築が始まろうとしているわけですよね。","respondent":"鈴木生活衛生課長","answer":"手続きについてのスケジュールですが、既に住民説明会の後、申請の手続きにはいらっしゃいまして、受理をしております。一応、事業者の話では、３月下旬ぐらいには建設工事を完了させて、許可の最終の手続きをしたいと考えていると聞いております。","id":"exchange-046"},{"speaker":"あべ委員","kind":"意見","question":"条例の比較だけではない、やはり地域環境の守り方というのはあると思うのです。あるいは実際に苦情なども起きているところですし、そうした姿勢は持てないものかと思うのですが、区のお考えを説明を求めました。","respondent":"鈴木生活衛生課長","answer":"先ほどご説明したように、区としての独自の状況に合わせた規制の仕方、もしくは対応の仕方というのはあると考えています。やはり条例での規制が認められるほどの現状がないということで、今は指導でその不足部分を補うというのが、区の考え方です。","id":"exchange-047"},{"speaker":"あべ委員","kind":"意見","question":"そうした意味では、品川区というのは、地域特性からいえば、こうした無人ホテルが乱立する可能性が高いところであると私は理解しております。ですので、他区の一般に比べても強いのではないかと理解しておりますが、区の考え方は違いますかとの意見を述べました。","respondent":"鈴木生活衛生課長","answer":"それ用の施設ということで、一定程度、やはり外への騒音など影響の出方が違うところがあってというのが一つにはあるかと考えております。区の現状で見ると、実際に起こるであろうと予見される確実性というのは…","id":"exchange-048"},{"speaker":"あべ委員","kind":"意見","question":"ただ条例で認めてしまうと、そこのコントロールも今後さらにつきにくくなるのではないかということも、あわせて懸念をしております。こうしたことを条例で認めているから、何でもこうスルーというのではなくて、一件一件、その事業を審査するという姿勢は今もありますかとの意見を述べました。","respondent":"鈴木生活衛生課長","answer":"ご質問の一件一件の審査ですが、区の保健所は、法令と条例の規定に基づいて審査をしっかりと行っております。それから困ったというような声に対応するために、指導の形で今まで対応してきておりまして、一定程度の対応をしていただいて。","id":"exchange-049"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"このホテル建設に疑問を持ち、不安を持っている皆さん、３０名以上がこの住民の会に入られた。そこを確認させてください。","respondent":"鈴木生活衛生課長","answer":"先ほど申し上げた３つの要件を満たすことが、品川区内の現状の懸念される影響等に着目して判断すると、条例による規制は難しいというのが区の判断です。","id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そこの不安があったのだと。宿泊者がどうしていいのかわからないということと、それを押せなかったときどうなのかとか、いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"それから近隣の善良な風俗の維持というのが目的になっていますので、それに沿ったものということは言えますので、区も同じ考え方です。ただし、実際には、やはり規定に沿ってやる中で、一定程度、できること、できないことの境ができてしまうというのは事実だと考えております。","id":"exchange-051"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ですので、こうした無人で、しかも駆けつけてくるのは運営者ではなくてロードサービスというやり方に、区はオーケーを出すのでしょうか。このホテル建設計画によって生まれてきてしまっているのですが、そうした適正な管理によって不安を取り除けるというお考えはお持ちか尋ねました。","respondent":"鈴木生活衛生課長","answer":"それから区の条例に基づいた基準に適合するかどうかを判断する権限しかありませんので、住民の方が不安を持つのであれば、指導という形で対応をお願いするというのが区のやり方です。","id":"exchange-052"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"お聞きしたのは、不安ではなく、歓迎という思いで迎え入れることができるという考えは区にもありますかということです。管理がしっかりしていればということです。","respondent":"鈴木生活衛生課長","answer":"区としては、もちろんしっかりとした管理が事業者にできるかどうかという審査をした上で、不足な部分は指導していますので、当然、しっかりとした管理は重要だと考えております。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ニーズを伺って、それから商店街での買い物とかの要望があれば、そこの民泊のところに事業者が伺って。誰がどう泊まっているかというのが、誰も責任もとらないという点では、その点はいかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"採算性の話とかもありますので、区として強制できるものではありません。そういう意味でも、やはり条例での規制は難しいと考えております。","id":"exchange-054"},{"speaker":"渡部委員","kind":"質問","question":"本日結論を出して、この陳情については、不採択でお願いいたします。それができなければ法令違反にそこはなるわけですから、その中でしっかり運営をしていくわけですから、この件に関しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"西村委員","kind":"質問・要望","question":"質問をさせていただきまして、課長のご説明にもありましたように、法と条例の関係につきましても一定の理解をいたしました。引き続き区のほうには丁寧にやりとりをしていただきたいとお願いをいたしたいと思いますので、本件に関しましては、不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結論を出すということで、採択でお願いしたいと思います。そういう不安、やはり他区で義務づけているような、条例でしっかりと常駐者を義務づけるという条例の改正が必要だと強く主張したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"一定の問題に責任を持って当たれる人物と言ったらいいのでしょうか、規模によっても、これは考えていく必要があろうかと思います。あるいは求める基準というのは変わってくると思いますので、地域に負担がないように、今後も指導をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"}]},{"id":"topic-04","title":"令和元年陳情第５９号 「品川区障害福祉計画・障害児福祉計画策定のための基礎調査」の選択肢の偏りに関する陳情","agenda":"令和元年陳情第５９号 「品川区障害福祉計画・障害児福祉計画策定のための基礎調査」の選択肢の偏りに関する陳情","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"それは普通にそういうものですから、それがまず１点。議会に陳情まであげてくる内容ではないと思うのだけれども、担当課がきちんとした答えをしないからこういう陳情が来たのか、教えてほしい。","respondent":"築山障害者施策推進担当課長","answer":"本件に関するご質問は、直接障害者福祉課にはございませんでした。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２９年度も同じ設問にしているので、そういうところで、毎回こういう形で聞くことになっていくのかということをお聞かせほしいと求めました。〔「そんなことはない」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"対する設問ですから、そういうことでいうと、これからもずっとこういう形で聞いていくということになるのか。私はどこかで改めることが必要なのではないかと思うのですけれども、いかがでしょうかということです。","respondent":"築山障害者施策推進担当課長","answer":"次回、この調査を行う際は、次回は９カ年の障害者計画の策定に当たっての基礎調査も兼ねることとなります。障害者計画および障害福祉計画という計画策定に向けたアンケート調査となりますので、改めて設問等については検討したいと思っているところです。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうことで、設問を検討するということであるとしたならば、今回のような形で、「とても」ということを片方につけるとかということでなく、これからは対する設問のあり方ということで、改善していただくということでよろしいか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"現在、まだアンケートの結果のほうも集計中です。いろいろな意見があるかと思いますので、次回、基礎調査の設問等を考える際には、また改めて検討したいと考えています。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひやはり恣意的にこちらにつけるということではなく、バランスを考えた形での設問の仕方ということで検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"２時間以上かかりまして、２人でヒーヒー言いながらやったのですけれども、やはりいろいろ改善の余地のある調査だと感じておりました。今回の基礎調査の内容と表記の仕方、あるいはその伝え方について、区として考えていることがあれば教えて下さい。","respondent":"築山障害者施策推進担当課長","answer":"ただ、その反面、項目が多くなることによって、回答するのが大変だということで、回答率の低下につながるという課題もあります。ですので、そのあたりのバランスをとりながら、次回考える際は、また新たに検討したいと考えています。","id":"exchange-064"},{"speaker":"あべ委員","kind":"提案","question":"この調査の内容が、一度、厚生委員会で示していただいたときに、でき上がった時点で当事者の方々に目を通してもらったらどうでしょうというようなことを提案したのですけれども、それはやっていただけたのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"設問については区が決定するということで、ご意見をいただきながら、こちらのほうは決めたものになります。自立支援協議会等でも諮って、ご意見を踏まえて総合的に決定をしたという流れをとらせていただきました。","id":"exchange-065"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません、前回要望した意図がやはり伝わっていなかったのかと思います。本当に必要なことだと思うので、ぜひ次回はやってほしいと求めましたが、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"今回、基礎調査を実施しまして、いろいろなご意見もいただいておりますし、また、これからも出てくるかと思いますので、そういう区民の方々、当事者の方々の意見を踏まえながら、また次回の検討に活かしていきたいと考えています。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ当事者の方々のご意見も改めて伺っていただいて、当事者の実態を把握するためのアンケートですから、ぜひしてほしいと求めました。改めて伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"当事者のほうから出てくる意見等を踏まえまして、また次回の設問設定、アンケート調査項目の検討の際に活かしていきたいと考えています。","id":"exchange-067"},{"speaker":"渡部委員","kind":"意見","question":"ただ、それが必要かどうかというのは、私はわからない。それはしっかり行政で考えてやっていただければいいと、不採択なのでもういいですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりバランスということからしても、そういう方向でぜひ今度の、これから来るアンケートには活かしてほしいと求めました。そして、また改めて当事者から聞き取りを行って、当事者の意見を反映したアンケートにしていただくよう、求めておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"あべ委員","kind":"意見","question":"ただ、その背景にあるこの基礎調査のわかりにくさ、受けた方の納得のしづらさというのはあったと思います。どの分野にもあると思いますので、そこを何とか埋めていくような手順というのをぜひ今後前向きに検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312511?Template=document&Id=3550#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":45382,"voices":173}},{"id":"r01-20191202-8","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"建設委員会","time":"午前１０時００分～午後 １時５７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件整理しています。","topics":[{"id":"topic-01","title":"第９０号議案、品川区災害弔慰金の支給等に関する条例の一部を改正する条例","agenda":"第９０号議案、品川区災害弔慰金の支給等に関する条例の一部を改正する条例","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"要望として、今１.５％や１.０％などの例示、なるべく低金利でお願いしたいなと。それから、これまでこういった制度を使われた方がいらっしゃるのかどうかということと、どのように周知をされているのかということを説明を求めました。","respondent":"中島防災課長","answer":"東日本大震災と平成２５年台風第２６号で大島町のほうに適用があったですけれども、この制度に基づく支給および貸し付けの実績はございませんでした。そのような対象の方にお伝えしていく…","id":"exchange-001"},{"speaker":"たけうち委員","kind":"確認","question":"第１９号は、それから品川区の「しながわガイド」というんですか、問い合わせ先が社会福祉協議会になっているのです。その辺のことでいいのかという確認と、第１９号で、この条件に合えばこれが使えるのかということを説明を求めました。","respondent":"中島防災課長","answer":"それが利用できない方が、この都の社会福祉協議会の貸し付けの対象というか、制度が利用できるというようになっております。今回の台風に関しましても、そのような対象の方については申し込みができると考えているところです。","id":"exchange-002"},{"speaker":"たけうち委員","kind":"意見","question":"今回の台風第１５号、第１９号は、対象になるのかどうかとの意見を述べました。","respondent":"中島防災課長","answer":"台風第１５号、第１９号に関しましても、対象になります。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"確認","question":"罹災証明ですか、そこが大事だから確認したので、自信を持って答えてもらいたいのです。特に国に、そのような声を上げてもらいたいと思うのですけれども、いかがか尋ねました。","respondent":"中島防災課長","answer":"ご指摘のとおり、今回この災害援護資金の対象は、家財の３分の１以上の損害や、住宅の半壊・全壊というものになっております。一部損壊を対象とするということは、法律のところのものですので、そのようなことは念頭に入れておきたいと思います。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問・要望","question":"このようなものがありますよという情報が届くように、周知啓発をしっかり行ってほしいと求めました。これは要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"提案","question":"利率のところは３％以内でということなので、条例審査までに利率も含めた提案というものをぜひお願いしたいと、これは要望です。確認なのですけれども、第１９号で、区内でそのような被害が認定されたような事例というのはあったのかないのかとの意見を述べました。","respondent":"中島防災課長","answer":"いずれも基本的には台風第１５号によるものということで聞いているところです。一部、台風第１９号の影響もあった、重なってあったということでもありますが、そのようなことを聞いているところです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"実際に半壊が３件あったということですので、ぜひこのような制度改正が行われたということですから、当然行うと思うのですけれども、漏れなく制度のご案内するようにお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"この貸付原資の負担は国が３分の２で、政令指定都市が３分の１だったかと思うのですが、そのあたりはどうなのか尋ねました。","respondent":"中島防災課長","answer":"今回の法改正の中では、自治体のほうが利率を決められるというところです。目安がないとということで、国のほうから、あとはそれを参考に自治体のほうで決めるというような形かと考えています。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"例えば２人世帯だと４３０万円、そのあたりの所得制限というものは、今回改正するに当たって何か検討などということはあったのか尋ねました。","respondent":"中島防災課長","answer":"基本的には今回自治体のほうで改正できるところは、法律の改正に基づきまして行っているところでございまして、所得制限の改正について検討ということは特に考えてございません。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりこの貸付利率なのですが、定められる前に、例えば議会の委員会の中で報告されるなどという機会はあるのでしょうか。ぜひ定められる前に報告していただきたいなと思うのですが、その辺いかがか尋ねました。","respondent":"中島防災課長","answer":"貸付利率につきましては委員会等の場でご説明をできるような機会が、時間的にも難しいのかなと思っているところです。何らか、別の形でお伝えできるように考えてまいりたいと思っています。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはできるだけお知らせいただきたいということと、他区が参考になるのかなと思うのですけれども、その辺は既に調べていらっしゃるのでしょうか。その辺について調べていらっしゃるかどうかと、それからもし調べていらっしゃったら、簡単にご報告ほしいと求めました。","respondent":"中島防災課長","answer":"他区において、まだ全ての区が改正できていないのですが、調べたところですと、いずれの区も保証人がいる場合は無利子となっております。保証人がいない場合につきましては、１％が１５区で、１.５％が４区と聞いているところです。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"制度全体というか、その利率以外にも、災害障害見舞金や災害弔慰金なども、そのようなことをあわせて、ほかの区の状況などは調べていらっしゃらないのか尋ねました。","respondent":"中島防災課長","answer":"災害障害見舞金、災害弔慰金のところにつきましては、ほかの区についても基本的に、特に改正はしていないと。今回は、あくまで災害援護資金の貸付利率のところと、あと保証人のところとか、そういうところの改正であると認識しています。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"１つは、災害援護資金の上限３５０万円は、どうしてこの３５０万円というものが出てきたかということが１点です。品川区が別に４区の方でもいいのだけれども、それを１２月中旬に定めようとしたのはどのような理由があったのかということだけ説明を求めました。","respondent":"中島防災課長","answer":"この貸付限度額というものが３５０万円というふうに決められていますのは、法律でもう決められておりまして、それに基づきまして対応しています。第２回定例会で改正している区もあるのですけれども、遅れてしまったところもありますが、今回の第４回定例会で改正をするです。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"確認","question":"法律で３５０万円というと、地方も含めて全部３５０万円なのか、特別区はいろいろな割合の中で変わったりもするではないですか。これはもう最初から３５０万円が上限だよということで何の動かしようもなかったのか、全国一律そうなっているかというところだけ確認させてください。","respondent":"中島防災課長","answer":"私の知る限りでは、特別区の担当課長会などでもそのような声が上がったという記憶はありません。以前あったかどうかまではちょっと調べてはいないのですが、少なくともここ１年についてはなかったと認識しております。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"その辺のところ、品川区では、他の自治体も含めた債権管理の仕方というようなものはどのようにお考えなのでしょうか。高齢化社会と債権管理の経費の扱い方についての考え方をお知らせください。","respondent":"中島防災課長","answer":"基本的に品川区といたしましては、債権管理の条例がありますので、そちらに基づきまして行っていくことになろうかと考えています。保証人も含めまして相談を受ける中で、貸付けをしっかり行い、あわせて債権管理もしっかり行っていくということになろうかと考えています。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"災害ですから、皆さんお困りの中で融資申請をするわけです。これは債権管理に関するコストというものは、その辺のところの管理をしっかりしていただきたいと思うのですけれども、最後にそのことをお願いします。","respondent":"中島防災課長","answer":"今回１０年の貸付けという形になりますので、１０年ということになって、債権管理も大変難しくなるかなと思っています。延ばしたりというところもあるようなので、コストも含めまして適正になるように努めてまいりたいと考えています。","id":"exchange-016"}]},{"id":"topic-02","title":"令和元年請願第１８号、武蔵小山駅周辺再開発の環境調査実施と計画見直しを求める請願","agenda":"令和元年請願第１８号、武蔵小山駅周辺再開発の環境調査実施と計画見直しを求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それぞれについてある程度お伺いしたいのですけれども、その後申請し、指定されたということなのでしょうか。伺いたいと思います。","respondent":"稲田都市開発課長","answer":"９月の当委員会で地域での説明会を実施したこと等を報告させていただきましたところです。それから防災上の安全、このような形で区のほうとしても地域の皆様方の意見を取り入れた形での方針づくりをやっているです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"それとも生じていないと考えているのでしょうか。伺いたいと思いますし、ここの複合被害については一応考慮されているという理解でよろしいのか、その辺ちょっとお伺いします。","respondent":"稲田都市開発課長","answer":"私どもはこのシミュレーションに従った形の対策を実施し、実際１年間はかってみると、黄色になったりする部分もあります。このシミュレーションに従って実施後の調査も行いながら対応するということで、このような考えで今やっているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは現状より悪くなるということですから、それは風害そのものなのではないですかと伺ったので、全然質問に答えていないのです。その後、大崎ではどのような対策が行われて改善されたのか、これもあわせて伺います。","respondent":"稲田都市開発課長","answer":"そのポイント以外でも、地域の人がここは風が強いのではないかなどという話、これはきちんとお聞きしまして、その対応策も考えるです。も現地調査等を何回かやりながら、植栽の位置を変えてみたり、大きいものにしたりと対応施策をとってきているです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと大崎のほうは、植栽をやって今現在どうなっているのですかということも伺ったので、改善されたのですかということも伺いたいと思います。なぜ令和４年度から増便、何で令和４年度からなのかということ、８両編成でその状態は解消されるとお考えなのかどうか伺います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"まちづくり、超高層をどんどん建てていくことでいいのかどうかということも含めて検討するのが行政の役割ではないでしょうか。全体で想定しているお子さんの数、保育園や幼稚園、学校に通う人数などを予測しておられるのかどうか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"両地区合わせた人数の想定というように聞いておりまして、保育園規模が３０名程度ですので、それに見合った検討でやっていくと。３０名規模の保育園を設置して対応できるというところでやっております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"今お伺いしたのは予測をしているのかどうかということだったので、では予測はしているということでよろしいのか、また３点伺います。やはり高さ制限というものを検討すべきだと思うのですけれども、検討すべきというところに関して、区の考えはいかがか尋ねました。","respondent":"稲田都市開発課長","answer":"居住者も増やしながら、そしてまちのにぎわいもさらに継続して、活力を生み出していくというところは非常に大事な部分です。このような高さも必要ではないかと考えているところですので、そのような方向で今後もいくというようなところです。","id":"exchange-022"},{"speaker":"松本委員","kind":"質問","question":"先ほどの安藤委員からの質問に対して少し疑問に思ったのが、なぜ令和４年度からというところで、相鉄線の関係だと思うのです。こちらのほうの情報、６両から８両になるのかなど、そのあたりのところをお願いできればと思います。","respondent":"稲田都市開発課長","answer":"東急に私どもが聞く中におきましては、いろいろと調整が必要だという、このような回答を受けているです。それ以外の鉄道につきましては、現在詳しい状況について承知していないところです。","id":"exchange-023"},{"speaker":"松本委員","kind":"質問・要望","question":"それはやはりどうかなと思うのですけれども、どちらも２０２２年、令和４年度に８両化に向けてという情報が出てくるのです。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をさせてください。それから先ほど来、それに対して対応していくという意味では再開発も地区計画もスタートは同じだと思っているので、そこの確認だけさせてください。","respondent":"稲田都市開発課長、鈴木都市計画課長","answer":"委員おっしゃるとおり、地区計画をかけて、用途地域の変更はしないのですけれども、地区計画の中で容積等の形を決めていくです。それが再開発だけでなく、それ以外の用途地域の変更についてもですが、このところにつきましては… どう目標を立てて進めていくかということは、木密整備地域などで進めている地区計画、さまざまです。そういう意味では、まさに事の発端はやはり地域の声、発意というところだと思います。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は余りこのような調査には詳しくないのですが、例えば、体重７０kg程度の成人男子が基準になっていたりするのです。どのような人たちを基準にして考えておられるのか、一定基準がないと調査できないと思うので、その辺のことをぜひ教えてほしいと求めました。","respondent":"稲田都市開発課長","answer":"嫌な風というのはどのようなものがあるかという感覚的な話が載っているのですけれども、一般的な結論を示すことは非常に難しい。１年間実施をする中において、そのような風の強い部分、そのようなものには対応していこうというふうに考えております。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのような先行した事例というものは、その辺をこれから参考にしていこうというような計画があるのかどうか、その辺について伺いたいと思います。その建物の方たちだけでなく、地域のことも考慮したような倉庫の設置を求めているのか、その辺も伺いたいと思います。","respondent":"稲田都市開発課長","answer":"実際にはかっていく、今も武蔵小山パルム駅前地区が建ちましたので、１年間計測しながら検討していきたいと考えています。地域の方々に対応する防災倉庫、このような防災倉庫も備えているですので、地域の方々に対応する倉庫も十分つくっているです。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"最後に１点だけ、現実それがどう機能するかというところまでは、そのようなこともきちんと話し合われていくということでしょうか。その点、１点だけ伺います。","respondent":"稲田都市開発課長","answer":"防災協定を結んでやっておるというところは、地域に、還元するというのですか、地域に資さなければいけないですので、その辺はしっかりやっていきたいと考えています。","id":"exchange-028"},{"speaker":"大沢委員","kind":"質問","question":"既に行政は十分に手を尽くしていただいております。よって、この本請願は不採択、繰り返しますけれども、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"意見","question":"それに伴って、環境対策等も出てきておりましたが、品川区でもその環境対策等は行われていると私は理解をしています。そのような意味からも、この請願は不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"意見","question":"請願項目の１番、２番にある、今できる中での対応をしていただいていることは理解できます。今、そういった面では高層化ありきということは当てはまらないのかなと考えていますので不採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択を求めたいと思います。ですので、こうしたまちづくりを見直すべきだという立場から、採択を主張します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"吉田委員","kind":"意見","question":"やはりその辺は風工学研究所などのデータ任せにせず、区として、そのような個別の状況もきちんと勘案した調査もすべきだと思います。そのことだけでも、この請願は妥当と思いますので、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"松本委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。やはり先ほどの要望を、私も使っている線ですから、いろいろと調査はしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"}]},{"id":"topic-03","title":"令和元年請願第１９号、住民の合意が得られない放射２号線道路計画の中止を求める請願","agenda":"令和元年請願第１９号、住民の合意が得られない放射２号線道路計画の中止を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"この請願に「放射２号線道路の計画を都に求めたのは濱野区長です」とありますけれども、これはどういうことなのか、説明をほしいと求めました。あわせまして、さまざまな会派からこの間要望も出されていたと思うのですが、現在の都との交渉状況がどうなっているのか伺います。","respondent":"鈴木都市計画課長","answer":"木密地域が多く広がる地域において、さまざまその辺は関係する区市にも問い合わせがあったというふうに認識しています。区としてもこうした路線をしっかり位置づけていただいて、早急な整備を進めていただきたいというやりとりがあったというふうに認識しています。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"しっかり、当時は放射２号線と補助２９号線だったと思いますけれども、続けて早期に整備をということを求めたということですね。整備推進の理由を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"補助２９号線を含めて、その後さまざまな検討を加えられて、シミュレーションを行いその効果的なところを検証の上で今進められているです。車、交通環境のネットワークの構築というところもございまして、それもあわせて今進められているところです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここ大事なところなのでもう一度お伺いしますけれども、中原街道では４分の１も減っているのに、円滑化という理由は成り立つのでしょうか。何というのでしょうか、３３ｍですか、では防災上どのような効果があるのか尋ねました。","respondent":"鈴木都市計画課長、高梨木密整備推進課長","answer":"そうした視点でまさに東京都のほうが検証して、今事業を進めようとしているところだというふうに区としては理解しているものです。不燃領域率、一定程度の目標値がありますので… 救援路ともに効果を上げるものというふうに考えておりまして、特定整備路線そのものの必要性について、区としては考えているところです。放射２号線が通る町丁目を含む地域につきましては、防災性の向上を図るために必要な道路であると…","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後にこの請願にかかわってお伺いしたいのですけれども、共産党は、この放射２号線は必要ない道路だと考えております。これはこの委員会に対する要望であります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"吉田委員","kind":"提案","question":"今の安藤委員からの提案といいますか、私もこのような懇談会というものは、議会として開催する必要があるのではないかと思います。続いて質問してもいいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"説明会の開催を求めるということは、本当にごく自然の要望ではないかなと思います。きちんとご答弁もあるわけですし、その説明会を開く意思といいますか、そのようなものがあるのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"用地説明会でしっかり、区の認識としてはしっかり地域の方への説明の場を設けて進めて、今事業が進められているという認識です。それは地域の声に対してどのような形で説明するかという手法的なところだと思うのですが、区の認識としては、回答しているというような認識です。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"やはり説明会という形でほかの方たちの意見や質問を聞くということも、ああ、そういう視点も必要なのだということを気づくきっかけにもなります。やはり説明会というものは、個別の対応以外に有用なチャンスではないかと思うのですが、その辺について見解を伺います。","respondent":"鈴木都市計画課長","answer":"それの沿道の方々への説明会、それもここの資料に記載してありますとおり、これまで東京都においてしっかり行われてきているというような認識です。そうした中で、説明会を今後区として都に説明会という場を設けて再度行っていただきたいと求める考えはございませんが…","id":"exchange-041"},{"speaker":"吉田委員","kind":"意見","question":"説明だけに限らず、もう少し意見交換というものが必要だと思いますが、説明というのは最低限の区の責任ではないかと思います。たとえ都の事業であっても、区としての説明会の開催は必要ではないかと主張させていただいて、最後にいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問","question":"それに基づいて行っているわけですから、早急に整備をしていく、これが大切だと考えています。そのような考えで不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問・要望","question":"理由ですけれども、まず請願の表題が「計画の中止を求める請願」という形になっております。いろいろ項目としては１から４まで、意見交換などいろいろなご意見もありますけれども、基本は中止を求めるというように読み取れます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは世論なども踏まえて、幾らでも全国には例がありますので、私はそのような方向にかじを切るべきだと思います。そういった意味からも採択を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すということで、採択を求めたいと思います。その中で、そこの地域の人たちが説明会の実施などを求めてきているということは、当然理解できる心情だと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"}]},{"id":"topic-04","title":"令和元年請願第２０号、品川区Ｃ地区の生活権に関する請願","agenda":"令和元年請願第２０号、品川区Ｃ地区の生活権に関する請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区の役割について伺いたいのですが、どういった支援、援助を行っているのか。こちらについては出ているのかどうかも伺います。","respondent":"稲田都市開発課長","answer":"やはり大井町のまちづくりということで、区の中心核であるということも考え、まちづくりの動向を把握するために同席させているところです。勉強会の費用ですか、専門家の派遣などの費用におきましては、この会では使っていないというところです。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"これはその当該の地権者のみならず、品川区としては、この古き良き大井町らしいまち並みというものをどう理解しておられるのか伺いたいと思います。区としてはこの書かれている願いにどう応える考えがあるのか、それともないのか、伺います。","respondent":"稲田都市開発課長","answer":"現在もさまざまな機能が入っているところですが、中心核というところもありますけれども、地域の方々が住みよいまちというところも考えております。意見を言っていただいて、よりよいまちを今後つくっていくためにいろいろな意見を言っていただいて…","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"あるいはこの周辺地区、それはそれでいいですよ、では低層でいきましょうとなるのですかということを１点お伺いします。特に区からいうとメリットだと思うのですけれども、メリットが出てくるのか、その２点お伺いします。","respondent":"稲田都市開発課長","answer":"いや、そのようなところをしっかりと話をしていただきながら、この大井町にふさわしいまちづくりをやっていただければと思っているところです。住宅・業務床の供給の促進、昭和６３年に設けられたというところで…","id":"exchange-049"},{"speaker":"安藤委員","kind":"確認","question":"今のまちに対する皆様の思いが出ていましたので、そのような思いを感じたものですから、今質問させていただいています。１点だけ、確認なのですが、確認させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"たけうち委員","kind":"質問","question":"お気持ちはわかるのですけれども、品川区も参加しているとはいえ、品川区が責任を持って届けなければいけないということになるのでしょうか。ぜひお願いしますぐらいは言えるかもしれないけれども、区が責任を持つことではないのかなとは思うのですが、そこの見解はいかがか尋ねました。","respondent":"稲田都市開発課長","answer":"この勉強会はあくまでも権利者の方々が自主的にやっているですので、区がどうしろこうしろというところのものではございません。ただ、できる限り届けるようにしてくださいというふうに伝えておりまして、事務局のほうもできる限りやっていくというところの話は聞いております。","id":"exchange-051"},{"speaker":"たけうち委員","kind":"意見","question":"そもそも区が責任持ってやるのは、ちょっと限度があるのかなと思います。感想ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"松本委員","kind":"質問・要望","question":"今年の５月ですか、所在の不明ということは大きな問題だと思っていますので、これは区としてもできることはやってほしいと求めました。ちょっとお伺いしたいのですけれども、大体どのくらいの割合で、もし来ていたらお答えほしいと求めました。","respondent":"稲田都市開発課長","answer":"郵送数は２２０、なぜ差があるかというと、登記簿のほうに住所が載っていなかったというようなことのようです。それから戻ってきたのが５２というように聞いております。","id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"かなりの数が戻ってきているような状態だと思いますので、これは質問というより、要望で、できる限りご協力ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"区として責任を負うというところまではあれですけれども、先ほどのご答弁だと、できる限りの調査を事務局に要請しているという範囲なのです。そこはもう少し何かできることがあるのではないかと思うのですが、あくまでその姿勢、区としてはその辺どのようにお考えか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"区のほうにも伝えてくれという話が来ていますので、区は伝えているところです。要するに権利者の方々が自主的にやっている勉強会ですので、区は今のスタンスでやっていきたいと考えています。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"一番調べられるとしたら、これはあくまで主張になってしまいますけれども、ぜひこの請願の趣旨というものは本当にもっともだと思います。今後またこの請願代表者の方や勉強会に参加されている方たちと話し合いの上、何かできる方策はぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"区のスタンスとしては、どうなるかわからないものに対して区が調査をして調べますなどということはあってはならないことだと、逆に私は思っています。そこはきちんと分けておかないと、何のための勉強会かわからなくなってしまうから、その辺のところは明確にお答えほしいと求めました。","respondent":"稲田都市開発課長","answer":"このＣ地区の勉強会、権利者の方々が話し合われて、意見を交換しながらよりよいまちをつくっていくというようにやっているところです。権利者の方々がやるというところにおきましては、区のほうは現在のところ、区の意見を勉強会に申し入れるというところはやっていないところで…","id":"exchange-057"},{"speaker":"石田（秀）委員","kind":"意見","question":"５２も戻ってきていると把握しているのであれば、再開発でやるかもしれない、これは今わからないわけです。区がそこの携わり方をきちんと言っていただかないと、最後の語尾がよくわからなかったので、もう１回との意見を述べました。","respondent":"稲田都市開発課長","answer":"届いていない方へ、区が届けるようにどうのこうのしろというところではございませんで、区としては届いていないところには事務局等がしっかりと届けるようにしてくださいと言うところまでです。","id":"exchange-058"},{"speaker":"大沢委員","kind":"確認","question":"そのような立ち位置でいいということですよね。そこを確認させてください。","respondent":"稲田都市開発課長","answer":"その考え方でやっております。","id":"exchange-059"},{"speaker":"たけうち委員","kind":"質問","question":"結論を出すで、不採択でお願いします。これは一元的には区ではなく、この事務局、またこのまちづくりの世話人の方でお願いしたいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"この大井町は区の中心核だということもあって、上位計画までつくって、行政として一定の方向性をつけてやろうとしているのは明らかなわけです。ですから少なくとも、私は品川区がやはり行政として、採択を主張します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問・要望","question":"その結論を出すにあたって、なるべく多くの方たちの参加をもって結論を出したいということだと思います。結論次第によっては区にもいろいろな影響もあることですし、ぜひその辺については検討をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"松本委員","kind":"質問・要望","question":"２００幾つあるうちの５０に届かないということは、これは制度上もやはり、本来は考えていかないといけないところだと思います。なので、可能な限り、民民の中でも区としてはできる限りのことをやっていただきたいというところで、趣旨採択を主張したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"１人でも多くの方が、こういった請願者の方々の意を酌んで意思を示すということは大事だと思います。吉田委員はいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"}]},{"id":"topic-05","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"それ以前にこのようなことになっているよというような情報は寄せられたりはしていなかったのでしょうか。その辺ちょっと伺いたいと思います。","respondent":"溝口公園課長","answer":"もう一度改めてご説明します。は年１回の遊具点検、さらに日常点検、そういったものを大切にやっていきたいというふうに考えているところです。","id":"exchange-065"},{"speaker":"吉田委員","kind":"確認","question":"このようなことは結構、今回はけがに至ったということで、その方のお申し出があったというふうに理解していいでしょうか。ごめんなさい、もう１回確認させてください。","respondent":"溝口公園課長","answer":"申しわけありませんでした。今回はけがされた親御さんのほうから、今回滑り台でけがをしたということで申し出があって、けがをしたという事実を確認したということです。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"けがという状況が起きて、ああ、このようなことになっているのだということがわかったということなのでしょうか。１つよく言われるのが、答弁難しいかと思いますけれども、伺いたいと思います。","respondent":"溝口公園課長","answer":"先ほども年１回の遊具点検の中で少し、地面がへこんできてくぼむ、そういった状態が昨年の遊具点検の中で実際に見られたところです。やはり公園管理、そういった事故の予見というものをしっかり持って点検にあたっていく、そういったことが大事だと改めて感じているところです。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"別にけがというほどではないけれども、公園課としてはどうなのかということを言ってこられる方が、いるのではないかと思います。そのような情報は大切と考えていただいて、巡回点検はしていたとしても、ぜひ改めての点検などをしていただけるようにお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて確認させていただきたいのですが、この当該公園での直近の点検というものはいつだったのか伺います。そして現在、滑り台は具体的にどのような補修がされたのか伺います。","respondent":"溝口公園課長","answer":"週１回必ず巡回の目が行くような形をとっておりますので、そういったところにも週１回は必ず見ながらやってきたところです。より安全な形で子どもたちに楽しんでいただけるような遊具にしようと考えて、補修をしたところです。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際に事故に遭った方には、このようにしましたよということを具体的に報告してほしいと求めましたし、その徹底をお願いしたいと思います。最後に、またそれが今後の公園整備や運営にどのように活かされているのかということだけ聞かせてください。","respondent":"溝口公園課長","answer":"そういったところも含めて示談に至っているというようにご理解いただきたいと考えています。課内に共有しながら公園の整備、または維持管理、そういったものに役立てていきたいというふうに考えているところです。","id":"exchange-070"},{"speaker":"たけうち委員","kind":"質問","question":"そこを利用される方がボランティアで点検をされていた仕組みがあったと思いますが、今、これがどうなったのかということ。それからこの専決処分２つに関係するのですけれども、このような形で議会に報告しますなどという了解はとられているかどうか、そこを説明を求めました。","respondent":"溝口公園課長","answer":"はそういったものに対して、全く制度としてなくなったわけではなくて、そちらのほうに引き継ぐ形でやらせていただいているところです。今回、相手方には、こういった形で報告するということの確認をとりながら、専決処分の報告をさせていただいているものです。","id":"exchange-071"},{"speaker":"たけうち委員","kind":"質問・要望","question":"１週間に１回、または２週間に１回点検されているということで、安全な公園の管理に努めてほしいと求めました。それは要望でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけ、お願いというようになるのかもしれないのですけれども、今回お子さんが着地マットの破損で左膝を裂傷したと。安全を確保していただいて、この例がどうということではなくて、余り規制をかけるようなことはしてほしくないということだけお願いをしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２９日の須貝行宏議員の質問で、災害時・停電時の中高層マンション対策についての質問なのですが、あるいは照明についても共用部分のみなのか。現行義務づけている非常用発電機で、結局どのような活動までができるのかということを知りたいと思って、質問したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"どこまで義務づけているのかということと、その義務づけたことによって、どのような活動までができるのかということもお伺いさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"で在宅避難用の設置は義務づけていないという答弁もあったので、では結局その義務づけられた発電機で、どのような救援活動ができるのか。何人の方が何時間、何日滞在できるのかとか、そのようなところまで伺わせていただきたいと思ったということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/876969?Template=document&Id=4278#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":52158,"voices":204}},{"id":"r01-20191202-9","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"文教委員会","time":"午前１０時００分～午後 ２時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件整理しています。","topics":[{"id":"topic-01","title":"令和元年請願第１７号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和元年請願第１７号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"公私間の格差の是正をしてほしいということで、毎年のように出ておりますけれども、公私の格差というものが、現状、どうなっているのか。保育費の負担のところで伺いたいと思います。","respondent":"大澤保育支援課長","answer":"公立幼稚園と私立幼稚園の保育料の差ということでご説明します。１,０００円未満の保育料負担という方が１０％強になりますので、大体８割の方は保育料の負担はほぼゼロとなる計算となります。","id":"exchange-001"},{"speaker":"塚本委員","kind":"確認","question":"今、ご説明で私立の入園料の補助金というものが、現在、１０万円と説明があったのでしょうか。これは私の認識が間違っていないかどうかの確認なのですけれども、「直接助成金」という言葉が２回ほど出てくるのです。","respondent":"大澤保育支援課長","answer":"区内の私立幼稚園の入園料ですが、現在、１１万円から１６万円の間で、平均で約１３万円となっております。恐らく園への助成ということと保護者への助成ということで、直接園、または保護者へ助成をしているという意味で使われていると認識しております。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"どういう状況になっているのか。区としての負担が軽減している部分があれば、それがどれぐらいなのかを説明を求めました。","respondent":"大澤保育支援課長","answer":"これまでなかった預かり保育の１万１,３００円の部分の区の負担が新たに出てまいりますので、預かり保育の人数によって区の負担が違ってまいります。ただ、預かり保育については、今後、増えていく傾向だと考えております。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問・要望","question":"保育課ですか。もう少し具体的な説明があれば教えてほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"その際に、この児童の保護者が要求する内容については、かなり過大な要求であるとの認識と、弁護士からも得ているところです。個別で対応してくれということについては、まだ１人で子どもを見ろなどの要求については、区側としては過大な要求と考えているところです。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"この陳情者の方が理由に書いている暴力行為等は、実際、あったのでしょうか。それは、区としてはどういう認識なのか。","respondent":"吉田保育施設調整担当課長","answer":"多分、噛まれただろうと思われる傷があった。園内で起こったことであれば、園長が謝罪したという形にはなっております。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"耳をちぎられそうになる、あと、目をつつかれて流血したなど、いろいろ、ある意味深刻な状況が書かれているのですけれども、医師の診断など、この陳情者の方は受けられたのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"実際は保護者がお迎えに来た際に、自分の娘に暴力を振るっていると言われている子どもに、父親が目をつつかれたと言っている次第です。医師の診断書につきましては、特にその時点では何も上がってきておりません。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご説明を伺って、陳情が４つ出ていて、現在の状況はこのような状況なのですけれども、区としては、今後、どのような対応をするのか。見込みというか、その辺りを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"１１月１日から数日登園いたしましたけれども、３歳児クラスの集団の中で遊んでいたり、園では考えております。連絡をとるとともに、精神面の不安があるのであれば、そちらは医療機関等の受診をお勧めするという形をとってまいりたいと考えています。","id":"exchange-007"},{"speaker":"横山委員","kind":"確認","question":"お話をお聞きしましたけれども、個別の事例等に関しましては、行政側の確認や現場において対応していただくことが適切かなと考えております。いただいた情報や今日の議論をお伺いしたところにおきましては、現場において対応していただくということで、まずはお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"理由として、まず、前提となる事実の段階で、区の認識と陳情者の認識が大分ずれている部分で、なかなか議論が難しい。なかなかこの要望自体が、非常にハードルの高いもので実現困難と考えておりますので、不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"一人ひとりの状況に応じて対応していくということが求められているのは事実ではありますけれども、今、そういった中で。今後とも、現場におけるそういった対応はしっかりとお願いしたいと思いますけれども、この陳情に対しては不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"意見","question":"保育園と保護者の信頼関係なしに保育は成り立たないと思いますので、区には引き続き信頼関係を築く努力を続けてほしいと思います。ですので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"筒井委員","kind":"確認","question":"中立公正さを保つということは非常に重要だと考えておりますけれども、要旨の理由となる部分で、事実が確認できないということです。申したとおり、事実確認が客観的にできないという状況であるから、そうした理由で不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その仕組みの中で、保育園との課題を解決していると思います。園の姿勢を理解していただくということをお聞きしたので、誠意をもって対応していくことでご理解をいただくように努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"保育士の加配等も品川区ではやっているわけですし、そういった中で、現場の中でやられているものをしっかりと進めていただくことでよいと思います。この陳情に対しては、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"理由は、先ほど述べましたとおり、事実の確認ができないということであります。支援拡充というのは、引き続き、区としてもぜひ研究していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"グレーゾーンだけでなくて、こういった支援を必要とするお子さんたちへの研修を現在もやられているということで、ぜひそれをさらに拡充して。現在もきちんとされていると思うのですが、現在以上の対応ができるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"理由としては、この陳情を出されている方の一事例内容をもって、区内のすべての保育所に防犯カメラを設置していくということは難しい。そこまでは至らないと思いますので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"理由は、先ほども述べましたとおり、要旨の理由の事実確認がとれないということであります。一般論として必要でありますので、暴力行為の防止につきましては、区としては引き続きしっかりと行っていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"カメラ設置については、先ほど、数々の状況からなかなか厳しいという区の説明がありました。園での様子を、園長をはじめ、保育士等々がきちんと把握していっていただいて、そこでさまざまなことを解決していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"結論は、不採択でお願いいたします。理由としては、引き続き頑張っていただいて、先ほどと同じになります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"結論としては、不採択でお願いいたします。現実的でないというか、難しい問題だと思いますので、これは不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"理由は、先ほど来、述べているとおり、要旨の理由の事実確認がとれないということであります。ただ、一般論として、いじめの防止ということは、区としてしっかりと行っていただきたいと存じます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。前の陳情でお話ししたのですが、その情報共有をし、問題が起きないように対応していっていただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"週２.５日配置されているということで、週５日、毎日勤務できるようにということで求めているわけです。実際に、今の２.５日の配置の中で、学校図書館が開いていない日がある学校があるのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"学校図書館のボランティアがいる学校で運営しているところ、さまざまなやり方がありますが、できるだけの活用を各校で考えているところです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"司書はいないけれども、さまざまな学校の状況で開いているということなのですね。毎日開かないという学校はないということでいいのか、そこをお伺いさせてほしいと求めました。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"実態そのものを調査したことはないのですが、学校の運営の中で有効に活用するという法則のもとで運営していますので、有効に活用されているものと承知しています。 実際に授業中など、例えば、管理者がいないときには鍵をかける。昼休みに本を読めたり、１５分休みに読めたり、そういった有効活用をしている学校が多くあります。","id":"exchange-025"},{"speaker":"のだて委員","kind":"提案","question":"それがわからないと、合った本の提案をすることができないと思うのですけれども、その点、いかがかというところ。そういった点についても伺えればと思いますとの意見を述べました。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"同じ人がずっといるというのも大切だと思いますが、いろいろな方が子どもに関わるというのも、また有効なことかと図書館では認識しています。そういう意味では、その子に対応するために… 特別支援教室専門員が各校配置されていますから、場合によっては、本人の観察を授業とは違う場所でしているようなケースもあります。それは、図書室に限ったことではなく、さまざまなケースがあろうかと思います。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"以前に、平成３０年度の事務事業評価シートの図書館のところで、今後の方向性のところに書かれています。ぜひ配置日数の増加をお願いしたいと思うのですけれども、この間の検討状況といったところを伺えればと思います。","respondent":"横山品川図書館長","answer":"私どもも平成１７年度から８年かけて配置を完了しているような状況ですので、なおかつ、完成させていきたいということで検討しています。そちらについては、５年、１０年のレベルになりますけれども、最終的には全日いるような形が望ましいと、こちらでも考えているところです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"５年、１０年かかるというお話だったのですけれども、ぜひ進めてほしいと求めました。利用の頻度や何の授業に使われているのかというところを伺えればと思います。","respondent":"横山品川図書館長","answer":"読み聞かせで５,８６７時間、ブックトークで１,３４０時間という形で、よく活用していただいています。授業での教科利用が１,６６４時間という形にはなっておりますが、数は違いますけれども、満遍なくご利用いただいているような状況です。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"今、利用状況をご説明いただきました。そういった中で、学校の司書はどういった形で先生と協力をしてやっていらっしゃるのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"子どもたちに読み聞かせを行って、その感想を聞く。ブックトークとして、本の紹介をするなど、さまざまな形でその授業を一緒に組み立てる形で協力させていただいているところです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"子どもの情報を共有できなかったり、目の前でけんかやトラブルがあったときに、それを注意することができないということもあるかなと思うのです。そして、業者が変わったときに、引き継ぎもできないのではないかと思うのですけれども、その点について、伺いたいと思います。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"先ほどご案内しました月ごとの会議ですが、作業企画会議に責任者が出席しまして、相談や個別の対応を学校と一緒に考えることができます。… 仲よくしようね」と声をかけてくださると思うのです。それと同じような対応は、子どもの指導あるいは授業は、教員が行うというのが大前提です。 先ほど、引き継ぎについてご答弁させていただいていなかったので、お答えいたします。事業者が変わった場合は、引き継ぎ期間を設けて…","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"今、国が学校司書を１.５校に１人配置するという交付税措置を始めたみたいなのです。２３区についても、さらに配置していけるのではないかなと思うのですが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"２.５日ですから、そういう意味では、事業としてもなかなかすぐに倍にするということは難しい状況もあります。金額的にも精査しながら、また、協力関係を仰ぎながら、長期的に考えることかなと考えています。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"これからの国の措置ということなのですけれども、これが行われることによって、配置の増員や日数を増やすといったことができるということでいいのか尋ねました。","respondent":"横山品川図書館長","answer":"詳細が確認できてからのことになると思いますが、財政当局と調整しながら、今後のことについては、財政的にも、運営そのものについても考えて、検討しながら進めていきたいと思います。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に１点。教員との協力がスムーズにいって、自ら学んでいくということがより進んでいくのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"その上で、先ほどもお話がありましたように、会議などでいろいろとご助言いただいたことを教員としてもしっかりと有効活用している。そのような状況があります。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"そして、司書教諭、学校司書の人的配置促進ということが掲げられております。先ほどのご答弁と重なるところはあるかもしれませんが、この文部科学省の計画を受けて、品川区としては、今後どのようにやられていくのか尋ねました。","respondent":"横山品川図書館長","answer":"国の第四次計画を追い風として、これからより充実させたいということで、今、国のレベルよりも品川区のほうが進んでおりますので、国の方針に則りながら、品川区の計画自体もより充実させて進めていきたいと考えています。","id":"exchange-034"},{"speaker":"筒井委員","kind":"意見","question":"不問にしているところが、ほかには中央区、港区、あきる野市など、そうした品川区を含め７自治体しかないのです。そうした他自治体との比較、現状を見て、どういうご認識なのかを説明を求めました。","respondent":"横山品川図書館長","answer":"現状では、９割方、司書資格をもった方がスタッフとして働いていただいております。他区や他市の比較で、それぞれ充実を目指すという考え方で進んでいるところで、特に雇用が５日間でないから劣っているという考え方はございません。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"そうしたお考えがあるということなのですけれども、機動的な、柔軟的な取り組みができないということをおっしゃっているのです。そうしたご不満というか、問題点の指摘については、どのようなお考えなのか尋ねました。","respondent":"横山品川図書館長","answer":"そちらに関しては、学校図書館の図書館長である学校長に対して、年に１回、状況調査をさせていただいているところです。その中では、これからの問題点を聞きたい調査なのですけれども、学校の中の一員として機能しているという形で反応が返ってきているところです。","id":"exchange-036"},{"speaker":"せお委員","kind":"質問・要望","question":"今現在、コミュニティ・スクールとの関わりや、その関わりが、今後、どのような見通しか。お話しほしいと求めました。","respondent":"横山品川図書館長","answer":"多くの学校で学校図書館の支援スタッフを学校の一員として、コミュニティ・スクールの一員として扱っていただいて、スタッフも張り切って子どもたちに対応していると聞いてあります。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、東京都教育委員会の考え方はどのような考え方なのでしょうか。日常的に敏速にというか、迅速にというか、さまざま連絡・調整がとれるような仕組みは、どのような形で行われているのか尋ねました。","respondent":"横山品川図書館長","answer":"学校図書館法でも必置の施設ですので、学校でも重要な位置づけになっておりますし、授業でも欠かせない存在だと認識しています。運営会議が月１回という形で、例えば、事業者の責任者が即時に駆けつけるような体制になってあります。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"意見","question":"都は、司書教諭、教員の中で資格をもった方が学校図書館の運営をするという形の位置づけにしているのかどうか。つまり、こういった学校運営スタッフを２３区がこのような形で雇用するのを前提としているのかというところですとの意見を述べました。","respondent":"横山品川図書館長","answer":"雇用や存在の形態ではなく、学校図書館を充実させるために司書教諭や学校司書が連携してあたるという観念的な計画のように承知しています。品川区においては、司書教諭については、法令設置の規定どおり配置されている状況です。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"費用の問題なのですけれども、今現在、民間委託されているということなのです。仮の話になるのですけれども、区が司書を直接雇用した場合の費用と、民間委託している今現在の費用を比較したら、かなり大幅な差があるのか尋ねました。","respondent":"横山品川図書館長","answer":"直接の詳細な比較をしたことがないので、金額的に幾らというのは出ないのですが、一般的な委託だと、会社の管理費が入りますので、その分をスタッフ個人の給与を落とすような形で調整するところが多いと聞いています。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"管理費は、民間委託のほうが負担が大きいということか尋ねました。","respondent":"横山品川図書館長","answer":"ですので、それを直接割り返して個人のお給料になるという形にはならないという意味では、管理費が入るというワンステップになります。直接雇用の場合は、基本的には一生雇用するという考え方で、一概の比較というのはなかなか難しいかなと思います。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"地域の方々、父兄の方々、いろいろな方々が子どもたちに関わっていくことが望ましいと考えております。ですので、引き続き、地域の方々と協力していただきながら、民間の協力なども仰いでいただいて進めていくということをお願いしたいなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"芹澤副委員長","kind":"意見","question":"なぜそのようにしているのかはわかりませんが、いろいろな教育の成長の１つの大きなステップ、場所になっていると思っています。週５日にしたことで、この品川区のよさがなくならないように、ぜひさまざまな研究を続けてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"塚本委員","kind":"意見","question":"全日に、という話においては、不採択でお願いしたいと思います。そういった意味からも、現時点においては不採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"のだて委員","kind":"意見","question":"いろいろな方が関わったほうがいいというお話もありましたけれども、それはそれで。学校司書も週５日、それによって子どもたちの学習にも寄与するというところで、採択をしていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"筒井委員","kind":"質問","question":"理由は、日数を増やす、将来的に毎日勤務ということは、区のほうも方向性を認めているところですし、私もある程度の日数は必要かなと考えております。ただ、民間への委託の問題やさまざまな課題があるところから、趣旨は採択したいという考えで、趣旨採択ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"意見","question":"では、自治体としてどうしていくかというところで、品川区としては２.５日という形でやられているのです。必ずしも毎日という形がベストかどうかというのは、また別で、そのような考え方から、趣旨は理解しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の陳情は、全体としてインクルーシブ教育をより充実してくださいということだと思うのですけれども、まず、確認をさせていただきたいのです。今年度は３回実施したというお話でしたけれども、毎年３回くらいなのか、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"特殊教育から特別支援教育に変わったここ１０年間の推移の中で、当初は教職員全体、１,２００人を一堂に集めるような研修会も数年間行いました。別に特別支援教育コーディネーターが各校に複数おりますので、区で行う研修会とは別に…","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"１点。今、特別支援教育コーディネーターのお話が出ましたが、その役割、どういったことをやられているのか、ご説明ほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"周囲の学校との関係調整、連絡調整、あるいは保護者との対応に関する教員との共通理解、あるいは校内委員会を管理職、担任と一緒に主催する。担任とご家庭、あるいは連携する学校同士での情報共有などに努める。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"別の件なのですが、巡回相談員の巡回数を増やすということも陳情に書かれておりますけれども、今の巡回はどのくらいの頻度でいらっしゃるのか。どういった業務、支援を行っていらっしゃるか、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"１人の巡回相談員が５校ないし６校、１つの小学校、学校間連携も意識した状態の担当校を２週に１日巡回しております。そのような活動をしております。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"常に支援が必要な方がいるときに伺うような感じに受け取ったのですけれども、そういう支援が必要な方がいるかどうかということも見ながら、あとは助言などをした子どもがどう改善するかといったところも見ていらっしゃるということか尋ねました。","respondent":"大関教育総合支援センター長","answer":"学習支援員のように、個別に１人のお子さんの支援に直接携わるのではなくて、学習の様子を見ながら、支援を受けている、あるいは配慮を受けているお子さんに関する情報を精査したり、あるいは担任にアドバイスしているといった立場です。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"いることがわかっていて行くということなのか、それとも、定期的に行って、支援が必要な子がいたら、そういう助言をするということなのかを伺いたかったのです。","respondent":"大関教育総合支援センター長","answer":"何らかの支援、ないに関わりなく、２週に１日は必ず行くという形をとっております。朝から夕方までいます。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"定期的に伺っているということで、やはりそういったところで今回、頻度を増やしてほしいということで出ているわけです。そういった中で先生が対応していくために、より巡回を増やしていく必要があるのかなと思うのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"複数の支援内容をうまく活用しながら、重層的に行っていく、学校の支援をしているのが本区の特別支援教育の特徴です。さまざまな立場から学校を支えていくということが重要だと思いますので、引き続き、現状を充実させてまいりたいと現段階では考えております。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どもがどういう子かということがわかってくるということで、今回、週１回から増やすようにということで求められています。子どもに対応した的確な助言や支援をしていくことができるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"特別支援だけに特化せずに、カウンセラーという立場で週１回、学校に常駐しています。なお、この週１日のカウンセラー業務の中で得た情報をもとに、実際に教育相談室にカウンセリングにお越しいただくというケースが多くなってあります。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、区の考え方としては、このスクールカウンセラーのところは、最初に情報をキャッチして、教育相談室につなげる役割という捉え方なのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"毎週、そこは現実にさまざまなスタッフ、学校全体には養護教員もいます。あるいは特別支援教育係の中には、直接チーフが学校に行って支援にあたるなど、複層的に対応しています。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"スクールカウンセラーも、配置日数を増やしていってほしいと求めました。やはり、このインクルーシブ教育を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"筒井委員","kind":"確認","question":"最初のほうの陳述の事実確認ということになってくるかなと思っているのですけれども、「気軽に相談できるイメージがないということが起きています」。そうしたことが書かれているのですけれども、書かれていることに対して、品川区としてはどういう認識なのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"１００かゼロかではなくて、やはり話し合いの継続、よりよい方向を目指すのが大切だと考えております。特別な配慮の必要なお子さんであれば、そのような形をとるなどして、とにかく丁寧に進めていくのが大切だと考えております。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問","question":"今回の陳情は個人お一人の方なのですけれども、ほかにもそうした希望の係をやらせてもらえないとか、スクールカウンセラーの配置が週１日だから、それで子どもが混乱しているとか、他の方からそうした苦情のお声はあるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"もう既に教育総合支援センターとしても受けてきて、あるいは電話連絡等で情報をいただいて共通理解をして、齟齬のないような努力はしています。努力をしている最中ですので、ご理解いただければと思います。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"最後に１点。先ほども少しお話があったかもしれませんが、支援の必要な子が外に飛び出してしまった場合の対応を、現状、どうされているのか、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"基本的には、非常に安全配慮が必要なお子さんの学校には、区として支援員を配置させていただいたりしています。危険のないような対応の仕方をご家庭ごとにケース会議等に基づいた内容の共通理解を校内体制全体で図っているところです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"陳情者の方のお話を聞いて、廊下で放置されていたというお話も聞いています。逃げ込むような場所、落ちつくような場所を確保していくということは必要なのではないかと思いますけれども、そのお考えを伺えればと思います。","respondent":"大関教育総合支援センター長","answer":"クールダウンする場所は必要だということは、教育委員会も同じ認識で、全教員に伝えております。今後、どうしていくべきかという部分は、関係者含めてケース会議等でしっかりと丁寧に検討を進めるのが基本だと考えております。","id":"exchange-060"},{"speaker":"横山委員","kind":"質問・要望","question":"教育委員会として、総合的にしっかりと進めていただきたいということを要望させていただきたいと思っています。ただし、インクルーシブ教育を総合的にしっかりと進めていただくよう、どうぞお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"芹澤副委員長","kind":"意見","question":"まず、品川区ではインクルーシブ教育をやっていないというスタートになっていますが、品川区では既にしっかりと実践しているという認識があります。そこは教育委員会でさまざま議論、研究を進めていただいて、さらなる拡充をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"塚本委員","kind":"質問・要望","question":"ある種もっと充実していただきたいとか、ここはどうだったのだろうかということについて、個別にいろいろな問題があるということは承知しております。陳情という形で個別にもっと充実してほしい、もっとこうしてほしいということになってくると、不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問・要望","question":"事実確認もなかなかできない状況でして、そういった意味では、こうした陳情項目を並べられているところが賛同できないということで、不採択とします。この陳情者のご不満解消、そして、ご理解いただけるような丁寧な対応を引き続き行っていただきたいと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういったところから、この項目に対しては、十分対応していると判断しております。配慮を払いながら、理解をいただき、こういった陳情のお気持ちの方が出てきてしまわないように進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"せお委員","kind":"質問・要望","question":"それと療育というところの違いがありましたら、教えてほしいと求めました。その２点、お願いいたします。","respondent":"佐藤保育課長","answer":"療育は、医師の指示のもと、児童に合わせた医療面の支援を医師等が療育施設で行うものと認識しております。配慮を行う保育活動と認識しておりまして、各施設の設置目的、従事する職員の資格や支援内容等に違いがあると考えております。","id":"exchange-066"},{"speaker":"せお委員","kind":"質問","question":"そうしますと、例えば療育と特別支援保育となりますと、公立園と私立園で、考え方として違いがあったりしますか尋ねました。","respondent":"佐藤保育課長","answer":"特別支援に対する公立、特別支援児の対応は、私立園にもお伝えしています。保育の延長線上で子どもの健やかな発達につながる支援、今後も引き続き、そういった支援の拡充につながるように頑張っていきたいと考えております。","id":"exchange-067"},{"speaker":"せお委員","kind":"質問・要望","question":"質問が変わりまして、どれにおいても、小学校から中学校に向けて人数が減るのです。それは、どのような理由が考えられると思いますか。","respondent":"大関教育総合支援センター長","answer":"自分だけで２できるようになっていくというふうに進めていこうと品川区の特別支援教育は考えておりますので、自立していくという部分があります。特別支援学級ではなく、支援が必要だったお子さんが１年間、固定学級に移られるというケースもあります。","id":"exchange-068"},{"speaker":"せお委員","kind":"質問","question":"１点だけ。どこにも通えていないというか、どこからも学習を受けられていないようなお子さんは品川区にいらっしゃいますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"教育相談という形でさいかち学級に大体１日５、６人の子どもが来て、特別な配慮をさせていただいているところです。都立特別支援学校、光明特別支援学校から訪問教育も受けられるようになっておりますので、何らかの形で入院中も学習ができるという状況にあります。","id":"exchange-069"},{"speaker":"せお委員","kind":"質問","question":"在宅医療をしている子など、全然通えていない子は把握できていたりしますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"そういった状況になった時点で、都立特別支援学校に籍を移して、その形で都立特別支援学校の教員が訪問指導を行っております。それも、また個別のケースで柔軟に対応したいと考えております。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"就学前の子どものための特別支援の巡回相談を行う人材名のところでお伺いしたいのです。臨床心理士、学校心理士と３つの資格があるのですけれども、巡回の相手先ややり方の使い分けの考え方があるのかということについてもお伺いします。","respondent":"佐藤保育課長","answer":"嘱託医１名、臨床心理士１名、臨床発達心理士１名、学校心理士１名〔同日後刻に「４名」と答弁訂正あり〕です。学校心理士に関しましては、就学に向けた相談をやっていただいておりますので、広く公私立の各施設を回っていただいているです。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問","question":"それぞれ１人ということで、嘱託医は多分、普段どこかでお医者さんをやられているのだと思うのです。ほかの３つの資格の方は、通常はどういうところに属しているというか、巡回相談以外にどういうところで仕事をされている方かを説明を求めました。","respondent":"佐藤保育課長","answer":"臨床発達心理士の方は、自分でＮＰＯを立ち上げて、特別支援に関する発達の相談の講演などをされております。子育て等々あるので、時間の余裕があるところで、品川区に貢献していただいているところです。","id":"exchange-072"},{"speaker":"塚本委員","kind":"意見","question":"やはり年々増えてきていて、平成３０年度１２人に対して、令和元年度では１０月末時点で既に２０名ということです。十分なリソースという言い方が正しいかどうかわからないけれども、あるのか、やや人がいなくて探さなければいけない状況にあるのかとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"実際に業務委託を区内のＮＰＯにお願いしておりますので、ＮＰＯのほうで必要な人材教育はしていただいています。今年度より、中学生段階のいろいろな学習上の支援の研究に非常に詳しいスタッフを新たに迎えたと聞いておりますので。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問・要望","question":"あるいは、それは個人で進めるということではなくて、保育課なりが１回集約して対応していくのか。詳しく教えていただきたいと思うのです。","respondent":"佐藤保育課長","answer":"１点、答弁の訂正をさせていただいていいですか。先ほど、学校心理士を１名と答えたようなのですけれども、４名です。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこの連携が少しうまくいかないと、早期発見、早期導入につながらないところが出てしまうといけないと思うのです。その辺りの連携について、最後に確認をさせてほしいと求めました。","respondent":"佐藤保育課長","answer":"私ども保育課で対応するのは２つのパターンがあります。基本的に療育支援ネットワークという庁内の情報共有の場がありますので、効果的に情報共有や事業内容の理解に努めているということです。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"もちろん、できるだけ多くの私立幼稚園にも行けるような形式で行われているかどうか、確認が１つです。一般質問でもお伺いしたところでもあるのですが、先ほど、それだけで情報が小学校のほうに行っているのかということです。","respondent":"大澤保育支援課長、大関教育総合支援センター長","answer":"私から私立幼稚園の巡回相談についてご説明します。幼稚園に必要性を聞いて、必ずしも全園で使っているわけではないのですが、全園で手を挙げていただいても回れるだけの回数分の計画はしています。 １点目の就学相談のメンバー、この療育支援ネットワークの図に出てくるそれぞれの関係機関とどう連携を進めているかという部分です。という形で、各校の校長から“うちの学校には特別支援教室があって…","id":"exchange-076"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今後、そういった教室のことは、教育委員会としても十分注視していってほしいと求めました。ご本人にとっていい形になるように、教育委員会として見られる範囲で結構ですので、注視していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"就学前のところで、特別支援保育推進チームの設置をされているということで、これは各園に設置をしているのでしょうか。人数といったところを少しご説明ほしいと求めました。","respondent":"佐藤保育課長","answer":"特別支援保育推進チームですが、今年度から区立保育園各園で１名の中堅保育士をリーダーと定めて実施しているところです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"それを各園でやられているということで、そうすると、メンバーは何人ぐらいの体制でそれぞれ意見交換して、対応を考えていくということになるのか。特別支援に特化したというか、専門性をもった人が中堅のリーダーになるという形になるのか尋ねました。","respondent":"佐藤保育課長","answer":"人数は、４３園ありますので、４３名です。各園１人ずつです。","id":"exchange-079"},{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、４３人いらっしゃるというのは、チームとしては４３園分あるということでいいのですか。チームが４３人です、というと、４３人のチームなのかと感じてしまうのですけれども、そこの確認です。","respondent":"佐藤保育課長","answer":"説明が悪くてすみません。４３園で、各園ごとに１チームといいますか、１つの体制でやっているということです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"そういったチーム体制でやられているということで、今年度から始めたということなのですが、始めるきっかけ、背景を伺えればと思います。どういった仕組みで、実際のケースを検討していくにあたって、どういうスキーム、形でやられるのか伺いたいと思います。","respondent":"佐藤保育課長","answer":"こういった特別支援に対する研修というのは、先ほどご答弁したとおり１０年経っていまして、こういったチームを立ち上げているところです。各特別支援児に関する個別指導計画というものをＰＤＣＡで回していくのですけれども、見直して、健全な発達につなげていくというところで…","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"行事のみの場合もあるというお話だったので、そこも要因だとは思うのですが、ほかに背景などがあったら伺いたいと思います。学習支援員と介助員というのは、何人ぐらいいらっしゃるのか伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"区としてはこちらの表に載っている人数が支援の必要なお子さんということで、行事だけであったり、あるいは中には週１日だけというお子さんもいます。あるいは学校に何時間という形で… すみません。子どもが年々増えていると同時に、やはりそれだけ特別支援教育に対する理解と期待が両方とも高まってきたと受けとめております。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"随時派遣していただくということで、そういった処遇改善も充実させていくということで、この特別支援の充実を図られていくところもあると思います。そういった面でも、考えていってほしいと求めましたが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"私どもも委託の単価に反映させる方向で、この数年、努力してまいりました。今後につきましても、引き続きそういった部分は財政部門のほうに相談して進めていきたいと考えています。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問","question":"幾つかお伺いしてまいります。例えば、研修に関して、連携の状況がもし何かございましたら、教えていただけたらと思います。","respondent":"佐藤保育課長、大関教育総合支援センター長","answer":"まさに公立園は自分たちでやろうということで、特別支援保育推進チームを立ち上げているところです。私立園にもさまざまな研修を開催しますし、相談も行っていって、力を伸ばしていきたいと考えております。 これからも依頼があれば学校のほうも連携して、可能な範囲で同じく学校に通う子どもたちへの対応ですので、やっております。普段、あるいは週１回の（校内）委員会での情報共有に責任者の方に入っていただいたり…","id":"exchange-084"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それは、手続上、そういったこともあるかもしれませんが、これについて、今後、調査などはやっていかないのかどうかということ。実際にそういった事例をつかんでいるのかというところを伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/211588?Template=document&Id=4986#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":49803,"voices":245}}]);
